import React, { Component } from "react";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import workItemUtils from "_helpers/workitem.utils";
import LuxListRowMenuPortal from "views/common/fragments/LuxListRowMenuPortal";
import {
  getWorkItemStatusMeta,
  getWorkItemPriorityMeta,
} from "./workItemActivity.utils";
import {
  getWorkItemChecklistMeta,
  getWorkItemHoursMeta,
  formatWorkItemOwner,
  getWorkItemOwnerInitial,
} from "./workItemList.utils";

class WorkItemListRow extends Component {
  constructor(props) {
    super(props);
    this.state = { menuOpen: false, confirmRemove: false };
    this.rowRef = React.createRef();
    this.menuTriggerRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.menuOpen) return;
    if (event.target.closest(".lux-list-row-menu-portal")) return;
    if (this.rowRef.current && !this.rowRef.current.contains(event.target)) {
      this.setState({ menuOpen: false, confirmRemove: false });
    }
  };

  toggleMenu = (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.setState((prev) => ({ menuOpen: !prev.menuOpen, confirmRemove: false }));
  };

  closeMenu = () => this.setState({ menuOpen: false, confirmRemove: false });

  runMenuAction = (handler) => (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.closeMenu();
    if (handler) handler();
  };

  stopRowClick = (event) => {
    event.preventDefault();
    event.stopPropagation();
  };

  handleRemove = () => {
    if (this.state.confirmRemove) {
      this.props.handleRemoveWorkItem(this.props.item.id);
      this.setState({ confirmRemove: false, menuOpen: false });
      return;
    }
    this.setState({ confirmRemove: true });
  };

  isDeleteByHoursEnabled = () => {
    const { item, permission } = this.props;
    if (!item) return false;
    const hours = parseInt(permission.enableWorkItemDeleteTillNextDayXHour || 0, 10);
    return workItemUtils.isWorkItemEditActive(item.actualStartTime, hours);
  };

  renderMenuItem = (item) => (
    <button
      key={item.key}
      type="button"
      className={classNames("lux-emp-card__menu-item", item.tone && `is-${item.tone}`)}
      role="menuitem"
      onClick={this.runMenuAction(item.onClick)}
    >
      <span className={classNames("lux-emp-card__menu-icon", item.tone && `is-${item.tone}`)}>
        <i className={item.icon} aria-hidden="true" />
      </span>
      <span className="lux-emp-card__menu-copy">
        <strong>{item.label}</strong>
      </span>
    </button>
  );

  getMenuSections = () => {
    const { item, permission } = this.props;
    const primary = [
      {
        key: "view",
        icon: "fe fe-eye",
        label: "View details",
        onClick: () => this.props.onOpenDetail(item),
      },
    ];
    if (permission.editEnabled) {
      primary.push({
        key: "edit",
        icon: "fe fe-edit-2",
        label: "Edit work item",
        onClick: () => this.props.handleEditWorkItem(item.id),
      });
    }
    if (
      permission.checklistEnabled &&
      (item.taskType === "PROJECT" || item.taskType === "NON_PROJECT")
    ) {
      primary.push({
        key: "checklist",
        icon: "fa fa-wpforms",
        label: "Open checklist",
        onClick: () => this.props.onCheklistItemClick && this.props.onCheklistItemClick(item),
      });
    }

    const secondary = [];
    if (permission.deleteEnabled || this.isDeleteByHoursEnabled()) {
      secondary.push({
        key: "delete",
        icon: item.deleted ? "fe fe-rotate-ccw" : "fe fe-trash-2",
        label: item.deleted ? "Undo delete" : "Delete",
        tone: "danger",
        onClick: () => this.props.handleDeleteWorkItem(item.id, !item.deleted),
      });
    }
    if (permission.removeEnabled) {
      secondary.push({
        key: "remove",
        icon: this.state.confirmRemove ? "fe fe-check" : "fe fe-x",
        label: this.state.confirmRemove ? "Confirm remove" : "Remove permanently",
        tone: "danger",
        onClick: this.handleRemove,
      });
    }
    return { primary, secondary };
  };

  handleRowActivate = () => {
    if (this.props.onOpenDetail) {
      this.props.onOpenDetail(this.props.item);
    }
  };

  handleRowKeyDown = (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      this.handleRowActivate();
    }
  };

  render() {
    const { item, permission } = this.props;
    const { menuOpen } = this.state;
    const statusMeta = getWorkItemStatusMeta(item.status);
    const priorityMeta = getWorkItemPriorityMeta(item.taskPriority);
    const hoursMeta = getWorkItemHoursMeta(item);
    const checklistMeta = getWorkItemChecklistMeta(item.checklistStatus, item.checklistData);
    const { primary, secondary } = this.getMenuSections();
    const ownerName = formatWorkItemOwner(item);

    return (
      <article
        ref={this.rowRef}
        className={classNames("lux-bid-list__item lux-workitem-row", {
          "is-deleted": item.deleted,
          "is-menu-open": menuOpen,
          [`is-status-${statusMeta.tone}`]: true,
        })}
        role="listitem"
      >
        <span className="lux-bid-list__accent" aria-hidden="true" />

        <div className="lux-bid-list__col lux-bid-list__col--index">
          <span className="lux-workitem-row__index">{this.props.rowIndex}</span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--id">
          <span className="lux-bid-list__ref">{item.itemIdUserTeamPrefix}</span>
        </div>

        <div
          className="lux-bid-list__col lux-bid-list__col--name lux-workitem-row__name-col is-clickable"
          role="button"
          tabIndex={0}
          onClick={this.handleRowActivate}
          onKeyDown={this.handleRowKeyDown}
          aria-label={`View ${item.name}`}
        >
          <span className="lux-workitem-row__name" title={item.name}>
            <span className="lux-workitem-row__name-text">{item.name}</span>
            <i className="fe fe-arrow-up-right" aria-hidden="true" />
          </span>
          <div className="lux-workitem-row__tags">
            <span className={classNames("lux-workitem-row__prio", `is-${priorityMeta.tone}`)}>
              {priorityMeta.label}
            </span>
            {item.deleted && (
              <span className="lux-bid-list__deleted-badge">
                <i className="fe fe-trash-2" aria-hidden="true" />
                Deleted
              </span>
            )}
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--category">
          <span className="lux-workitem-row__category">{item.taskActCategory || "Other"}</span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--owner">
          <div className="lux-workitem-row__owner" title={ownerName}>
            <span className="lux-workitem-row__owner-avatar">{getWorkItemOwnerInitial(item)}</span>
            <span className="lux-workitem-row__owner-name">{ownerName}</span>
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--dates">
          <div className="lux-workitem-row__dates">
            <span className="lux-workitem-row__date">
              <em>Start</em>
              {dateUtils.convertDateTimeFormat(item.actualStartTime || item.estStartTime) || "—"}
            </span>
            {item.estCompletionTime && (
              <span className="lux-workitem-row__date is-due">
                <em>Due</em>
                {dateUtils.convertDateFormat(item.estCompletionTime)}
              </span>
            )}
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--hours">
          <div className={classNames("lux-workitem-row__hours", `is-${hoursMeta.tone}`)}>
            <span className="lux-workitem-row__hours-label">{hoursMeta.label}</span>
            <strong>{hoursMeta.value}</strong>
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--checklist is-center">
          <span
            className={classNames("lux-workitem-row__checklist", `is-${checklistMeta.tone}`)}
            title={checklistMeta.label}
          >
            <i className={checklistMeta.icon} aria-hidden="true" />
            {checklistMeta.label}
          </span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--status is-center">
          <span
            className={classNames("lux-workitem-row__status", `is-${statusMeta.tone}`)}
            title={statusMeta.label}
          >
            <i
              className={classNames(statusMeta.icon, { spin: statusMeta.spin })}
              aria-hidden="true"
            />
            {statusMeta.label}
          </span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--actions is-center">
          <button
            ref={this.menuTriggerRef}
            type="button"
            className="lux-bid-list__menu-btn"
            aria-label="Row actions"
            aria-haspopup="menu"
            aria-expanded={menuOpen}
            onClick={this.toggleMenu}
          >
            <i className="fe fe-more-vertical" aria-hidden="true" />
          </button>
          <LuxListRowMenuPortal
            open={menuOpen}
            triggerRef={this.menuTriggerRef}
            onClose={this.closeMenu}
            primary={primary}
            secondary={secondary}
            renderItem={this.renderMenuItem}
          />
        </div>
      </article>
    );
  }
}

export default WorkItemListRow;
