import React, { Component } from "react";
import { connect } from "react-redux";
import { employeeActions } from "_actions";
import { employeeConstants } from "_constants";
import { accessUtils } from "_helpers";
import { commonUtils, store } from "_helpers";
import { validationUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import PageInnerHeader from "views/common/PageInnerHeader";
import AttendancePageSummary from "./components/attendance/AttendancePageSummary";
import AttendanceCurrentUserPanel from "./components/attendance/AttendanceCurrentUserPanel";
import AttendanceMatrix from "./components/attendance/AttendanceMatrix";
import AttendanceMarkPopover from "./components/attendance/AttendanceMarkPopover";
import AttendanceDetailsPopover from "./components/attendance/AttendanceDetailsPopover";
import {
  buildAttendanceSummary,
  buildAttendanceDashboard,
  findCurrentUserEmployee,
  getEmployeeStats,
  sortEmployeesCurrentFirst,
  filterEmployeesById,
} from "./components/attendance/attendance.utils";
import AttendanceEmployeeFilter from "./components/attendance/AttendanceEmployeeFilter";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

class AttendancePage extends Component {
  constructor() {
    super();
    this.state = {
      selectedDate: dateUtils.convertDateToMoment(new Date()),
      monthDays: [],
      permission: accessUtils.getEmployeeAttendanceAccessControl(),
      markPopover: null,
      detailsPopover: null,
      selectedEmployeeId: null,
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    this.refreshMonthDates(this.state.selectedDate);
    const userTeams = commonUtils.getUserTeams(this.props.userTeams);
    store.dispatch({
      type: employeeConstants.INITIALIZE_EMPLOYEE_ATTENDANCE_USER_TEAMS,
      userTeams,
    });
    if (!this.props.employees) {
      this.reloadEmployeeItems(userTeams);
    }
    this.getTeamsAttendance(userTeams);
    this.setState({ permission: accessUtils.getEmployeeAttendanceAccessControl() });
  }

  refreshMonthDates = (date) => {
    this.setState(
      {
        selectedDate: date,
        monthDays: dateUtils.getDaysArrayByMonth(date),
      },
      () => this.getTeamsAttendance(commonUtils.getUserTeams(this.props.userTeams))
    );
  };

  handleFilterChange = (filterOptions) => {
    store.dispatch({
      type: employeeConstants.CHANGE_FILTER_EMPLOYEES_ATTENDANCE,
      filterOptions,
    });
  };

  handleUserTeamsSelection = (userTeams) => {
    store.dispatch({
      type: employeeConstants.INITIALIZE_EMPLOYEE_ATTENDANCE_USER_TEAMS,
      userTeams,
    });
    this.setState({ selectedEmployeeId: null });
    this.reloadEmployeeItems(userTeams);
    this.getTeamsAttendance(userTeams);
  };

  reloadEmployeeItems = (userTeams) => {
    const selectedUserTeams = [];
    userTeams &&
      userTeams.forEach((userTeam) => {
        if (userTeam.isChecked) selectedUserTeams.push(userTeam.id);
      });
    if (selectedUserTeams.length > 0) {
      store.dispatch(
        this.props.getTeamsEmployees(selectedUserTeams, this.props.filterOptions || {})
      );
    }
  };

  handleEmployeeFilterChange = (employeeId) => {
    this.setState({ selectedEmployeeId: employeeId });
  };

  onFilterTextChange = (value) => {
    const isValidChar = validationUtils.validateAlphaNumbericWithSpecial(value);
    if (!isValidChar) return;

    const filterOptions = {
      ...(this.props.filterOptions || {}),
      filterText: value,
    };
    this.handleFilterChange(filterOptions);
  };

  goToNext = () => {
    this.refreshMonthDates(this.state.selectedDate.clone().add(1, "months"));
  };

  goToBack = () => {
    this.refreshMonthDates(this.state.selectedDate.clone().subtract(1, "months"));
  };

  goToCurrent = () => {
    this.refreshMonthDates(dateUtils.getCurrentTime());
  };

  getTeamsAttendance = (userTeams) => {
    const range = dateUtils.getFirstAndLastDayofMonth(this.state.selectedDate);
    const startDate = range[0];
    const endDate = range[1];
    const selectedUserTeams = [];
    userTeams &&
      userTeams.forEach((userTeam) => {
        if (userTeam.isChecked) selectedUserTeams.push(userTeam.id);
      });
    if (selectedUserTeams.length > 0) {
      store.dispatch(
        this.props.getTeamsAttendance({
          userTeamIds: selectedUserTeams,
          startDate: startDate.format(dateUtils.SERVER_DATE_FORMAT),
          endDate: endDate.format(dateUtils.SERVER_DATE_FORMAT),
        })
      );
    }
  };

  createAttendance = (request) => {
    store.dispatch(this.props.createAttendance(request));
  };

  deleteAttendance = (id) => {
    store.dispatch(this.props.deleteAttendance({ id }));
  };

  openMarkPopover = (employeeId, employeeName, markDate) => {
    this.setState({
      markPopover: { employeeId, employeeName, markDate },
      detailsPopover: null,
    });
  };

  closeMarkPopover = () => {
    this.setState({ markPopover: null });
  };

  openDetailsPopover = (employeeId, employeeName, markDate, item) => {
    this.setState({
      detailsPopover: { employeeId, employeeName, markDate, item },
      markPopover: null,
    });
  };

  closeDetailsPopover = () => {
    this.setState({ detailsPopover: null });
  };

  unmarkAttendance = (attendanceId) => {
    this.deleteAttendance(attendanceId);
    this.closeDetailsPopover();
  };

  submitMarkAttendance = (details) => {
    const { markPopover } = this.state;
    if (!markPopover) return;

    this.createAttendance({
      employeeId: markPopover.employeeId,
      markDate: details.markDate,
      markTime: details.markTime,
      hours: details.hours,
      checkoutTime: details.checkoutTime,
    });
    this.closeMarkPopover();
  };

  render() {
    const { employees, items, isLoading, filterOptions, userTeams } = this.props;
    const { monthDays, permission, markPopover, detailsPopover, selectedEmployeeId } = this.state;
    const currentUserId = commonUtils.getCurrentUserId();
    const employeeFilterList = sortEmployeesCurrentFirst(
      this.props.allEmployees || employees,
      currentUserId
    );
    const sortedEmployees = filterEmployeesById(
      sortEmployeesCurrentFirst(employees, currentUserId),
      selectedEmployeeId
    );
    const currentUserEmployee = findCurrentUserEmployee(employees, currentUserId);
    const focusEmployee =
      selectedEmployeeId != null
        ? (employeeFilterList || []).find(
            (emp) => String(emp.id) === String(selectedEmployeeId)
          )
        : currentUserEmployee;
    const focusStats =
      focusEmployee && getEmployeeStats(focusEmployee.id, items, monthDays);
    const isViewingSelf =
      !focusEmployee || String(focusEmployee.id) === String(currentUserId);
    const summaryStat = buildAttendanceSummary(
      sortedEmployees,
      items,
      monthDays,
      this.state.selectedDate
    );
    const dashboard = buildAttendanceDashboard(
      sortedEmployees,
      items,
      monthDays,
      currentUserId
    );
    const hasData = (employees && employees.length > 0) || isLoading;

    return (
      <div className="lux-attendance">
        <PageInnerHeader
          userTeams={userTeams}
          handleUserTeamsSelection={this.handleUserTeamsSelection}
          showUserTeamMenu={true}
          showFilter={true}
          isLoading={isLoading}
          permission={permission}
          filterOptions={filterOptions || { filterText: null }}
          onFilterTextChange={this.onFilterTextChange}
          employeeFilterSlot={
            employeeFilterList && employeeFilterList.length > 0 ? (
              <AttendanceEmployeeFilter
                variant="header"
                employees={employeeFilterList}
                selectedEmployeeId={selectedEmployeeId}
                onChange={this.handleEmployeeFilterChange}
                isLoading={isLoading}
              />
            ) : null
          }
        />

        <AttendancePageSummary
          stat={summaryStat}
          dashboard={dashboard}
          isLoading={isLoading && !employees}
          calendarControls={{
            goToBack: this.goToBack,
            goToCurrent: this.goToCurrent,
            goToNext: this.goToNext,
          }}
          calendarDisabled={isLoading}
        />

        {focusEmployee && focusStats && !isLoading && (
          <AttendanceCurrentUserPanel
            employee={focusEmployee}
            stats={focusStats}
            monthDays={monthDays}
            items={items}
            permission={permission}
            isLoading={isLoading}
            isViewingSelf={isViewingSelf}
            createAttendance={this.createAttendance}
            deleteAttendance={this.deleteAttendance}
            onRequestMark={this.openMarkPopover}
            onRequestViewDetails={this.openDetailsPopover}
          />
        )}

        {hasData && (
          <AttendanceMatrix
            employees={sortedEmployees}
            monthDays={monthDays}
            items={items}
            permission={permission}
            isLoading={isLoading}
            currentUserId={currentUserId}
            createAttendance={this.createAttendance}
            deleteAttendance={this.deleteAttendance}
            onRequestMark={this.openMarkPopover}
            onRequestViewDetails={this.openDetailsPopover}
            employeeFilterEmployees={employeeFilterList}
            selectedEmployeeId={selectedEmployeeId}
            onEmployeeFilterChange={this.handleEmployeeFilterChange}
          />
        )}

        {hasData && sortedEmployees && sortedEmployees.length === 0 && !isLoading && (
          <div className="lux-attendance-empty lux-attendance-empty--filter">
            <i className="fe fe-user" aria-hidden="true" />
            <span>No employee matches this filter</span>
            <p>Choose another employee or select &ldquo;All employees&rdquo; to see the full list.</p>
          </div>
        )}

        <AttendanceMarkPopover
          show={!!markPopover}
          employeeId={markPopover && markPopover.employeeId}
          employeeName={markPopover && markPopover.employeeName}
          markDate={markPopover && markPopover.markDate}
          isLoading={isLoading}
          onClose={this.closeMarkPopover}
          onSubmit={this.submitMarkAttendance}
        />

        <AttendanceDetailsPopover
          show={!!detailsPopover}
          employeeName={detailsPopover && detailsPopover.employeeName}
          markDate={detailsPopover && detailsPopover.markDate}
          attendanceItem={detailsPopover && detailsPopover.item}
          isLoading={isLoading}
          canUnmark={permission && permission.deleteEnabled === true}
          onClose={this.closeDetailsPopover}
          onUnmark={this.unmarkAttendance}
        />

        {!hasData && !isLoading && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-attendance-empty"
            variant="attendance"
            eyebrow="Team roster"
            title="No employees in selected teams"
            description="Select one or more teams in the header to load attendance for this month."
            hints={[
              "Employees must be active members of the selected teams",
              "Clear employee filters to see the full roster",
              "Switch teams if you manage multiple groups",
            ]}
          />
        )}
      </div>
    );
  }
}

const mapStateToProps = (state) => {
  const allEmployees =
    state.employees.teamEmployees &&
    commonUtils.getActiveEmployees(state.employees.teamEmployees);

  return {
    allEmployees,
    employees: commonUtils.filterEmployees(allEmployees, state.employees.filterOptionsA),
    isLoading: state.employees.attendanceLoading,
    items: state.employees.attendanceItems,
    filterOptions: state.employees.filterOptionsA,
    userTeams: commonUtils.getUserTeams(state.employees.userTeamsA),
  };
};

const mapDispatchToProps = () => ({
  getTeamsEmployees: employeeActions.getTeamsEmployees,
  getTeamsAttendance: employeeActions.getTeamsAttendance,
  createAttendance: employeeActions.createAttendance,
  deleteAttendance: employeeActions.deleteAttendance,
});

export default connect(mapStateToProps, mapDispatchToProps)(AttendancePage);
