import React, { useMemo, useState } from "react";
import classNames from "classnames/bind";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import {
  buildAssignPanelDailyLoadChart,
  buildAssignPanelProjectChart,
  buildAssignPanelStatusDonutChart,
  buildAssignPanelTaskTypeChart,
} from "../plannerSummary.charts";
import { UTIL_TONES } from "../plannerAnalytics.utils";
import { readPlannerPrefs, writePlannerPrefs } from "../planner.storage";

function readAssignSummaryExpanded() {
  const prefs = readPlannerPrefs();
  return prefs.assignSummaryExpanded !== false;
}

const CHART_HEIGHT_DAILY = 188;
const CHART_HEIGHT_SECONDARY = 112;

function ChartEmpty({ message }) {
  return (
    <div className="lux-planner-assign-summary__chart-empty" role="status">
      {message}
    </div>
  );
}

function SummaryToolbarButton({ label, iconClass, onClick, ariaExpanded, ariaControls }) {
  return (
    <button
      type="button"
      className="lux-planner-btn lux-planner-btn--ghost lux-planner-assign-summary__charts-btn lux-planner-assign-summary__charts-btn--sm"
      onClick={onClick}
      aria-expanded={ariaExpanded}
      aria-controls={ariaControls}
    >
      <i className={classNames("fe", iconClass)} aria-hidden />
      {label}
    </button>
  );
}

function ChartToggleButton({ expanded, onClick, controlsId, hideLabel, showLabel, iconClass }) {
  return (
    <SummaryToolbarButton
      label={expanded ? hideLabel : showLabel}
      iconClass={iconClass}
      onClick={onClick}
      ariaExpanded={expanded}
      ariaControls={controlsId}
    />
  );
}

export default function PlannerAssignEmployeeInsight({ context, rangeLabel }) {
  const [summaryExpanded, setSummaryExpanded] = useState(readAssignSummaryExpanded);

  const persistSummaryExpanded = (expanded) => {
    setSummaryExpanded(expanded);
    writePlannerPrefs({ assignSummaryExpanded: expanded });
  };
  const [dailyChartExpanded, setDailyChartExpanded] = useState(true);
  const [secondaryChartsExpanded, setSecondaryChartsExpanded] = useState(true);

  const dailyChart = useMemo(
    () =>
      context && context.dailyLoad.length
        ? buildAssignPanelDailyLoadChart(context.dailyLoad)
        : null,
    [context]
  );

  const statusChart = useMemo(() => {
    if (!context || !Object.keys(context.statusCounts).length) return null;
    return buildAssignPanelStatusDonutChart(context.statusCounts);
  }, [context]);

  const projectChart = useMemo(() => {
    if (!context || !context.projects.length) return null;
    return buildAssignPanelProjectChart(context.projects, 4);
  }, [context]);

  const taskTypeChart = useMemo(() => {
    if (!context || !context.taskTypeMinutes) return null;
    return buildAssignPanelTaskTypeChart(context.taskTypeMinutes);
  }, [context]);

  if (!context) {
    return (
      <header className="lux-planner-assign-summary lux-planner-assign-summary--empty">
        <div className="lux-planner-assign-summary__placeholder">
          <i className="fe fe-users" aria-hidden />
          <strong>Select a team member</strong>
          <span>Choose someone in the form to see capacity summary and existing assignments.</span>
        </div>
      </header>
    );
  }

  const { employee, tone } = context;
  const toneMeta = UTIL_TONES[tone] || UTIL_TONES.available;
  const capacityHint =
    context.overbookedDays > 0
      ? `${context.overbookedDays} overbooked day(s)`
      : "Within capacity";

  return (
    <header
      className={classNames("lux-planner-assign-summary", {
        "is-summary-expanded": summaryExpanded,
        "is-summary-collapsed": !summaryExpanded,
        "is-daily-chart-expanded": summaryExpanded && dailyChartExpanded,
        "is-daily-chart-collapsed": summaryExpanded && !dailyChartExpanded,
        "is-secondary-charts-expanded": summaryExpanded && secondaryChartsExpanded,
        "is-secondary-charts-collapsed": summaryExpanded && !secondaryChartsExpanded,
      })}
    >
      {!summaryExpanded ? (
        <div
          id="planner-assign-summary-body"
          className="lux-planner-assign-summary__compact"
          aria-label={`${employee.name} capacity summary`}
        >
          <div className="lux-planner-assign-summary__compact-head">
            <span className="lux-planner-assign-insight__avatar lux-planner-assign-insight__avatar--sm">
              {(employee.name || "?").charAt(0).toUpperCase()}
            </span>
            <div className="lux-planner-assign-summary__compact-main">
              <strong>{employee.name}</strong>
              <span className="lux-planner-assign-summary__compact-meta">
                {rangeLabel || "Planning range"}
                <span className="lux-planner-assign-summary__compact-sep">·</span>
                {context.itemCount} assignment{context.itemCount === 1 ? "" : "s"}
                <span className="lux-planner-assign-summary__compact-sep">·</span>
                {context.activeProjects} project{context.activeProjects === 1 ? "" : "s"}
              </span>
            </div>
            <div className="lux-planner-assign-summary__compact-inline">
              <span className={classNames("lux-planner-assign-insight__util is-compact", `is-${tone}`)}>
                {context.horizonUtilization}%
              </span>
              <span
                className={classNames(
                  "lux-planner-assign-summary__chip lux-planner-assign-summary__chip--compact",
                  `is-${tone}`
                )}
                title={`${toneMeta.label} · ${capacityHint}`}
              >
                {toneMeta.label}
              </span>
            </div>
            <div className="lux-planner-assign-summary__summary-toggle">
              <SummaryToolbarButton
                label="Insights"
                iconClass="fe-bar-chart"
                onClick={() => persistSummaryExpanded(true)}
                ariaExpanded={false}
                ariaControls="planner-assign-summary-body"
              />
            </div>
          </div>
        </div>
      ) : (
      <div id="planner-assign-summary-body" className="lux-planner-assign-summary__layout">
        <aside className="lux-planner-assign-summary__identity lux-planner-assign-summary__panel">
          <div className="lux-planner-assign-summary__lead">
            <span className="lux-planner-assign-insight__avatar lux-planner-assign-insight__avatar--sm">
              {(employee.name || "?").charAt(0).toUpperCase()}
            </span>
            <div className="lux-planner-assign-summary__who">
              <h3>{employee.name}</h3>
            </div>
          </div>

          <ul className="lux-planner-assign-summary__meta">
            <li>
              <span>Horizon</span>
              <strong>{rangeLabel || "Planning range"}</strong>
            </li>
            <li>
              <span>Assignments</span>
              <strong>{context.itemCount}</strong>
            </li>
            <li>
              <span>Active projects</span>
              <strong>{context.activeProjects}</strong>
            </li>
          </ul>

          <div className="lux-planner-assign-summary__status">
            <span className={classNames("lux-planner-assign-insight__util", `is-${tone}`)}>
              {context.horizonUtilization}%
              <em>utilized</em>
            </span>
            <span
              className={classNames("lux-planner-assign-summary__chip", `is-${tone}`)}
              title={`${toneMeta.label} · ${capacityHint}`}
            >
              {toneMeta.label}
              <span className="lux-planner-assign-summary__chip-sep">·</span>
              {capacityHint}
            </span>
          </div>
        </aside>

        <div className="lux-planner-assign-summary__analytics">
          <div className="lux-planner-assign-summary__metrics-row">
            <div className="lux-planner-assign-summary__pills" aria-label="Capacity summary">
              <div className="lux-planner-assign-metric lux-planner-assign-metric--pill lux-planner-assign-summary__panel">
                <span>Planned</span>
                <strong>{context.allocatedLabel}</strong>
              </div>
              <div className="lux-planner-assign-metric lux-planner-assign-metric--pill lux-planner-assign-summary__panel">
                <span>Capacity</span>
                <strong>{context.capacityLabel}</strong>
              </div>
              <div className="lux-planner-assign-metric lux-planner-assign-metric--pill is-good lux-planner-assign-summary__panel">
                <span>Free</span>
                <strong>{context.freeLabel}</strong>
              </div>
              <div className="lux-planner-assign-metric lux-planner-assign-metric--pill lux-planner-assign-summary__panel">
                <span>Items</span>
                <strong>{context.itemCount}</strong>
              </div>
            </div>
            <div className="lux-planner-assign-summary__summary-toggle">
              <SummaryToolbarButton
                label="Collapse"
                iconClass="fe-chevron-up"
                onClick={() => persistSummaryExpanded(false)}
                ariaExpanded={true}
                ariaControls="planner-assign-summary-body"
              />
            </div>
          </div>

          <div className="lux-planner-assign-summary__charts-block">
            <div className="lux-planner-assign-summary__chart-head">
              <span className="lux-planner-assign-summary__chart-head-label">Daily load</span>
              <ChartToggleButton
                expanded={dailyChartExpanded}
                onClick={() => setDailyChartExpanded((v) => !v)}
                controlsId="planner-assign-summary-daily-chart"
                hideLabel="Hide daily load"
                showLabel="Show daily load"
                iconClass="fe-trending-up"
              />
            </div>

            {dailyChartExpanded && (
              <section
                id="planner-assign-summary-daily-chart"
                className="lux-planner-assign-insight__chart lux-planner-assign-summary__panel lux-planner-assign-summary__daily"
              >
                <div
                  className="lux-planner-assign-summary__daily-body"
                  style={{ minHeight: CHART_HEIGHT_DAILY, height: CHART_HEIGHT_DAILY }}
                >
                  {dailyChart ? (
                    <DashboardApexChart {...dailyChart} height={CHART_HEIGHT_DAILY} />
                  ) : (
                    <ChartEmpty message="No capacity days in this horizon." />
                  )}
                </div>
              </section>
            )}

            <div className="lux-planner-assign-summary__chart-head">
              <span className="lux-planner-assign-summary__chart-head-label">Breakdown charts</span>
              <ChartToggleButton
                expanded={secondaryChartsExpanded}
                onClick={() => setSecondaryChartsExpanded((v) => !v)}
                controlsId="planner-assign-summary-secondary-charts"
                hideLabel="Hide charts"
                showLabel="Show charts"
                iconClass="fe-bar-chart-2"
              />
            </div>

            {secondaryChartsExpanded && (
              <div
                id="planner-assign-summary-secondary-charts"
                className="lux-planner-assign-summary__charts-secondary"
              >
                <section className="lux-planner-assign-insight__chart lux-planner-assign-summary__panel is-compact">
                  <h4>Task type</h4>
                  {taskTypeChart ? (
                    <DashboardApexChart {...taskTypeChart} height={CHART_HEIGHT_SECONDARY} />
                  ) : (
                    <ChartEmpty message="No billable, non-billable, or leave hours in this horizon." />
                  )}
                </section>

                <section className="lux-planner-assign-insight__chart lux-planner-assign-summary__panel is-compact">
                  <h4>By status</h4>
                  {statusChart ? (
                    <DashboardApexChart {...statusChart} height={CHART_HEIGHT_SECONDARY} />
                  ) : (
                    <ChartEmpty message="No assignments yet — status breakdown appears when work is scheduled." />
                  )}
                </section>

                <section className="lux-planner-assign-insight__chart lux-planner-assign-summary__panel is-compact">
                  <h4>Top projects</h4>
                  {projectChart ? (
                    <DashboardApexChart {...projectChart} height={CHART_HEIGHT_SECONDARY} />
                  ) : (
                    <ChartEmpty message="No project hours in this horizon." />
                  )}
                </section>
              </div>
            )}
          </div>
        </div>
      </div>
      )}
    </header>
  );
}
