import React, { Component } from "react";
import { connect } from "react-redux";
import { accessUtils } from "_helpers";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import TaskDetailsGeneral from "../TaskDetailsGeneral";

class ViewTaskDetailsSidebar extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getTaskAccessControl(),
    };
  }

  render() {
    const { show, onCloseViewTask, taskInfo } = this.props;

    return (
      <LuxCreatePanelShell
        show={show}
        onClose={onCloseViewTask}
        panelId="viewtaskdetailssidebar"
        className="view_task_right_sidebar lux-view-deliverable-panel"
        kicker="Deliverable"
        title="Deliverable details"
        subtitle={
          taskInfo && taskInfo.name
            ? taskInfo.name
            : "View schedule, checklist, and work items"
        }
      >
        {show && taskInfo && (
          <div className="lux-create-panel__scroll lux-view-deliverable-panel__scroll">
            <TaskDetailsGeneral
              item={taskInfo}
              readOnly={true}
              permission={this.state.permission}
            />
          </div>
        )}
      </LuxCreatePanelShell>
    );
  }
}

const mapStateToProps = (state) => ({
  taskInfo: state.tasks.selectedTaskInfo,
  isLoading: state.tasks.loading,
});

export default connect(mapStateToProps)(ViewTaskDetailsSidebar);
