import React, { Component } from "react";
import { connect } from "react-redux";
import LuxCreateModeSwitch from "views/common/create/LuxCreateModeSwitch";
import LuxCreateWizardNav from "views/common/create/LuxCreateWizardNav";
import LuxCreateFooter from "views/common/create/LuxCreateFooter";
import {
  CREATE_ENTRY_MODES,
  getWizardStepMandatoryFieldNames,
  isValidRequestForFieldNames,
  resolveWizardStepStatuses,
} from "views/common/create/createPanel.utils";
import { bidRequestsActions } from "_actions";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import { validationUtils } from "_helpers";
import { CREATE_BID_WIZARD_STEPS } from "./createBid.wizardSteps";
import CreateBidRequestForm from "./CreateBidRequestForm";

class CreateBidRequestsSidebarSection extends Component {
  constructor() {
    super();
    this.state = {
      formErrors: {},
      hasFormError: false,
      entryMode: CREATE_ENTRY_MODES.WIZARD,
      wizardStep: 0,
      visitedWizardSteps: new Set([0]),
    };
  }

  componentDidMount() {
    this.initializeRequest();
  }

  initializeRequest = () => {
    const userTeamId = commonUtils.getCurrentUserTeamId();
    const bidRequest = this.props.editMode
      ? this.props.selectedBidRequestsInfo
      : this.props.duplicateMode
      ? {
          ...this.props.selectedBidRequestsInfo,
          id: null,
          createdBy: commonUtils.getCurrentUserId(),
          modifiedBy: null,
        }
      : {
          userTeamId,
          countriesData: {},
          studyTypesData: {},
          typeData: {},
          quotaInformation: {},
          additionalQuestions: {},
          screeningQuestions: {},
        };
    this.setState({ bidRequest });
  };

  onFormError = (fieldName, hasError) => {
    this.setState((prevState) => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError,
      },
    }));
  };

  onResetFormError = () => {
    this.setState({ hasFormError: false });
  };

  onChange = (fieldName, value) => {
    this.onResetFormError();
    if (fieldName === "userTeamId") {
      store.dispatch(this.props.getModuleConfig(value));
    }
    this.setState((prevState) => ({
      bidRequest: {
        ...prevState.bidRequest,
        [fieldName]: value,
      },
    }));
  };

  onTypeDataChange = (fieldName, value) => {
    this.onChange("typeData", {
      ...this.state.bidRequest.typeData,
      [fieldName]: value,
    });
  };

  handleSubmit = (isCreateAnotherEnabled) => {
    const isValid = validationUtils.isValidRequest(
      this.props.fieldConfig,
      this.state.bidRequest,
      this.state.formErrors
    );
    if (isValid) {
      const defaultNotificationEmails = commonUtils.getAppConfigValue(
        this.props.createConfig,
        "defaultNotificationEmails"
      );
      const bidRequestToBeSaved = {
        ...this.state.bidRequest,
        watchers: [
          ...(this.state.bidRequest.watchers ||
            (defaultNotificationEmails ? defaultNotificationEmails : [])),
        ],
      };
      this.props.handleSubmit(
        bidRequestToBeSaved,
        this.props.editMode,
        isCreateAnotherEnabled,
        !this.props.editMode ? this.initializeRequest : null
      );
    } else {
      this.setState({ hasFormError: true });
    }
  };

  isWizardMode = () => this.state.entryMode === CREATE_ENTRY_MODES.WIZARD;

  getWizardStep = () => CREATE_BID_WIZARD_STEPS[this.state.wizardStep];

  isSectionVisible = (sectionKey) => {
    if (this.props.readOnly || !this.isWizardMode()) return true;
    const step = this.getWizardStep();
    return step && step.sections.includes(sectionKey);
  };

  markWizardStepVisited = (stepIndex) => {
    this.setState((prev) => {
      const visitedWizardSteps = new Set(prev.visitedWizardSteps);
      visitedWizardSteps.add(stepIndex);
      return { visitedWizardSteps };
    });
  };

  handleEntryModeChange = (entryMode) => {
    this.setState({
      entryMode,
      wizardStep: 0,
      visitedWizardSteps: new Set([0]),
      hasFormError: false,
    });
  };

  handleWizardStepSelect = (wizardStep) => {
    this.markWizardStepVisited(wizardStep);
    this.setState({ wizardStep, hasFormError: false });
  };

  validateWizardStep = (stepIndex) => {
    const step = CREATE_BID_WIZARD_STEPS[stepIndex];
    if (!step) return true;
    const mandatoryNames = getWizardStepMandatoryFieldNames(
      this.props.fieldConfig,
      step.fieldNames
    );
    if (!mandatoryNames.length) return true;
    return isValidRequestForFieldNames(
      this.props.fieldConfig,
      this.state.bidRequest,
      this.state.formErrors,
      mandatoryNames
    );
  };

  handleWizardNext = () => {
    if (!this.validateWizardStep(this.state.wizardStep)) {
      this.setState({ hasFormError: true });
      return;
    }
    const nextStep = Math.min(
      this.state.wizardStep + 1,
      CREATE_BID_WIZARD_STEPS.length - 1
    );
    this.markWizardStepVisited(this.state.wizardStep);
    this.markWizardStepVisited(nextStep);
    this.setState({ wizardStep: nextStep, hasFormError: false });
  };

  handleWizardBack = () => {
    const prevStep = Math.max(this.state.wizardStep - 1, 0);
    this.markWizardStepVisited(prevStep);
    this.setState({ wizardStep: prevStep, hasFormError: false });
  };

  getWizardStepStatuses = () =>
    resolveWizardStepStatuses({
      steps: CREATE_BID_WIZARD_STEPS,
      activeIndex: this.state.wizardStep,
      fieldConfig: this.props.fieldConfig,
      request: this.state.bidRequest,
      formErrors: this.state.formErrors,
      visitedSteps: this.state.visitedWizardSteps,
      hasFormError: this.state.hasFormError,
    });

  getSelectedKindOfStudies = () => {
    let selected =
      (this.state.bidRequest &&
        this.state.bidRequest.kindOfStudies &&
        this.state.bidRequest.kindOfStudies.filter(
          (ks) =>
            !ks.startsWith("Others") && !ks.startsWith("Offline Qualitative")
        )) ||
      [];
    if (this.state.bidRequest && this.state.bidRequest.specifykindOfStudy) {
      selected = [...selected, this.state.bidRequest.specifykindOfStudy];
    }
    return selected;
  };

  render() {
    const wizardMode = this.isWizardMode() && !this.props.readOnly;
    const wizardStep = this.getWizardStep();
    const stepStatuses = wizardMode ? this.getWizardStepStatuses() : [];
    const isProcessing = this.props.creating || this.props.updating;

    if (this.props.readOnly && this.props.detailView && this.state.bidRequest) {
      return (
        <CreateBidRequestForm
          bidRequest={this.state.bidRequest}
          readOnly={true}
          isWizardMode={false}
          fieldConfig={this.props.fieldConfig}
          createConfig={this.props.createConfig}
          allEmployees={this.props.allEmployees}
          studyTypeConfig={this.props.studyTypeConfig}
          screeningQuestions={this.props.screeningQuestions}
          additionalQuestions={this.props.additionalQuestions}
          quotaInformation={this.props.quotaInformation}
          selectedKindOfStudies={this.getSelectedKindOfStudies()}
          onChange={this.onChange}
          onTypeDataChange={this.onTypeDataChange}
          onFormError={this.onFormError}
          isSectionVisible={() => true}
        />
      );
    }

    return (
      <>
        {this.state.bidRequest && (
          <div className="lux-create-panel__workflow lux-create-panel__workflow--bid">
            {!this.props.readOnly && (
              <div className="lux-create-panel__chrome">
                <LuxCreateModeSwitch
                  mode={this.state.entryMode}
                  onChange={this.handleEntryModeChange}
                  disabled={isProcessing}
                />
              </div>
            )}

            <div
              className={
                wizardMode
                  ? "lux-create-panel__workspace lux-create-panel__workspace--wizard lux-create-panel__workspace--bid-wizard"
                  : "lux-create-panel__workspace lux-create-panel__workspace--bid-full"
              }
            >
              {wizardMode && (
                <LuxCreateWizardNav
                  stepStatuses={stepStatuses}
                  activeIndex={this.state.wizardStep}
                  onSelect={this.handleWizardStepSelect}
                  disabled={isProcessing}
                  layout="rail"
                />
              )}

              <div className="lux-create-panel__canvas">
                <div className="lux-create-panel__scroll">
                  <div className="lux-create-panel__form-grid lux-create-form">
                    <CreateBidRequestForm
                      bidRequest={this.state.bidRequest}
                      readOnly={this.props.readOnly}
                      isWizardMode={wizardMode}
                      fieldConfig={this.props.fieldConfig}
                      createConfig={this.props.createConfig}
                      allEmployees={this.props.allEmployees}
                      studyTypeConfig={this.props.studyTypeConfig}
                      screeningQuestions={this.props.screeningQuestions}
                      additionalQuestions={this.props.additionalQuestions}
                      quotaInformation={this.props.quotaInformation}
                      selectedKindOfStudies={this.getSelectedKindOfStudies()}
                      onChange={this.onChange}
                      onTypeDataChange={this.onTypeDataChange}
                      onFormError={this.onFormError}
                      isSectionVisible={this.isSectionVisible}
                    />
                  </div>
                </div>
              </div>
            </div>

            {!this.props.readOnly && (
              <LuxCreateFooter
                handleSubmit={this.handleSubmit}
                editMode={this.props.editMode}
                duplicateMode={this.props.duplicateMode}
                initializeRequest={this.initializeRequest}
                isProcessing={isProcessing}
                hasFormError={this.state.hasFormError}
                onResetFormError={this.onResetFormError}
                wizardMode={wizardMode}
                wizardStepIndex={this.state.wizardStep}
                wizardStepCount={CREATE_BID_WIZARD_STEPS.length}
                onWizardBack={this.handleWizardBack}
                onWizardNext={this.handleWizardNext}
                canWizardNext={
                  wizardStep ? this.validateWizardStep(this.state.wizardStep) : true
                }
                createButtonLabel={
                  this.props.editMode
                    ? "Save changes"
                    : this.props.duplicateMode
                    ? "Create duplicate"
                    : "Create bid request"
                }
              />
            )}
          </div>
        )}
      </>
    );
  }
}

const mapStateToProps = (state) => ({
  fieldConfig: state.bidRequests.fieldConfig,
  createConfig: state.bidRequests.createConfig,
  allEmployees: state.employees.allEmployees,
  creating: state.bidRequests.creating,
  updating: state.bidRequests.updating,
  screeningQuestions: state.bidRequests.screeningQuestions,
  additionalQuestions: state.bidRequests.additionalQuestions,
  quotaInformation: state.bidRequests.quotaInformation,
  studyTypeConfig: state.bidRequests.studyTypeConfig,
});

const mapDispatchToProps = (dispatch) => ({
  getModuleConfig: bidRequestsActions.getModuleConfig,
});

export default connect(
  mapStateToProps,
  mapDispatchToProps
)(CreateBidRequestsSidebarSection);
