import React, { Component } from "react";
import { connect } from "react-redux";
import classNames from "classnames/bind";
import EmployeeImage from "views/common/fragments/EmployeeImage";
import Ckeditor from "views/common/plugins/charts/ckeditor";
import { itemAdditionalActions } from "_actions";
import { commonUtils } from "_helpers";
import { store } from "_helpers";
import {
  COLLAB_VIEWS,
  COLLAB_VIEW_TABS,
  formatCollabRelativeTime,
  formatCollabTimestamp,
  getCollabItemsForView,
  getEmployeeMeta,
  getEmployeeName,
  getEntryHeadline,
  getEntryIcon,
  getEntryTone,
  groupEntriesByDay,
  hasRichHtmlContent,
  stripHtml,
} from "./itemComments.utils";
import LuxActivityPanelEmptyState from "views/common/fragments/LuxActivityPanelEmptyState";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "views/common/fragments/luxSkeleton.constants";

class ItemCommentsSection extends Component {
  constructor(props) {
    super(props);
    const initialView = props.initialView || COLLAB_VIEWS.COMMENT;
    this.state = {
      currentView: initialView,
      loadedViews: { COMMENT: false, ACTIVITY: false, HISTORY: false },
    };
  }

  componentDidMount() {
    this.loadView(this.props.initialView || COLLAB_VIEWS.COMMENT);
  }

  componentDidUpdate(prevProps) {
    if (prevProps.itemId !== this.props.itemId) {
      const initialView = this.props.initialView || COLLAB_VIEWS.COMMENT;
      this.setState({
        currentView: initialView,
        loadedViews: { COMMENT: false, ACTIVITY: false, HISTORY: false },
      });
      this.loadView(initialView);
    }
  }

  loadView = (viewName) => {
    this.setState((prev) => ({
      currentView: viewName,
      loadedViews: { ...prev.loadedViews, [viewName]: true },
    }));
    store.dispatch(
      this.props.getItemAdditionals(
        { itemId: this.props.itemId, subType: this.props.subType, type: viewName },
        viewName
      )
    );
  };

  handleSubmitComment = (comment) => {
    store.dispatch(
      this.props.createItemAdditional({
        userTeamId: this.props.userTeamId || commonUtils.getCurrentUserTeamId(),
        itemId: this.props.itemId,
        type: COLLAB_VIEWS.COMMENT,
        subType: this.props.subType,
        description: comment,
      })
    );
  };

  handleRemoveComment = (commentId) => {
    store.dispatch(this.props.deleteItemAdditional({ itemId: commentId }));
  };

  getTabCount = (viewId) => {
    const items = getCollabItemsForView(this.props, viewId);
    return items && items.length ? items.length : 0;
  };

  renderEmptyState = (view) => {
    const copy =
      view === COLLAB_VIEWS.COMMENT
        ? {
            eyebrow: "Conversation",
            title: "No comments yet",
            description:
              "Start the conversation — mention teammates, capture decisions, and keep context in one place.",
            hints: [
              "Use @mentions to notify teammates",
              "Rich text supports links and formatting",
              "Comments stay attached to this record",
            ],
          }
        : view === COLLAB_VIEWS.ACTIVITY
        ? {
            eyebrow: "Activity feed",
            title: "No activity recorded",
            description:
              "Updates, notes, and team actions on this record will appear here as they happen.",
            hints: [
              "Status changes and assignments show automatically",
              "Linked work items surface related updates",
              "Filter tabs help you focus on one stream",
            ],
          }
        : {
            eyebrow: "Audit trail",
            title: "No history yet",
            description:
              "Status changes, edits, and audit events will be listed chronologically once logged.",
            hints: [
              "Edits to fields and dates appear in order",
              "Exports include history for compliance reviews",
              "Older events remain searchable in this tab",
            ],
          };

    return (
      <LuxActivityPanelEmptyState
        className="lux-item-collab__empty"
        variant="collab"
        eyebrow={copy.eyebrow}
        title={copy.title}
        description={copy.description}
        hints={copy.hints}
      />
    );
  };

  renderEntry = (entry, view) => {
    const tone = getEntryTone(entry, view);
    const icon = getEntryIcon(view, tone);
    const isComment = view === COLLAB_VIEWS.COMMENT;
    const employee = entry.employeeInfo;
    const canDelete =
      isComment &&
      !this.props.isReadOnly &&
      employee &&
      employee.id === commonUtils.getCurrentUserId();

    return (
      <article
        key={entry.id}
        className={classNames("lux-item-collab__entry", {
          "lux-item-collab__entry--last": false,
        })}
      >
        <div className="lux-item-collab__entry-rail" aria-hidden="true">
          <span className={classNames("lux-item-collab__entry-icon", `is-${tone}`)}>
            <i className={`fe ${icon}`} />
          </span>
          <span className="lux-item-collab__entry-line" />
        </div>

        <div
          className={classNames("lux-item-collab__entry-card", {
            "is-comment": isComment,
            "is-activity": view === COLLAB_VIEWS.ACTIVITY,
            "is-history": view === COLLAB_VIEWS.HISTORY,
          })}
        >
          {isComment && (
            <>
              <span className="lux-item-collab__comment-glow" aria-hidden="true" />
              <span className="lux-item-collab__comment-accent" aria-hidden="true" />
              <span className="lux-item-collab__comment-watermark" aria-hidden="true">
                <i className="fe fe-message-square" />
              </span>
            </>
          )}

          <header
            className={classNames("lux-item-collab__entry-head", {
              "lux-item-collab__comment-head": isComment,
            })}
          >
            <div className="lux-item-collab__entry-user">
              {employee && (
                <span className="lux-item-collab__avatar-ring">
                  <EmployeeImage employee={employee} classes="lux-item-collab__avatar" />
                </span>
              )}
              <div className="lux-item-collab__entry-names">
                <strong>{getEmployeeName(entry)}</strong>
                <span>
                  {isComment
                    ? "posted a comment"
                    : view === COLLAB_VIEWS.ACTIVITY
                    ? "logged activity"
                    : "made a change"}
                  {getEmployeeMeta(entry) ? ` · ${getEmployeeMeta(entry)}` : ""}
                </span>
              </div>
            </div>
            <div
              className={classNames("lux-item-collab__entry-time", {
                "lux-item-collab__comment-time": isComment,
              })}
            >
              {isComment && (
                <span className="lux-item-collab__comment-badge">
                  <i className="fe fe-message-circle" aria-hidden="true" />
                  Comment
                </span>
              )}
              <strong title={formatCollabTimestamp(entry.createdDate)}>
                {formatCollabRelativeTime(entry.createdDate)}
              </strong>
              <span>{formatCollabTimestamp(entry.createdDate)}</span>
            </div>
          </header>

          {!isComment && (
            <h3 className="lux-item-collab__entry-title">{getEntryHeadline(entry, view)}</h3>
          )}

          <div
            className={classNames({
              "lux-item-collab__comment-body-wrap": isComment,
            })}
          >
            {hasRichHtmlContent(entry.description) ? (
              <div
                className={classNames("lux-item-collab__entry-body htmlComments", {
                  "lux-item-collab__comment-body": isComment,
                })}
                dangerouslySetInnerHTML={{ __html: entry.description }}
              />
            ) : (
              <p
                className={classNames("lux-item-collab__entry-body", {
                  "lux-item-collab__comment-body": isComment,
                })}
              >
                {getEntryHeadline(entry, view)}
              </p>
            )}
          </div>

          {view === COLLAB_VIEWS.HISTORY && (
            <span className={classNames("lux-item-collab__entry-chip", `is-${tone}`)}>
              Audit trail
            </span>
          )}

          {view === COLLAB_VIEWS.ACTIVITY && (
            <span className={classNames("lux-item-collab__entry-chip", `is-${tone}`)}>
              Activity
            </span>
          )}

          {canDelete && (
            <div className="lux-item-collab__entry-actions">
              <button
                type="button"
                className="lux-item-collab__delete-btn"
                onClick={() => this.handleRemoveComment(entry.id)}
              >
                <i className="fe fe-trash-2" aria-hidden="true" />
                Remove
              </button>
            </div>
          )}
        </div>
      </article>
    );
  };

  renderTimeline = (view) => {
    const items = getCollabItemsForView(this.props, view) || [];
    if (!items.length) return this.renderEmptyState(view);

    const groups = groupEntriesByDay(items);
    return (
      <div className="lux-item-collab__timeline">
        {groups.map(([dayLabel, entries]) => (
          <section key={dayLabel} className="lux-item-collab__day-group">
            <div className="lux-item-collab__day-label">
              <i className="fe fe-calendar" aria-hidden="true" />
              {dayLabel}
            </div>
            <div className="lux-item-collab__entries">
              {entries.map((entry) => this.renderEntry(entry, view))}
            </div>
          </section>
        ))}
      </div>
    );
  };

  render() {
    const { currentView } = this.state;
    const { isLoading, creatingItemAdditional } = this.props;
    const items = getCollabItemsForView(this.props, currentView) || [];
    const showLoading = isLoading && !items.length;

    return (
      <div className="lux-item-collab">
        <div className="lux-item-collab__toolbar">
          <div className="lux-item-collab__tabs" role="tablist" aria-label="Collaboration views">
            {COLLAB_VIEW_TABS.map((tab) => {
              const count = this.getTabCount(tab.id);
              return (
                <button
                  key={tab.id}
                  type="button"
                  role="tab"
                  aria-selected={currentView === tab.id}
                  className={classNames("lux-item-collab__tab", {
                    "is-active": currentView === tab.id,
                  })}
                  onClick={() => this.loadView(tab.id)}
                >
                  <i className={tab.icon} aria-hidden="true" />
                  {tab.label}
                  {count > 0 && <span className="lux-item-collab__tab-count">{count}</span>}
                </button>
              );
            })}
          </div>
          <span className="lux-item-collab__summary">
            {items.length} {currentView === COLLAB_VIEWS.COMMENT ? "comment" : "entry"}
            {items.length === 1 ? "" : "s"}
          </span>
        </div>

        <div className="lux-item-collab__body">
          {showLoading && (
            <div className="lux-item-collab__loading" aria-busy="true" aria-label="Loading conversation">
              <SkeletonTheme baseColor={LUX_SKELETON_THEME.baseColor} highlightColor={LUX_SKELETON_THEME.highlightColor}>
                {[1, 2, 3].map((key) => (
                  <div key={key} className="lux-item-collab__loading-row">
                    <Skeleton circle width={32} height={32} />
                    <div style={{ flex: 1 }}>
                      <Skeleton width="35%" height={10} borderRadius={4} />
                      <Skeleton height={36} borderRadius={10} style={{ marginTop: 8 }} />
                    </div>
                  </div>
                ))}
              </SkeletonTheme>
            </div>
          )}

          {!showLoading && currentView === COLLAB_VIEWS.COMMENT && (
            <>
              <ItemCommentsComposer
                isReadOnly={this.props.isReadOnly}
                onSubmit={this.handleSubmitComment}
                isSubmitting={creatingItemAdditional === true}
                commentCount={items.length}
              />
              {this.renderTimeline(COLLAB_VIEWS.COMMENT)}
            </>
          )}

          {!showLoading && currentView === COLLAB_VIEWS.ACTIVITY && (
            this.renderTimeline(COLLAB_VIEWS.ACTIVITY)
          )}

          {!showLoading && currentView === COLLAB_VIEWS.HISTORY && (
            this.renderTimeline(COLLAB_VIEWS.HISTORY)
          )}
        </div>
      </div>
    );
  }
}

class ItemCommentsComposer extends Component {
  constructor() {
    super();
    this.state = {
      comment: "",
      submitEnabled: false,
    };
  }

  componentDidUpdate(prevProps) {
    if (prevProps.isSubmitting && !this.props.isSubmitting) {
      this.setState({ comment: "", submitEnabled: false });
    }
  }

  onChange = (comment) => {
    const plain = stripHtml(comment);
    this.setState({
      comment,
      submitEnabled: plain.length > 1,
    });
  };

  onSubmit = () => {
    if (!this.state.submitEnabled || this.props.isSubmitting) return;
    this.props.onSubmit(this.state.comment);
  };

  render() {
    const { isReadOnly, commentCount, isSubmitting } = this.props;

    return (
      <div className="lux-item-collab__composer">
        <div className="lux-item-collab__composer-head">
          <span className="lux-item-collab__composer-title">Add a comment</span>
          <span className="lux-item-collab__composer-hint">Visible to everyone with access</span>
        </div>

        {!isReadOnly && (
          <Ckeditor onChange={this.onChange} content={this.state.comment} />
        )}

        <div className="lux-item-collab__composer-foot">
          <span className="lux-item-collab__composer-meta">
            {commentCount || 0} comment{commentCount === 1 ? "" : "s"} in this thread
          </span>
          {!isReadOnly && (
            <button
              type="button"
              className="lux-item-collab__post-btn"
              onClick={this.onSubmit}
              disabled={!this.state.submitEnabled || isSubmitting}
            >
              {isSubmitting ? (
                <>
                  <i className="fe fe-loader" aria-hidden="true" />
                  Posting…
                </>
              ) : (
                <>
                  <i className="fe fe-send" aria-hidden="true" />
                  Post comment
                </>
              )}
            </button>
          )}
        </div>
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  comments: state.itemAdditional.comments,
  activities: state.itemAdditional.activities,
  histories: state.itemAdditional.histories,
  isLoading: state.itemAdditional.isLoading,
  creatingItemAdditional: state.itemAdditional.creatingItemAdditional,
});

const mapDispatchToProps = () => ({
  getItemAdditionals: itemAdditionalActions.getItemAdditionals,
  createItemAdditional: itemAdditionalActions.createItemAdditional,
  deleteItemAdditional: itemAdditionalActions.removeItemAdditional,
});

export default connect(mapStateToProps, mapDispatchToProps)(ItemCommentsSection);
