class FeedbackPageSection extends Component {
  constructor() {
    super();
    this.state = {
      viewMode: "PAGE",
      projectModuleConfig:{},
      filterOptions: {
        SHOW: {
          options: [
            { name: "ALL", label: "All" },
            { name: "ACTIVE", label: "Active" },
            { name: "INACTIVE", label: "In Active" },
          ],
          selected: "ALL",
        },
        SORT: {
          options: [
            { name: "CREATEDDATE", label: "Created Date" },
            { name: "A-Z", label: "A-Z" },
          ],
          selected: "CREATEDDATE",
          directionUp: true,
        },
        filterText: null,
      },
      permission: accessUtils.getFeedbackTemplateAccessControl(),
      permissionFeedbackRequest: accessUtils.getFeedbackRequestAccessControl(),
      editMode: false,
      showCreateWindow: false,
      formErrors: {},
      page: 1,
      pageSize: REGISTER_DEFAULT_PAGE_SIZE,
    };
  }

  componentDidUpdate(prevProps) {
    if (shouldResetRegisterPage(prevProps, this.props)) {
      this.setState({ page: 1 });
    }
  }

  handlePageChange = (page) => {
    this.setState({ page });
  };

  handlePageSizeChange = (pageSize) => {
    this.setState({ pageSize, page: 1 });
  };

  componentDidMount() {
    this.setState({
      type: this.props.feedbackType,
    });

    if (this.props.feedbackType) {
      this.setState({
        viewMode: this.props.feedbackType,
      });
      this.props.getAllFeedbackTemplates({
        itemType: this.props.feedbackType,
      });
      this.props.getAllFeedbackRequests({
        itemType: this.props.feedbackType,
        itemId: this.props.projectItem ? this.props.projectItem.id : null,
      });
    } else {
      this.props.getAllFeedbackRequests({
        itemType: "PROJECT",
      });
      this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    }
    this.initialize();
    store.dispatch(projectActions.getModuleConfigData(userUtils.getCurrentTeamId(), (projectModuleConfig) => {
      this.setState({
        projectModuleConfig: projectModuleConfig
      });
    }))
  }

  initialize = () => {
    //store.dispatch(employeeActions.getAllEmployees())
    this.setState({
      showCroDropdownMenu: false,
      editMode: false,
      feedbackRequest: {
        userTeamId: commonUtils.getCurrentUserTeamId(),
        type: this.state.type || this.props.feedbackType,
        subType: "GENERAL",
        itemId: this.props.projectItem ? this.props.projectItem.id : null,
        itemName: this.props.projectItem ? this.props.projectItem.name : null,
        recurring: false,
        draft: false,
        active: true,
        feedbackRequestInfos: [],
      },
    });
  };

  onChange = (feedbackRequest) => {
    this.setState({
      feedbackRequest: feedbackRequest,
    });
  };

  onCreateItemClick = () => {
    this.setState({
      showCreateWindow: true,
    });
    this.props.getAllFeedbackTemplates({ itemType: this.state.type });
    this.initialize();
  };

  closeCreateItemWindow = () => {
    this.setState({
      showCreateWindow: false,
      editMode: false,
    });
  };

  editFeedbackRequest = (feedbackRequest) => {
    if (feedbackRequest !== null) {
      this.setState({
        showCreateWindow: true,
        feedbackRequest: feedbackRequest,
        editMode: true,
      });
    } else {
      this.setState({
        feedbackRequest: null,
      });
    }
  };

  createFeedbackRequest = (createAnother) => {
    this.props.createFeedbackRequest(this.state.feedbackRequest, this.initialize);
    if (createAnother === false) {
      this.closeCreateItemWindow();
    }
  };

  updateFeedbackRequest = () => {
    this.props.updateFeedback(this.state.feedbackRequest, this.initialize);
    this.closeCreateItemWindow();
  };

  showFeedbackTemplateConfigureWindow = () => {
    store.dispatch({
      type: feedbackTemplateConstants.SHOW_FEEDBACK_TEMPLATE_CONFIGURE_WINDOW,
    });
  };

  handleFilterChange = (filterOptions) => {
    this.setState({ filterOptions: filterOptions }, () => {
      store.dispatch({
        type: feedbackRequestConstants.CHANGE_FILTER_FEEDBACKS,
        filterOptions,
      });
    });
  };

  onFilterTextChange = (value) => {
    this.setState(
      (prevState) => ({
        filterOptions: {
          ...prevState.filterOptions,
          filterText: value,
        },
      }),
      () => {
        this.handleFilterChange(this.state.filterOptions);
      }
    );
  };

  render() {
    const filterOptions =
      this.props.filterOptions || this.state.filterOptions;
    const allItems = this.props.items || [];
    const pagination = paginateRegisterList(
      allItems,
      this.state.page,
      this.state.pageSize
    );
    const items = pagination.items;
    const summary = buildFeedbackSummary(allItems);
    const isPageView = this.state.viewMode === "PAGE";
    const showList = isPageView || this.state.viewMode !== "PAGE";

    return (
      <div className="lux-feedback-page lux-bid-requests col-md-12 col-xs-12 px-0">
        <div className="p-0 m-0">
          <PageInnerHeader
            userTeams={[]}
            handleUserTeamsSelection={this.handleUserTeamsSelection}
            //showCreateMenu={this.state.permission.createEnabled}
            showCreateMenu={
              this.state.showCreateWindow === false &&
              this.state.viewMode !== "PAGE" &&
              this.state.permissionFeedbackRequest.createEnabled === true
            }
            showGridListMenu={false}
            searchViewEnabled={false}
            handleSearchSubmit={this.handleSearchSubmit}
            showFilter={true}
            showUserTeamMenu={true}
            isLoading={this.props.isLoading}
            filterOptions={filterOptions}
            handleFilterChange={this.handleFilterChange}
            onFilterTextChange={this.onFilterTextChange}
            showCreateMenuText="Request Feedback"
            createItemHandler={this.onCreateItemClick}
            showDateRangeSelector={false}
            handleDateRangeChange={this.handleDateRangeChange}
            permission={this.state.permission}
            additionalButtons={
              this.state.permission.createEnabled === true &&
              this.state.viewMode !== "PAGE" ? (
                <div className="lux-feedback-header-extra">
                  <button
                    type="button"
                    className="lux-planner-btn lux-planner-btn--ghost"
                    title="Configure feedback templates"
                    onClick={() => this.showFeedbackTemplateConfigureWindow()}
                  >
                    <i className="fe fe-sliders" aria-hidden="true" />
                    Configure template
                  </button>
                </div>
              ) : null
            }
          />
        </div>

        {isPageView && (
          <FeedbackPageSummary
            summary={summary}
            isLoading={this.props.isLoading}
            visibleCount={pagination.total}
            filterText={(filterOptions && filterOptions.filterText) || ""}
            filterOptions={filterOptions}
            isEmpty={!this.props.isLoading && pagination.total === 0}
          />
        )}

        <LuxFeedbackRequestCreatePanel
          show={this.state.showCreateWindow && !!this.state.feedbackRequest}
          editMode={this.state.editMode}
          onClose={this.closeCreateItemWindow}
        >
          {this.state.showCreateWindow && this.state.feedbackRequest && (
            <CreateFeedbackRequestSection
              initialize={this.initialize}
              editMode={this.state.editMode}
              projectModuleConfig={this.state.projectModuleConfig}
              feedbackRequest={this.state.feedbackRequest}
              fieldConfig={this.props.feedbackFieldConfig}
              allEmployees={this.props.allEmployees}
              feedbackTypeOptions={this.props.feedbackTypeOptions}
              feedbackSubTypeOptions={this.props.feedbackSubTypeOptions}
              userTeamId={
                this.props.projectItem
                  ? this.props.projectItem.userTeamId
                  : commonUtils.getCurrentUserTeamId()
              }
              type={this.state.type || this.props.feedbackType}
              itemId={this.props.projectItem ? this.props.projectItem.id : null}
              itemName={this.props.projectItem ? this.props.projectItem.name : null}
              closeCreateItemWindow={this.closeCreateItemWindow}
              onChange={this.onChange}
              permission={this.state.permissionFeedbackRequest}
              createFeedbackRequest={this.createFeedbackRequest}
              updateFeedbackRequest={this.updateFeedbackRequest}
              emailInfoFieldConfig={this.props.emailInfoFieldConfig}
              feedbackTemplateDataList={this.props.feedbackTemplateDataList}
            />
          )}
        </LuxFeedbackRequestCreatePanel>
        {showList && this.state.viewMode !== "PAGE" && (
          <div className="lux-feedback-list-section">
          <FeedbackRequestsTable
            items={items}
            listTotal={pagination.total}
            isLoading={this.props.isLoading}
            editMode={this.state.editMode || this.state.showCreateWindow}
            getAllFeedbackScheulers={this.handleGetAllFeedbackScheulers}
            permission={this.state.permissionFeedbackRequest}
            enableFeedback={this.props.enableFeedback}
            removeFeedback={this.props.removeFeedback}
            removeFeedbackRequest={this.props.removeFeedbackRequest}
            remindFeedbackRequest={this.props.remindFeedbackRequest}
            updateFeedbackRequestStatus={this.props.updateFeedbackRequestStatus}
            editEnabled={true}
            editFeedbackRequest={this.editFeedbackRequest}
            onCreateRequest={this.onCreateItemClick}
            allUserTeams={this.props.allUserTeams}
            allEmployees={this.props.allEmployees}
          />
          </div>
        )}
        {showList && this.state.viewMode === "PAGE" && (
          <div className="lux-feedback-list-section">
          <FeedbackRequestsTableByItem
            items={items}
            listTotal={pagination.total}
            isLoading={this.props.isLoading}
            editMode={this.state.editMode || this.state.showCreateWindow}
            getAllFeedbackScheulers={this.handleGetAllFeedbackScheulers}
            permission={this.state.permissionFeedbackRequest}
            enableFeedback={this.props.enableFeedback}
            removeFeedback={this.props.removeFeedback}
            removeFeedbackRequest={this.props.removeFeedbackRequest}
            remindFeedbackRequest={this.props.remindFeedbackRequest}
            updateFeedbackRequestStatus={this.props.updateFeedbackRequestStatus}
            onCreateRequest={this.onCreateItemClick}
            allUserTeams={this.props.allUserTeams}
            allEmployees={this.props.allEmployees}
          />
          </div>
        )}
        {showList && !this.props.isLoading && pagination.total > 0 && (
          <LuxRegisterPagination
            className="lux-feedback-pagination"
            pagination={pagination}
            onPageChange={this.handlePageChange}
            onPageSizeChange={this.handlePageSizeChange}
            pageSizeOptions={REGISTER_PAGE_SIZE_OPTIONS}
            summaryLabel="campaigns"
          />
        )}
        <ConfigureFeedbackTemplateSidebar
          type={this.props.feedbackType}
          show={this.props.showFeedbackTemplateConfigureModel}
        />
      </div>
    );
  }
}

class CreateFeedbackRequestSection extends Component {
  constructor() {
    super();
    this.state = {
      formErrors: {},
      hasFormError: false,
    };
  }

  componentDidMount() {}
  onResetFormError = () => {
    this.setState({
      hasFormError: false,
    });
  };

  getFeedbackTypeOptions = () => {
    if (this.props.type && this.props.feedbackTypeOptions) {
      return this.props.feedbackTypeOptions.filter(
        (type) => type.value === this.props.type
      );
    }
    return this.props.feedbackTypeOptions;
  };

  getFeedbackSubTypeOptions = () => {
    return this.props.feedbackSubTypeOptions;
  };

  getItemOptions = () => {
    if (this.props.itemId) {
      return [{ value: this.props.itemId, label: this.props.itemName }];
    }
    //get all project or po or bid or employees
  };

  getFeedbackTemplateDataList = () => {
    return (
      this.props.feedbackTemplateDataList &&
      this.props.feedbackTemplateDataList.filter(
        (ftdl) => ftdl.subType === this.props.feedbackRequest.subType
      )
    );
  };
  onCreateAnotherEnabled = (value) => {
    this.setState({
      createAnotherEnabled: value,
    });
  };

  onFormError = (fieldName, hasError) => {
    this.setState((prevState) => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError,
      },
    }));
  };

  onChange = (fieldName, value) => {
    this.onResetFormError();
    var scheduleData = null;
    var templateId =
      fieldName === "templateId"
        ? value
        : this.props.feedbackRequest.templateId;
    if (fieldName === "subType") {
      templateId = null;
    }
    if (fieldName === "recurring") {
      if (value === true) {
        scheduleData = {
          cronValue: "0 0 00 ? * SUN ",
          cronString: "At 12:00 AM, only on Sunday",
        };
      }
    }
    this.props.onChange({
      ...this.props.feedbackRequest,
      [fieldName]: value,
      templateId: templateId,
      scheduleData:
        fieldName === "recurring"
          ? scheduleData
          : this.props.feedbackRequest.scheduleData,
    });
  };

  onCronValueChange = (cronValue, cronString) => {
    this.props.onChange({
      ...this.props.feedbackRequest,
      scheduleData: {
        ...this.props.feedbackRequest.scheduleData,
        cronString: cronString,
        cronValue: cronValue.substr(0, cronValue.length - 1),
      },
    });
    this.toggeleCronMenu(false);
  };

  onChangeScheduleData = (fieldName, value) => {
    this.props.onChange({
      ...this.props.feedbackRequest,
      scheduleData: {
        ...this.props.feedbackRequest.scheduleData,
        [fieldName]: value,
      },
    });
  };
  toggeleCronMenu = (isShow) => {
    this.setState((prevState) => ({
      showCroDropdownMenu: isShow,
    }));
  };

  handleSubmit = (createAnotherEnabled) => {
    let isValid = validationUtils.isValidRequest(
      this.props.fieldConfig,
      this.props.feedbackRequest,
      this.state.formErrors
    );
    if (isValid) {
      if (this.props.editMode === true) {
        this.props.updateFeedbackRequest(false);
        //this.props.toggeleCreateWindow(false);
        //this.props.toggeleEditMote(false)
      } else {
        this.props.createFeedbackRequest(createAnotherEnabled);
      }
    } else {
      this.setState({
        hasFormError: true,
      });
    }
  };

  render() {
    if (!this.props.feedbackRequest) return null;

    return (
      <LuxFeedbackRequestCreateForm
        feedbackRequest={this.props.feedbackRequest}
        fieldConfig={this.props.fieldConfig}
        emailInfoFieldConfig={this.props.emailInfoFieldConfig}
        editMode={this.props.editMode}
        onChange={this.onChange}
        onFormError={this.onFormError}
        onChangeScheduleData={this.onChangeScheduleData}
        feedbackTypeOptions={this.getFeedbackTypeOptions()}
        feedbackSubTypeOptions={this.getFeedbackSubTypeOptions()}
        feedbackTemplateDataList={this.props.feedbackTemplateDataList}
        feedbackTemplateOptions={commonUtils.convertObjectToSelectObject(
          this.getFeedbackTemplateDataList()
        )}
        itemOptions={this.getItemOptions()}
        projectModuleConfig={this.props.projectModuleConfig}
        hasFormError={this.state.hasFormError}
        onResetFormError={this.onResetFormError}
        closeCreateItemWindow={this.props.closeCreateItemWindow}
        handleSubmit={this.handleSubmit}
        createButtonLabel={
          this.props.editMode ? "Save changes" : "Create feedback request"
        }
        showCronMenu={this.state.showCroDropdownMenu}
        onToggleCronMenu={this.toggeleCronMenu}
        onCronValueChange={this.onCronValueChange}
      />
    );
  }
}

class FeedbackRequestsTableByItem extends Component {
  constructor() {
    super();
    this.state = {
      expandedIds: [],
      clicked: false,
    };
  }

  toggleExpand = (id) => {
    var expandedIds = this.state.expandedIds;
    if (!this.state.expandedIds.includes(id)) {
      expandedIds.push(id);
    } else {
      expandedIds = expandedIds.filter((item) => item !== id);
    }
    this.setState({ expandedIds, clicked: true });
  };

  render() {
    const listTotal = this.props.listTotal != null ? this.props.listTotal : (this.props.items || []).length;
    const isEmpty = !this.props.isLoading && listTotal === 0;
    const listByItems =
      this.props.items &&
      this.props.items.reduce(function (r, a) {
        let itemId = a.itemId;
        r[itemId] = r[itemId] || [];
        r[itemId].push(a);
        return r;
      }, Object.create(null));
    const groupKeys = listByItems ? Object.keys(listByItems) : [];

    return (
      <div className="lux-feedback-groups">
        {this.props.isLoading &&
          [1, 2, 3].map((k) => <Skeleton key={k} height={88} borderRadius={14} />)}
        {!this.props.isLoading &&
          groupKeys.map((key, index) => {
            const expanded =
              this.state.expandedIds.includes(key) ||
              (this.state.expandedIds.length === 0 && index === 0 && this.state.clicked === false);
            return (
            <section key={key} className="lux-feedback-group">
              <div className="lux-feedback-group__header">
                <button
                  type="button"
                  className="lux-feedback-group__toggle"
                  onClick={() => this.toggleExpand(key)}
                  aria-expanded={expanded}
                >
                  <i
                    className={classNames("fe", expanded ? "fe-chevron-down" : "fe-chevron-right")}
                    aria-hidden="true"
                  />
                  <span className="lux-feedback-group__id">#{key}</span>
                  <span className="lux-feedback-group__name">{listByItems[key][0].itemName}</span>
                </button>
                <a
                  className="lux-feedback-group__open"
                  target="_blank"
                  rel="noopener noreferrer"
                  href={`/project/details/${key}?view=feedback`}
                  title="Open project feedback"
                  aria-label="Open project"
                >
                  <i className="fe fe-external-link" aria-hidden="true" />
                </a>
              </div>
              {expanded && (
                <div className="lux-feedback-group__body">
                  <FeedbackRequestsTable
                    items={listByItems[key]}
                    editMode={false}
                    getAllFeedbackScheulers={this.handleGetAllFeedbackScheulers}
                    permission={this.props.permission}
                    enableFeedback={this.props.enableFeedback}
                    removeFeedback={this.props.removeFeedback}
                    removeFeedbackRequest={this.props.removeFeedbackRequest}
                    remindFeedbackRequest={this.props.remindFeedbackRequest}
                    updateFeedbackRequestStatus={
                      this.props.updateFeedbackRequestStatus
                    }
                    editEnabled={false}
                    editFeedbackRequest={() => {}}
                    allUserTeams={this.props.allUserTeams}
                    allEmployees={this.props.allEmployees}
                  />
                </div>
              )}
            </section>
            );
          })}
        {isEmpty && (
          <LuxRegisterEmptyState
            variant="projects"
            eyebrow="Feedback"
            title="No feedback campaigns yet"
            description="Request feedback from clients and teams — use templates and track responses in one place."
            hints={[
              "Click Request Feedback to start a new campaign",
              "Add recipient emails before sending",
              "Configure templates for reusable question sets",
            ]}
            showCreate={this.props.permission && this.props.permission.createEnabled}
            createLabel="Request feedback"
            onCreate={this.props.onCreateRequest}
          />
        )}
      </div>
    );
  }
}

