import classNames from "classnames/bind";
import React, { Component } from "react";
import dateUtils from "_helpers/date.utils";
import { validationUtils } from "_helpers";
import workItemUtils from "_helpers/workitem.utils";
import {
  buildWorkItemChecklistMeter,
  buildWorkItemDetailSummary,
  buildWorkItemHoursMeter,
  getWorkItemScheduleInsight,
} from "./workItemActivityDetail.utils";

class WorkItemActivityDetailPopover extends Component {
  constructor(props) {
    super(props);
    this.state = {
      editEnabled: false,
      workItemRequest: null,
    };
  }

  componentDidMount() {
    document.addEventListener("keydown", this.handleKeyDown);
    this.syncWorkItemRequest(this.props.item);
  }

  componentDidUpdate(prevProps) {
    if (prevProps.item !== this.props.item || (this.props.show && !prevProps.show)) {
      this.syncWorkItemRequest(this.props.item);
      this.setState({ editEnabled: false });
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.handleKeyDown);
  }

  syncWorkItemRequest = (item) => {
    if (!item) {
      this.setState({ workItemRequest: null });
      return;
    }
    this.setState({
      workItemRequest: {
        ...item,
        estDurationInHrs: dateUtils.minuteToHourDecimal(item.estDurationInMins),
        durationInHrs: dateUtils.minuteToHourDecimal(item.durationInMins),
      },
    });
  };

  handleKeyDown = (event) => {
    if (event.key === "Escape" && this.props.show) {
      if (this.state.editEnabled) {
        this.setState({ editEnabled: false });
        return;
      }
      this.props.onClose();
    }
  };

  onChange = (fieldName, value) => {
    if (!validationUtils.validateAlphaNumbericWithSpecial(value)) return;
    this.setState((prevState) => ({
      workItemRequest: {
        ...prevState.workItemRequest,
        [fieldName]: value,
      },
    }));
  };

  onTimeEntryValueChange = (fieldName, valueInHours) => {
    const { permission } = this.props;
    if (
      !validationUtils.validateDecimalNumberic(valueInHours) ||
      (valueInHours && permission.maxHoursAllowedToEnter < parseFloat(valueInHours)) ||
      (valueInHours && parseFloat(valueInHours) - parseInt(valueInHours, 10) > 0.59)
    ) {
      return;
    }

    let valueInMins = 0;
    if (valueInHours !== "") {
      valueInMins =
        parseInt(valueInHours, 10) * 60 +
        Math.round((parseFloat(valueInHours) - parseInt(valueInHours, 10)) * 100);
    }

    const { workItemRequest } = this.state;
    let durationInMins = workItemRequest.durationInMins;
    let estDurationInMins = workItemRequest.estDurationInMins;

    if (fieldName === "durationInHrs") {
      durationInMins = valueInMins;
    } else if (fieldName === "estDurationInHrs") {
      estDurationInMins = valueInMins;
    }

    this.setState((prevState) => ({
      workItemRequest: {
        ...prevState.workItemRequest,
        durationInMins,
        estDurationInMins,
        [fieldName]: valueInHours,
      },
    }));
  };

  toggleEditEnabled = (value) => {
    this.setState({ editEnabled: value });
    if (value === false && this.props.item) {
      this.syncWorkItemRequest(this.props.item);
    }
  };

  onSubmit = () => {
    this.props.handleUpdateWorkItem(this.state.workItemRequest);
    this.toggleEditEnabled(false);
  };

  isCompletedHourEditByHoursEnabled = () => {
    const { item, permission } = this.props;
    if (item && item.status === "COMPLETED") {
      const hoursToBeAdded = parseInt(permission.enableCompletedWorkItemHoursEditTillNextDayXHour || 0, 10);
      return workItemUtils.isWorkItemEditActive(item.actualStartTime, hoursToBeAdded);
    }
    return false;
  };

  canEditInfo = () => {
    const { permission } = this.props;
    return permission.editCompletedWorkItemInfo || this.isCompletedHourEditByHoursEnabled();
  };

  canEditEstimatedHours = () => {
    const { permission } = this.props;
    return permission.viewWorkItemEstimatedHours && permission.editCompletedWorkItemEstimatedHours;
  };

  canEditActualHours = () => {
    const { item, permission } = this.props;
    return (
      (permission.editCompletedWorkItemHours && item.status === "COMPLETED") ||
      this.isCompletedHourEditByHoursEnabled()
    );
  };

  renderHoursMeter = (summary, item) => {
    const meter = buildWorkItemHoursMeter(summary, item);
    if (!meter) return null;

    return (
      <article className="lux-activity-detail-popover__hours-meter">
        <header>
          <strong>Time booked</strong>
          <span>{meter.caption}</span>
        </header>
        <div className="lux-activity-detail-popover__hours-compare">
          <div className="lux-activity-detail-popover__hours-stat is-plan">
            <span>Planned</span>
            <strong>{meter.plannedLabel}</strong>
          </div>
          <div className={classNames("lux-activity-detail-popover__hours-stat is-logged", { "is-muted": !meter.isCompleted })}>
            <span>Logged</span>
            <strong>{meter.isCompleted ? meter.loggedLabel : "—"}</strong>
          </div>
        </div>
        <div className="lux-activity-detail-popover__hours-bar" aria-hidden="true">
          <span
            className={classNames("lux-activity-detail-popover__hours-bar-fill", `is-${meter.varianceTone}`)}
            style={{ width: `${meter.barPct}%` }}
          />
        </div>
        <footer className={classNames("lux-activity-detail-popover__hours-foot", `is-${meter.varianceTone}`)}>
          <i className="fe fe-activity" aria-hidden="true" />
          {meter.isCompleted ? meter.varianceLabel : "Opens when work is marked complete"}
          {meter.isCompleted && <em>{meter.utilizationRate}% utilization</em>}
        </footer>
      </article>
    );
  };

  renderChecklistMeter = (summary) => {
    const meter = buildWorkItemChecklistMeter(summary);
    if (!meter) return null;

    return (
      <article className="lux-activity-detail-popover__checklist-meter">
        <header>
          <strong>Checklist</strong>
          <span>{meter.hint}</span>
        </header>
        <div className="lux-activity-detail-popover__checklist-body">
          <div
            className={classNames("lux-activity-detail-popover__checklist-ring", `is-${meter.tone}`)}
            style={{ "--lux-check-pct": `${meter.percent || 0}%` }}
            aria-hidden="true"
          >
            <strong>{meter.hasChecklist ? `${meter.percent}%` : "—"}</strong>
          </div>
          <div className="lux-activity-detail-popover__checklist-copy">
            <span className={classNames("lux-activity-detail-popover__checklist-label", `is-${meter.tone}`)}>
              {meter.label}
            </span>
            {meter.hasChecklist && (
              <div className="lux-activity-detail-popover__checklist-bar" aria-hidden="true">
                <span style={{ width: `${meter.percent}%` }} />
              </div>
            )}
          </div>
        </div>
      </article>
    );
  };

  renderDetailMosaic = (summary) => {
    let lastGroup = null;

    return (
      <section className="lux-activity-detail-popover__mosaic">
        <header className="lux-activity-detail-popover__mosaic-head">
          <i className="fe fe-grid" aria-hidden="true" />
          <div>
            <strong>Activity record</strong>
            <span>People, timing, and connected work</span>
          </div>
        </header>
        <div className="lux-activity-detail-popover__tiles">
          {summary.flatDetailTiles.map((tile) => {
            const showGroup = tile.groupKey !== lastGroup;
            lastGroup = tile.groupKey;
            return (
              <React.Fragment key={`${tile.groupKey}-${tile.label}`}>
                {showGroup && (
                  <div className="lux-activity-detail-popover__tile-group-label">{tile.groupTitle}</div>
                )}
                {this.renderTile(tile)}
              </React.Fragment>
            );
          })}
        </div>
      </section>
    );
  };

  renderTimeLedger = () => {
    const { item, permission } = this.props;
    const { workItemRequest } = this.state;
    if (!workItemRequest) return null;

    return (
      <article className="lux-activity-detail-popover__time-ledger">
        <header className="lux-activity-detail-popover__time-ledger-head">
          <span className="lux-activity-detail-popover__time-ledger-icon" aria-hidden="true">
            <i className="fe fe-sliders" />
          </span>
          <div>
            <strong>Time ledger</strong>
            <span>Fine-tune planned or logged hours for this activity</span>
          </div>
        </header>
        <div className="lux-activity-detail-popover__time-ledger-grid">
          {this.canEditEstimatedHours() && (
            <label className="lux-activity-detail-popover__time-field">
              <span>Planned duration</span>
              <input
                className="lux-activity-detail-popover__time-input"
                onChange={(e) => this.onTimeEntryValueChange("estDurationInHrs", e.target.value)}
                type="number"
                min={0}
                max={permission.maxHoursAllowedToEnter}
                value={workItemRequest.estDurationInHrs}
              />
            </label>
          )}
          {this.canEditActualHours() && (
            <label className="lux-activity-detail-popover__time-field">
              <span>Logged duration</span>
              <input
                className="lux-activity-detail-popover__time-input"
                onChange={(e) => this.onTimeEntryValueChange("durationInHrs", e.target.value)}
                type="number"
                min={0}
                max={permission.maxHoursAllowedToEnter}
                value={workItemRequest.durationInHrs}
              />
            </label>
          )}
          {item.taskType === "PROJECT" && this.canEditActualHours() && (
            <label className="lux-activity-detail-popover__time-field">
              <span>Quantity</span>
              <input
                className="lux-activity-detail-popover__time-input"
                onChange={(e) => this.onChange("quantity", e.target.value)}
                value={workItemRequest.quantity || ""}
              />
            </label>
          )}
        </div>
      </article>
    );
  };

  renderTile = (tile) => (
    <article
      key={tile.label}
      className={classNames("lux-activity-detail-popover__tile", tile.highlight && `is-key-${tile.highlight}`)}
    >
      <span className="lux-activity-detail-popover__tile-icon" aria-hidden="true">
        <i className={tile.icon} />
      </span>
      <div className="lux-activity-detail-popover__tile-copy">
        <span>{tile.label}</span>
        <strong title={tile.value}>{tile.value}</strong>
        {tile.subValue && <em>{tile.subValue}</em>}
      </div>
    </article>
  );

  renderLifecycleChart = (lifecycle) => {
    if (!lifecycle) return null;

    return (
      <article className={classNames("lux-activity-detail-popover__mini-chart", `is-${lifecycle.tone}`)}>
        <header>
          <span>Lifecycle</span>
          <strong>{lifecycle.pct}%</strong>
        </header>
        <div className="lux-activity-detail-popover__lifecycle-track" aria-hidden="true">
          {lifecycle.segments.map((segment) => (
            <span
              key={segment.key}
              className={classNames("lux-activity-detail-popover__lifecycle-seg", `is-${segment.tone}`, {
                "is-active": segment.active,
                "is-complete": segment.complete,
              })}
              title={segment.label}
            />
          ))}
        </div>
        <footer>
          <span>{lifecycle.label}</span>
          <em>{lifecycle.segments.filter((s) => s.complete).length}/{lifecycle.segments.length} stages</em>
        </footer>
      </article>
    );
  };

  renderPriorityGauge = (priority) => {
    if (!priority) return null;

    return (
      <article className={classNames("lux-activity-detail-popover__mini-chart is-compact", `is-${priority.tone}`)}>
        <header>
          <span>Priority</span>
          <strong>{priority.label}</strong>
        </header>
        <div className="lux-activity-detail-popover__gauge-track" aria-hidden="true">
          <span className={`is-${priority.tone}`} style={{ width: `${priority.pct}%` }} />
        </div>
        <footer>
          <span>P{priority.level}</span>
          <em>Queue weight</em>
        </footer>
      </article>
    );
  };

  renderScheduleMeter = (schedule) => {
    if (!schedule) return null;

    return (
      <article className={classNames("lux-activity-detail-popover__mini-chart is-compact", `is-${schedule.tone}`)}>
        <header>
          <span>Schedule</span>
          <strong>{schedule.label}</strong>
        </header>
        <div className="lux-activity-detail-popover__gauge-track" aria-hidden="true">
          <span className={`is-${schedule.tone}`} style={{ width: `${schedule.pct}%` }} />
        </div>
        <footer>
          <span>{schedule.hint}</span>
        </footer>
      </article>
    );
  };

  renderHoursSplitChart = (hoursSplit) => {
    if (!hoursSplit) return null;

    const maxMins = Math.max(hoursSplit.planned, hoursSplit.logged, 1);
    const plannedPct = Math.round((hoursSplit.planned / maxMins) * 100);
    const loggedPct = Math.round((hoursSplit.logged / maxMins) * 100);

    return (
      <article className={classNames("lux-activity-detail-popover__mini-chart", `is-${hoursSplit.tone || "slate"}`)}>
        <header>
          <span>Hours split</span>
          <strong>{hoursSplit.isCompleted ? `${hoursSplit.utilization}% used` : "In progress"}</strong>
        </header>
        <div className="lux-activity-detail-popover__hours-split">
          <div className="lux-activity-detail-popover__hours-split-row">
            <span>Planned</span>
            <strong>{hoursSplit.plannedLabel}</strong>
            <div className="lux-activity-detail-popover__gauge-track is-thin" aria-hidden="true">
              <span className="is-indigo" style={{ width: `${plannedPct}%` }} />
            </div>
          </div>
          <div className="lux-activity-detail-popover__hours-split-row">
            <span>Logged</span>
            <strong>{hoursSplit.isCompleted ? hoursSplit.loggedLabel : "—"}</strong>
            <div className="lux-activity-detail-popover__gauge-track is-thin" aria-hidden="true">
              <span className={classNames(`is-${hoursSplit.tone || "green"}`, { "is-muted": !hoursSplit.isCompleted })} style={{ width: `${loggedPct}%` }} />
            </div>
          </div>
        </div>
      </article>
    );
  };

  renderScopeChart = (scope) => {
    if (!scope) return null;

    return (
      <article className={classNames("lux-activity-detail-popover__mini-chart is-compact", `is-${scope.tone}`)}>
        <header>
          <span>Scope</span>
          <strong>{scope.label}</strong>
        </header>
        <div className="lux-activity-detail-popover__gauge-track" aria-hidden="true">
          <span className={`is-${scope.tone}`} style={{ width: `${scope.billablePct}%` }} />
        </div>
        <footer>
          <span>{scope.category}</span>
          <em>{scope.billablePct === 100 ? "Billable" : scope.billablePct === 0 ? "Non-billable" : "Mixed"}</em>
        </footer>
      </article>
    );
  };

  renderInsightsRow = (visualCharts) => {
    if (!visualCharts) return null;

    return (
      <div className="lux-activity-detail-popover__insights-row">
        {this.renderLifecycleChart(visualCharts.lifecycle)}
        {this.renderPriorityGauge(visualCharts.priority)}
        {this.renderScheduleMeter(visualCharts.schedule)}
        {this.renderScopeChart(visualCharts.scope)}
      </div>
    );
  };

  renderJourneyCharts = (visualCharts) => {
    if (!visualCharts) return null;

    return (
      <div className="lux-activity-detail-popover__journey-charts">
        {this.renderHoursSplitChart(visualCharts.hoursSplit)}
        <div className="lux-activity-detail-popover__journey-chart-row">
          {this.renderPriorityGauge(visualCharts.priority)}
          {this.renderScopeChart(visualCharts.scope)}
        </div>
      </div>
    );
  };

  renderTimelineNode = (node) => (
    <article
      key={node.key}
      className={classNames("lux-activity-detail-popover__timeline-node", `is-${node.tone}`, {
        "is-highlight": node.highlight,
        "is-empty": !node.display && !node.value,
      })}
    >
      <span>{node.label}</span>
      <strong>{node.display || node.value || "—"}</strong>
      {node.subDisplay && <b>{node.subDisplay}</b>}
      {node.hint && <em>{node.hint}</em>}
    </article>
  );

  render() {
    const { show, item, permission, onClose, onCheklistItemClick } = this.props;
    const { editEnabled } = this.state;
    if (!show || !item) return null;

    const summary = buildWorkItemDetailSummary(item);
    const scheduleInsight = getWorkItemScheduleInsight(item);
    const checklistClass =
      summary.checklistMeta.key === "COMPLETED"
        ? "is-done"
        : summary.checklistMeta.key === "INPROGRESS"
          ? "is-progress"
          : summary.checklistMeta.key === "NOT_STARTED"
            ? "is-open"
            : "";

    return (
      <>
        <button
          type="button"
          className="lux-activity-detail-popover__backdrop"
          aria-label="Close activity details"
          onClick={onClose}
        />
        <div
          className={classNames("lux-activity-detail-popover", { "is-editing": editEnabled })}
          role="dialog"
          aria-modal="true"
          aria-labelledby="lux-activity-detail-popover-title"
        >
          <header className="lux-activity-detail-popover__head">
            <div className="lux-activity-detail-popover__head-main">
              <div className="lux-activity-detail-popover__title-row">
                <span className={classNames("lux-activity-detail-popover__status", `is-${summary.statusMeta.tone}`)}>
                  <i className={classNames(summary.statusMeta.icon, { spin: summary.statusMeta.spin })} aria-hidden="true" />
                </span>
                <div className="lux-activity-detail-popover__title-copy">
                  <span className="lux-activity-detail-popover__eyebrow">Activity snapshot</span>
                  <h2 id="lux-activity-detail-popover-title">{item.name}</h2>
                  <p>
                    <span className="lux-activity-detail-popover__ref">{item.itemIdUserTeamPrefix}</span>
                    <span>{summary.projectLabel}</span>
                    <span>{summary.ownerName}</span>
                  </p>
                </div>
              </div>
              <div className="lux-activity-detail-popover__badges">
                <span className={classNames("lux-activity-detail-popover__badge", `is-${summary.statusMeta.tone}`)}>
                  {summary.statusMeta.label}
                </span>
                <span className={classNames("lux-activity-detail-popover__badge", `is-${summary.priorityMeta.tone}`)}>
                  {summary.priorityMeta.label}
                </span>
                <span className={classNames("lux-activity-detail-popover__badge", `is-${summary.dueMeta.tone}`)}>
                  {summary.dueMeta.label}
                </span>
                <span className={classNames("lux-activity-detail-popover__badge", `is-${scheduleInsight.tone}`)}>
                  {scheduleInsight.value}
                </span>
              </div>
            </div>
            <button type="button" className="lux-activity-detail-popover__close" onClick={onClose} aria-label="Close">
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-activity-detail-popover__canvas">
            <div className="lux-activity-detail-popover__strip">
              {summary.insightStrip.map((chip) => (
                <article
                  key={chip.key}
                  className={classNames("lux-activity-detail-popover__chip", `is-${chip.tone}`, {
                    "is-highlight": chip.highlight,
                    [`is-key-${chip.key}`]: chip.highlight,
                  })}
                >
                  <i className={chip.icon} aria-hidden="true" />
                  <div>
                    <span>{chip.label}</span>
                    <strong>{chip.value}</strong>
                    <em>{chip.hint}</em>
                  </div>
                </article>
              ))}
            </div>

            {this.renderInsightsRow(summary.visualCharts)}

            <div className="lux-activity-detail-popover__grid">
              <aside className="lux-activity-detail-popover__viz">
                {editEnabled && this.canEditInfo() ? (
                  this.renderTimeLedger()
                ) : (
                  <>
                    {this.renderHoursMeter(summary, item)}
                    {this.renderChecklistMeter(summary)}
                  </>
                )}
              </aside>

              <section className="lux-activity-detail-popover__journey">
                <header>
                  <i className="fe fe-git-merge" aria-hidden="true" />
                  <div>
                    <strong>Activity journey</strong>
                    <span>Where this work sits in the flow</span>
                  </div>
                </header>
                <div className="lux-activity-detail-popover__journey-body">
                  <div className="lux-activity-detail-popover__stage-flow" aria-label="Activity lifecycle">
                    {summary.stages.map((stage, index) => (
                      <React.Fragment key={stage.key}>
                        <div
                          className={classNames("lux-activity-detail-popover__stage", `is-${stage.tone}`, {
                            "is-active": stage.active,
                            "is-complete": stage.complete,
                          })}
                        >
                          <span>{stage.label}</span>
                        </div>
                        {index < summary.stages.length - 1 && (
                          <span className="lux-activity-detail-popover__stage-arrow" aria-hidden="true">
                            <i className="fe fe-chevron-right" />
                          </span>
                        )}
                      </React.Fragment>
                    ))}
                  </div>
                  <div className="lux-activity-detail-popover__timeline">
                    {summary.timeline.map((node) => this.renderTimelineNode(node))}
                  </div>
                  {this.renderJourneyCharts(summary.visualCharts)}
                </div>
              </section>

              {this.renderDetailMosaic(summary)}
            </div>
          </div>

          <footer className="lux-activity-detail-popover__foot">
            <div className="lux-activity-detail-popover__foot-left">
              {permission.checklistEnabled === true &&
                (item.taskType === "PROJECT" || item.taskType === "NON_PROJECT") && (
                  <button
                    type="button"
                    className={classNames("lux-activity-detail-popover__btn is-checklist", checklistClass)}
                    onClick={() => onCheklistItemClick && onCheklistItemClick(item)}
                  >
                    <i className="fa fa-wpforms" aria-hidden="true" />
                    {summary.checklistMeta.label}
                  </button>
                )}
              {this.canEditInfo() && !editEnabled && (
                <button
                  type="button"
                  className="lux-activity-detail-popover__btn is-ghost"
                  onClick={() => this.toggleEditEnabled(true)}
                >
                  <i className="fe fe-sliders" aria-hidden="true" />
                  Adjust time
                </button>
              )}
            </div>
            <div className="lux-activity-detail-popover__foot-right">
              {editEnabled && this.canEditInfo() ? (
                <>
                  <button type="button" className="lux-activity-detail-popover__btn" onClick={() => this.toggleEditEnabled(false)}>
                    Discard
                  </button>
                  <button type="button" className="lux-activity-detail-popover__btn is-primary" onClick={this.onSubmit}>
                    Save time
                  </button>
                </>
              ) : (
                <button type="button" className="lux-activity-detail-popover__btn" onClick={onClose}>
                  Close
                </button>
              )}
            </div>
          </footer>
        </div>
      </>
    );
  }
}

export default WorkItemActivityDetailPopover;
