import React, { Component } from "react";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import LuxCreateFooter from "views/common/create/LuxCreateFooter";
import LuxCreateFieldGroup, { LuxCreateField } from "views/common/create/LuxCreateFieldGroup";

export function getDefaultInvoiceGenerateForm() {
  const lastMonth = dateUtils.getCurrentTime().clone().subtract(1, "month");
  const currentMonth = dateUtils.getCurrentTime().clone();
  const lastDayOfMonth = lastMonth.clone().endOf("month");
  const twentieth = lastMonth.clone().date(20);
  const isoLocal = (m) => m.format("YYYY-MM-DDTHH:mm:ss");
  const monthName = lastMonth.format("MMMM");
  const currentMonthName = currentMonth.format("MMMM");
  return {
    createdBy: commonUtils.getCurrentUserId(),
    userTeamId: commonUtils.getCurrentUserTeamId(),
    name: `${currentMonthName} Invoice`,
    invoiceNumber: `C5${currentMonth.format("YYYYMM")}05`,
    description: `Invoice for the month of ${currentMonthName}`,
    status: "PENDING",
    invoiceDateTime: isoLocal(lastDayOfMonth),
    type: "PER_USER",
    ratePerUser: 400,
    invoiceMonthYear: isoLocal(twentieth),
    items: [
      {
        name: "Cloud Cost",
        description: "Course5i Cloud Cost",
        totalAmount: "38400.00",
      },
    ],
  };
}

class CreateInvoiceSidebar extends Component {
  constructor(props) {
    super(props);
    this.state = {
      form: getDefaultInvoiceGenerateForm(),
      formError: null,
    };
  }

  componentDidUpdate(prevProps) {
    if (this.props.show && !prevProps.show) {
      this.setState({
        form: getDefaultInvoiceGenerateForm(),
        formError: null,
      });
    }
  }

  onClose = () => {
    this.props.closeActionHandler();
  };

  resetForm = () => {
    this.setState({
      form: getDefaultInvoiceGenerateForm(),
      formError: null,
    });
  };

  onFieldChange = (field, value) => {
    this.setState((prev) => ({
      form: { ...prev.form, [field]: value },
      formError: null,
    }));
  };

  onItemChange = (index, field, value) => {
    this.setState((prev) => {
      const items = prev.form.items.map((row, i) =>
        i === index ? { ...row, [field]: value } : row
      );
      return { form: { ...prev.form, items }, formError: null };
    });
  };

  addItem = () => {
    this.setState((prev) => ({
      form: {
        ...prev.form,
        items: [
          ...prev.form.items,
          { name: "", description: "", totalAmount: "" },
        ],
      },
      formError: null,
    }));
  };

  removeItem = (index) => {
    this.setState((prev) => ({
      form: {
        ...prev.form,
        items: prev.form.items.filter((_, i) => i !== index),
      },
      formError: null,
    }));
  };

  validate = () => {
    const f = this.state.form;
    if (!f.name || !String(f.name).trim()) {
      return "Name is required.";
    }
    if (!f.invoiceNumber || !String(f.invoiceNumber).trim()) {
      return "Invoice number is required.";
    }
    if (f.createdBy == null || f.createdBy === "") {
      return "Created by (user id) is required.";
    }
    if (f.userTeamId == null || f.userTeamId === "") {
      return "User team id is required.";
    }
    if (!f.items || f.items.length === 0) {
      return "Add at least one additional line item.";
    }
    for (let i = 0; i < f.items.length; i++) {
      const row = f.items[i];
      if (!row.name || !String(row.name).trim()) {
        return `Line item ${i + 1}: name is required.`;
      }
      const amt = parseFloat(row.totalAmount);
      if (Number.isNaN(amt)) {
        return `Line item ${i + 1}: total amount must be a number.`;
      }
    }
    return null;
  };

  handleSave = () => {
    const err = this.validate();
    if (err) {
      this.setState({ formError: err });
      return;
    }
    const f = this.state.form;
    const payload = {
      createdBy: Number(f.createdBy),
      userTeamId: Number(f.userTeamId),
      name: f.name.trim(),
      invoiceNumber: f.invoiceNumber.trim(),
      description: (f.description || "").trim(),
      status: f.status,
      invoiceDateTime: f.invoiceDateTime,
      type: f.type,
      ratePerUser: Number(f.ratePerUser),
      invoiceMonthYear: f.invoiceMonthYear,
      additionalItems: {
        items: f.items.map((row) => ({
          name: row.name.trim(),
          description: (row.description || "").trim(),
          totalAmount: parseFloat(row.totalAmount),
        })),
      },
    };
    this.props.handleSubmit(payload);
  };

  onResetFormError = () => {
    this.setState({ formError: null });
  };

  renderField = (label, name, value, options = {}) => (
    <LuxCreateField>
      <label className="form-label">{label}</label>
      {options.type === "textarea" ? (
        <textarea
          className="form-control form-control-sm"
          rows={options.rows || 2}
          value={value}
          onChange={(e) => this.onFieldChange(name, e.target.value)}
        />
      ) : options.type === "select" ? (
        <select
          className="form-control form-control-sm"
          value={value}
          onChange={(e) => this.onFieldChange(name, e.target.value)}
        >
          {options.choices.map((s) => (
            <option key={s} value={s}>
              {s}
            </option>
          ))}
        </select>
      ) : (
        <input
          type={options.inputType || "text"}
          className="form-control form-control-sm"
          placeholder={options.placeholder}
          value={value != null ? value : ""}
          onChange={(e) => this.onFieldChange(name, e.target.value)}
        />
      )}
    </LuxCreateField>
  );

  render() {
    const { form, formError } = this.state;
    const statusOptions = ["DRAFT", "PENDING", "APPROVED", "PAID", "CLOSED"];

    return (
      <LuxCreatePanelShell
        show={this.props.show}
        onClose={this.onClose}
        panelId="createinvoicesidebar"
        className="lux-create-panel--invoice create_project_right_sidebar"
        kicker="Billing"
        title="Generate invoice"
        subtitle="Prefill invoice metadata and line items, then save to the directory."
      >
        {this.props.show && (
          <div className="lux-invoice-generate">
            {formError && (
              <div className="lux-create-footer__alert" role="alert">
                <i className="fe fe-alert-triangle" aria-hidden="true" />
                <span>{formError}</span>
                <button
                  type="button"
                  className="lux-create-footer__alert-dismiss"
                  onClick={this.onResetFormError}
                  aria-label="Dismiss"
                >
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              </div>
            )}

            <div className="lux-create-form lux-invoice-generate__form">
              <LuxCreateFieldGroup columns={2}>
                {this.renderField("Name", "name", form.name)}
                {this.renderField("Invoice number", "invoiceNumber", form.invoiceNumber)}
                {this.renderField("Description", "description", form.description, {
                  type: "textarea",
                  rows: 2,
                })}
                {this.renderField("Status", "status", form.status, {
                  type: "select",
                  choices: statusOptions,
                })}
                {this.renderField("Type", "type", form.type)}
                {this.renderField("Rate per user", "ratePerUser", form.ratePerUser, {
                  inputType: "number",
                })}
                {this.renderField("Invoice date / time", "invoiceDateTime", form.invoiceDateTime, {
                  placeholder: "YYYY-MM-DDTHH:mm:ss",
                })}
                {this.renderField("Invoice month-year", "invoiceMonthYear", form.invoiceMonthYear, {
                  placeholder: "YYYY-MM-DDTHH:mm:ss",
                })}
                {this.renderField("Created by (user id)", "createdBy", form.createdBy, {
                  inputType: "number",
                })}
                {this.renderField("User team id", "userTeamId", form.userTeamId, {
                  inputType: "number",
                })}
              </LuxCreateFieldGroup>

              <section className="lux-create-section lux-invoice-generate__items">
                <header className="lux-create-section__head">
                  <span className="lux-create-section__icon" aria-hidden="true">
                    <i className="fe fe-list" />
                  </span>
                  <div>
                    <h3 className="lux-create-section__title">Additional items</h3>
                    <p className="lux-create-section__hint">Line items included on the generated invoice.</p>
                  </div>
                  <button
                    type="button"
                    className="lux-invoice-generate__add-btn"
                    onClick={this.addItem}
                  >
                    <i className="fe fe-plus" aria-hidden="true" /> Add item
                  </button>
                </header>
                <div className="lux-create-section__body">
                  <div className="lux-invoice-generate__table-wrap">
                    <table className="lux-invoice-generate__table">
                      <thead>
                        <tr>
                          <th>Name</th>
                          <th>Description</th>
                          <th>Total</th>
                          <th aria-label="Actions" />
                        </tr>
                      </thead>
                      <tbody>
                        {form.items.map((row, index) => (
                          <tr key={index}>
                            <td>
                              <input
                                type="text"
                                className="form-control form-control-sm"
                                value={row.name}
                                onChange={(e) =>
                                  this.onItemChange(index, "name", e.target.value)
                                }
                              />
                            </td>
                            <td>
                              <input
                                type="text"
                                className="form-control form-control-sm"
                                value={row.description}
                                onChange={(e) =>
                                  this.onItemChange(index, "description", e.target.value)
                                }
                              />
                            </td>
                            <td>
                              <input
                                type="text"
                                className="form-control form-control-sm"
                                value={row.totalAmount}
                                onChange={(e) =>
                                  this.onItemChange(index, "totalAmount", e.target.value)
                                }
                              />
                            </td>
                            <td>
                              <button
                                type="button"
                                className="lux-invoice-generate__remove"
                                title="Remove row"
                                disabled={form.items.length <= 1}
                                onClick={() => this.removeItem(index)}
                              >
                                <i className="fe fe-trash-2" aria-hidden="true" />
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </section>
            </div>

            <LuxCreateFooter
              hasFormError={!!formError}
              onResetFormError={this.onResetFormError}
              handleSubmit={() => this.handleSave()}
              initializeRequest={this.resetForm}
              isProcessing={this.props.isProcessing}
              createButtonLabel="Save invoice"
              disableKeepMeOpen
            />
          </div>
        )}
      </LuxCreatePanelShell>
    );
  }
}

export default CreateInvoiceSidebar;
