import React, { Component } from "react";
import { connect } from "react-redux";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import { accessUtils } from "_helpers";
import { employeeActions } from "_actions";
import { appConfigActions } from "_actions";
import { userActions } from "_actions";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import ProfilePageSideSecuritySettings from "./components/fragments/ProfilePageSideSecuritySettings";
import ApplicationConfigSection from "./components/ApplicationConfigSection";
import ProfilePageHero from "./components/ProfilePageHero";
import ProfilePageNav, { ProfileViewConst } from "./components/ProfilePageNav";
import ProfilePageAside from "./components/ProfilePageAside";
import ProfileDetailsBackNav from "./components/ProfileDetailsBackNav";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "views/common/fragments/luxSkeleton.constants";
import ProfilePersonalView from "./components/profile/ProfilePersonalView";
import ProfileExitDateAdmin from "./components/profile/ProfileExitDateAdmin";
import ProfilePreferencesView from "./components/profile/ProfilePreferencesView";
import ProfileNotificationsView from "./components/profile/ProfileNotificationsView";
import ProfileAccountActivityView from "./components/profile/ProfileAccountActivityView";
import ProfilePageSkeleton from "./components/profile/ProfilePageSkeleton";
import {
    buildAccessTabStats,
    buildActivityTabStats,
    buildPersonalTabStats,
    buildSecurityTabStats,
    buildSettingsTabStats,
    getProfileEmployeeLabel,
} from "./components/profile/profileDetailsTab.utils";

class ProfilePage extends Component {
    constructor() {
        super();
        this.state = {
            selectedSideNavValue: ProfileViewConst.PERSONAL,
            permission: accessUtils.getEmployeeAccessControl(),
        };
    }

    componentDidMount() {
        this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);

        let urlEmployeeId = this.props.match.params.employeeId;
        if (!urlEmployeeId) {
            urlEmployeeId = commonUtils.getCurrentUserId();
        }
        store.dispatch(this.props.getEmployeesInfo(urlEmployeeId));
    }

    onChangeSideNavMenu = (value) => {
        this.setState({ selectedSideNavValue: value });
    };

    refreshUserRole = () => {
        store.dispatch(userActions.authRefresh());
    };

    handleUpdateUserExitDate = (employeeId, exitDate) => {
        store.dispatch(this.props.updateEmployeeExitDate(employeeId, exitDate));
    };

    isReadOnlyProfile = () => {
        const { selectedEmployeeInfo } = this.props;
        return selectedEmployeeInfo && selectedEmployeeInfo.id !== commonUtils.getCurrentUserId();
    };

    renderMainContent = () => {
        const { selectedEmployeeInfo } = this.props;
        const { selectedSideNavValue, permission } = this.state;
        const readOnly = this.isReadOnlyProfile();

        if (!selectedEmployeeInfo) return null;

        switch (selectedSideNavValue) {
            case ProfileViewConst.PERSONAL:
                return (
                    <ProjectDetailsTabShell
                        icon="fe fe-user"
                        eyebrow="Identity"
                        title="Personal information"
                        subtitle="Contact, employment, practice, credentials, and platform access for this employee."
                        stats={buildPersonalTabStats(selectedEmployeeInfo)}
                    >
                        <div className="lux-settings-tab__stack profile-personal-wrap">
                            <ProfilePersonalView employee={selectedEmployeeInfo} />
                            {permission.updateUserExitDateEnabled && (
                                <ProfileExitDateAdmin
                                    employee={selectedEmployeeInfo}
                                    fieldConfig={this.props.fieldConfig}
                                    onUpdate={this.handleUpdateUserExitDate}
                                />
                            )}
                        </div>
                    </ProjectDetailsTabShell>
                );

            case ProfileViewConst.ACCESS:
                return (
                    <ProjectDetailsTabShell
                        icon="fe fe-key"
                        eyebrow="Permissions"
                        title="Access control"
                        subtitle="Role-based capabilities assigned to this employee. Read-only mirror of the live access matrix."
                        stats={buildAccessTabStats(selectedEmployeeInfo)}
                    >
                        <div className="lux-settings-tab__stack profile-access-wrap">
                            <button
                                type="button"
                                className="profile-access-refresh lux-pd-tab__link-btn"
                                onClick={this.refreshUserRole}
                                title="Refresh permissions"
                            >
                                <i className="fa fa-refresh" aria-hidden="true" />
                                Refresh my session permissions
                            </button>
                            <AccessControl
                                getAppConfig={this.props.getAppConfig}
                                selectedConfigData={this.props.selectedConfigData}
                                roleId={selectedEmployeeInfo.userRole}
                            />
                        </div>
                    </ProjectDetailsTabShell>
                );

            case ProfileViewConst.SECURITY:
                return (
                    <ProjectDetailsTabShell
                        icon="fe fe-shield"
                        eyebrow="Account"
                        title="Security settings"
                        subtitle="Sign-in identity and password management for this profile."
                        stats={buildSecurityTabStats(selectedEmployeeInfo, readOnly)}
                    >
                        <ProfilePageSideSecuritySettings selectedEmployeeInfo={selectedEmployeeInfo} />
                    </ProjectDetailsTabShell>
                );

            case ProfileViewConst.ACTIVITIES:
                return (
                    <ProjectDetailsTabShell
                        icon="fe fe-activity"
                        eyebrow="Audit"
                        title="Account activity"
                        subtitle="In-app actions and security events recorded for this employee."
                        stats={buildActivityTabStats(selectedEmployeeInfo)}
                    >
                        <ProfileAccountActivityView
                            employee={selectedEmployeeInfo}
                            readOnly={readOnly}
                        />
                    </ProjectDetailsTabShell>
                );

            case ProfileViewConst.PREFERENCE:
                return (
                    <ProjectDetailsTabShell
                        icon="fe fe-sliders"
                        eyebrow="Workspace"
                        title="Preferences"
                        subtitle="Landing page, layout density, and regional display defaults."
                        stats={buildSettingsTabStats(selectedEmployeeInfo, readOnly)}
                    >
                        <ProfilePreferencesView employee={selectedEmployeeInfo} readOnly={readOnly} />
                    </ProjectDetailsTabShell>
                );

            case ProfileViewConst.NOTIFICATIONS:
                return (
                    <ProjectDetailsTabShell
                        icon="fe fe-bell"
                        eyebrow="Alerts"
                        title="Notifications"
                        subtitle="Channels and categories for timesheet, HR, project, and security alerts."
                        stats={buildSettingsTabStats(selectedEmployeeInfo, readOnly)}
                    >
                        <ProfileNotificationsView employee={selectedEmployeeInfo} readOnly={readOnly} />
                    </ProjectDetailsTabShell>
                );

            default:
                return null;
        }
    };

    render() {
        const { selectedEmployeeInfo, getInfoLoading } = this.props;
        const readOnly = this.isReadOnlyProfile();
        const employeeLabel = getProfileEmployeeLabel(selectedEmployeeInfo);

        return (
            <div className="pd-page profile-page lux-project-details-page">
                <ProfileDetailsBackNav
                    location={this.props.location}
                    employeeLabel={employeeLabel}
                />

                <ProfilePageHero
                    employee={selectedEmployeeInfo}
                    readOnly={readOnly}
                    loading={getInfoLoading}
                />

                {selectedEmployeeInfo && (
                    <ProfilePageNav
                        activeView={this.state.selectedSideNavValue}
                        onSelect={this.onChangeSideNavMenu}
                        readOnly={readOnly}
                    />
                )}

                <div className="pd-page__body profile-page__body">
                    {getInfoLoading && <ProfilePageSkeleton />}

                    {!getInfoLoading && selectedEmployeeInfo && (
                        <div className="pd-workspace profile-page__workspace">
                            <main className="pd-workspace__main profile-page__main">
                                {this.renderMainContent()}
                            </main>
                            <ProfilePageAside employee={selectedEmployeeInfo} />
                        </div>
                    )}

                    {!getInfoLoading && !selectedEmployeeInfo && (
                        <LuxRegisterEmptyState
                            className="lux-register-empty--compact pd-empty profile-page__empty"
                            variant="employees"
                            eyebrow="People directory"
                            title="Profile not found"
                            description="This employee may not exist or you may not have permission to view their profile."
                            hints={[
                                "Confirm the employee ID in the URL",
                                "Search the roster from the employees register",
                                "Check team scope if the person was recently added",
                            ]}
                        />
                    )}
                </div>
            </div>
        );
    }
}

class AccessControl extends Component {
    componentDidMount() {
        store.dispatch(this.props.getAppConfig(this.props.roleId, "role"));
    }

    componentDidUpdate(prevProps) {
        if (prevProps.roleId !== this.props.roleId) {
            store.dispatch(this.props.getAppConfig(this.props.roleId, "role"));
        }
    }

    render() {
        if (!this.props.selectedConfigData) {
            return (
                <div className="profile-access-empty" role="status" aria-busy="true" aria-label="Loading access configuration">
                    <SkeletonTheme baseColor={LUX_SKELETON_THEME.baseColor} highlightColor={LUX_SKELETON_THEME.highlightColor}>
                        {[1, 2, 3, 4, 5].map((key) => (
                            <Skeleton key={key} height={48} borderRadius={10} style={{ marginBottom: 10 }} />
                        ))}
                    </SkeletonTheme>
                </div>
            );
        }

        return (
            <fieldset className="profile-access-fieldset" disabled>
                <ApplicationConfigSection
                    data={this.props.selectedConfigData}
                    onChange={() => {}}
                    readOnly
                />
            </fieldset>
        );
    }
}

const mapStateToProps = state => ({
    currentUser: state.authentication.user,
    selectedEmployeeInfo: state.employees.selectedEmployeeInfo,
    getInfoLoading: state.employees.getInfoLoading,
    selectedConfigData: state.appconfig.selectedConfigData,
    fieldConfig: state.employees.fieldConfig,
});

const mapDispatchToProps = () => ({
    getEmployeesInfo: employeeActions.getEmployeesInfo,
    getAppConfig: appConfigActions.getAppConfig,
    updateEmployeeExitDate: employeeActions.updateEmployeeExitDate,
});

export default connect(mapStateToProps, mapDispatchToProps)(ProfilePage);
