import React from "react";
import classNames from "classnames/bind";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import ProjectServiceLineView from "./fragments/ProjectServiceLineView";
import ProjectEstimateInput from "./fragments/ProjectEstimateInput";
import ItemChecklistInput from "./fragments/ItemChecklistInput";

const TimelineStep = ({ label, value, active }) => (
  <div className={classNames("pd-timeline__step", { "is-active": active })}>
    <span className="pd-timeline__dot" />
    <div className="pd-timeline__content">
      <span className="pd-timeline__label">{label}</span>
      <span className="pd-timeline__value">{value || "—"}</span>
    </div>
  </div>
);

export default function ProjectDetailsRightRail({
  item,
  readOnly,
  embedded,
  permission,
  projectEstimateRequest,
  onEstimateChange,
  handleUpdateEstimate,
  onUpdateChecklist,
}) {
  if (!item) return null;

  const teamEstimate =
    projectEstimateRequest ||
    (item.projectEstimate && item.projectEstimate.teamEstimate);
  const hasTeamEstimate =
    teamEstimate && typeof teamEstimate === "object" && Object.keys(teamEstimate).length > 0;
  const showEstimate = !readOnly || hasTeamEstimate;

  return (
    <aside
      className={classNames("pd-workspace__aside", "pd-rail", { "pd-rail--embedded": embedded })}
      aria-label="Timeline, estimates, and checklist"
    >
      <header className="pd-rail__head">
        <span className="pd-rail__eyebrow">Project context</span>
        <p className="pd-rail__hint">Schedule, effort, and delivery checklist</p>
      </header>

      <article className="pd-card pd-card--timeline">
        <header className="pd-card__head">
          <span className="pd-card__icon">
            <i className="fe fe-clock" />
          </span>
          <h2 className="pd-card__title">Timeline</h2>
        </header>
        <div className="pd-timeline">
          <TimelineStep
            label="Start"
            value={dateUtils.convertDateFormat(item.estStartTime)}
            active
          />
          <TimelineStep
            label="Due"
            value={dateUtils.convertDateFormat(item.estCompletionTime)}
            active={item.status === "INPROGRESS" || item.status === "ASSIGNED"}
          />
          <TimelineStep label="Created" value={dateUtils.convertDateTimeFormat(item.createdDate)} />
          {item.lastModifiedDate && (
            <TimelineStep
              label="Last updated"
              value={dateUtils.convertDateTimeFormat(item.lastModifiedDate)}
            />
          )}
        </div>
        <div className="pd-meta-list">
          {item.createdByDetails && (
            <div className="pd-meta-list__row">
              <span>Created by</span>
              <strong>{item.createdByDetails.name}</strong>
            </div>
          )}
          {item.updatedByDetails && (
            <div className="pd-meta-list__row">
              <span>Updated by</span>
              <strong>{item.updatedByDetails.name}</strong>
            </div>
          )}
        </div>
      </article>

      {permission.viewServiceLineEstimate && (
        <ProjectServiceLineView item={item} permission={permission} />
      )}

      {showEstimate && (
        <ProjectEstimateInput
          projectEstimateRequest={teamEstimate}
          onChange={onEstimateChange}
          handleUpdateEstimate={handleUpdateEstimate}
          projectInfo={item}
          name="teamEstimate"
          readOnly={readOnly}
          projectItem={item}
          userTeams={
            item.restrictedByUserTeamDetails && item.restrictedByUserTeamDetails.length > 0
              ? item.restrictedByUserTeamDetails
              : commonUtils.getUserTeamsFromUserItem()
          }
        />
      )}

      {permission.checklistEnabled && (
        <ItemChecklistInput
          handleUpdateChecklist={onUpdateChecklist}
          type="PROJECT"
          readOnly={readOnly}
          permission={permission}
          checklistData={item.checklistData}
          itemUserTeamId={item.userTeamId}
        />
      )}
    </aside>
  );
}
