/** Top inset for fixed right-side planner overlays (below app + page toolbars). */
export function measurePlannerOverlayTop() {
  if (typeof document === "undefined") return 0;
  let top = 0;
  const pageTop = document.getElementById("page_top");
  if (pageTop) {
    top = Math.max(top, pageTop.getBoundingClientRect().bottom);
  }
  const innerHeader = document.querySelector(".lux-planner-page .lux-page-header");
  if (innerHeader) {
    const rect = innerHeader.getBoundingClientRect();
    if (rect.height > 0 && rect.top <= top + 8) {
      top = Math.max(top, rect.bottom);
    }
  }
  return Math.max(0, Math.round(top));
}
