import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import { connect } from "react-redux";
import { workItemConstants } from "_constants";
import { accessUtils } from "_helpers";
import { store } from "_helpers";
import EmployeeImage from "./fragments/EmployeeImage";
import classNames from "classnames/bind";
import { employeeConstants } from "_constants";

class PageLeftMenubar extends Component {
  constructor() {
    super()
    this.state = {
      permission: accessUtils.getMenuAccessControl()
    };
  }
  toggleTodayActivitySidebar = () => {
    store.dispatch({ type: workItemConstants.SHOW_TODAYS_ACTIVITY_WINDOW })
  }

  toggleNotesOverlay = () => {
    const open = this.props.showNotesOverlay === true;
    store.dispatch({
      type: open
        ? workItemConstants.CLOSE_NOTES_OVERLAY_WINDOW
        : workItemConstants.SHOW_NOTES_OVERLAY_WINDOW,
    });
  }

  toggleUserDivSidebar = () => {
    store.dispatch({ type: employeeConstants.TOGGLE_USER_DIV_WINDOW })
  }
  isDisabled = (module, linkName) => {
    return this.state.permission && this.state.permission[module] && this.state.permission[module][linkName] === false;
  }

  renderBrandImages = () => (
    <>
      <img className="lux-rail-brand-favicon iconrotate" src="/favicon.ico" alt="" />
      <img
        className="lux-rail-brand-c5i"
        alt="C5i"
        src="/assets/images/custom/c5i-logo.png"
      />
    </>
  );

  render() {
    const notesOverlayOpen = this.props.showNotesOverlay === true;
    const notesEnabled = !this.isDisabled("projectModules", "todolistEnabled");

    return (
      <div id="header_top" className="header_top no-print lux-rail">
        <div className="container">
          <div className="hleft">
            {this.isDisabled("projectModules", "dashboardEnabled") &&
              <NavLink to={"/project/dashboard"} className="header-brand" data-ga-action="nav_dashboard" data-ga-category="navigation" data-ga-label="Dashboard">
                {this.renderBrandImages()}
              </NavLink>
            }
            {!this.isDisabled("projectModules", "dashboardEnabled") &&
              <button type="button" className="link header-brand" data-ga-action="nav_brand" data-ga-category="navigation" data-ga-label="Brand">
                {this.renderBrandImages()}
              </button>
            }

            <div className="dropdown lux-rail__nav">
              <NavLink to={"/project/search"} className={classNames("nav-link icon lux-rail__icon-btn", { "disabled colorlightgray": this.isDisabled("projectModules", "searchEnabled") })} activeClassName="active" data-ga-action="nav_search" data-ga-category="navigation" data-ga-label="Search" title="Search"><i className="fe fe-search" aria-hidden="true" /></NavLink>
              <NavLink to={"/project/taskboard"} className={classNames("nav-link icon lux-rail__icon-btn", { "disabled colorlightgray": this.isDisabled("projectModules", "taskboardEnabled") })} activeClassName="active" data-ga-action="nav_taskboard" data-ga-category="navigation" data-ga-label="Taskboard" title="Taskboard"><i className="fe fe-check-square" aria-hidden="true" /></NavLink>
              <NavLink to={"/project/calendar"} className={classNames("nav-link icon lux-rail__icon-btn", { "disabled colorlightgray": this.isDisabled("projectModules", "calendarEnabled") })} activeClassName="active" data-ga-action="nav_calendar" data-ga-category="navigation" data-ga-label="Calendar" title="Calendar"><i className="fe fe-calendar" aria-hidden="true" /></NavLink>
              {notesEnabled && (
                <button
                  type="button"
                  className={classNames("nav-link icon lux-rail__icon-btn lux-rail__notes-btn", {
                    active: notesOverlayOpen,
                  })}
                  onClick={this.toggleNotesOverlay}
                  data-ga-action="nav_notes_overlay"
                  data-ga-category="navigation"
                  data-ga-label="Notes overlay"
                  title="Pending notes"
                  aria-pressed={notesOverlayOpen}
                >
                  <i className="fe fe-book-open" aria-hidden="true" />
                </button>
              )}
              <NavLink to={"/project/chat"} className={classNames("nav-link icon lux-rail__icon-btn disabled d-none d-md-inline-flex", { "disabled colorlightgray": this.isDisabled("projectModules", "chatEnabled") })} activeClassName="active" data-ga-action="nav_chat" data-ga-category="navigation" data-ga-label="Chat" title="Chat"><i className="fe fe-message-circle" aria-hidden="true" /></NavLink>
              <NavLink to={"/project/filemanager"} className={classNames("nav-link icon lux-rail__icon-btn disabled d-none d-md-inline-flex", { "disabled colorlightgray": this.isDisabled("projectModules", "filemanagerEnabled") })} activeClassName="active" data-ga-action="nav_filemanager" data-ga-category="navigation" data-ga-label="File manager" title="Files"><i className="fe fe-folder" aria-hidden="true" /></NavLink>
            </div>
          </div>
          <div className="hright">
            <div className="dropdown lux-rail__tools">
              <button type="button" className="link nav-link icon lux-rail__icon-btn theme_btn d-none d-md-inline-flex" data-ga-action="nav_themes" data-ga-category="navigation" data-ga-label="Themes" title="Color palette"><i className="fe fe-droplet" aria-hidden="true" data-toggle="tooltip" data-placement="right" title="Color palette" /></button>
              <NavLink to={"/hrms/appconfig"} className={classNames("nav-link icon lux-rail__icon-btn", { "disabled colorlightgray": this.isDisabled("hrmsModules", "appconfigEnabled") })} activeClassName="active" data-ga-action="nav_appconfig" data-ga-category="navigation" data-ga-label="App config" title="App config"><i className="fe fe-sliders" aria-hidden="true" /></NavLink>
              <button type="button" className="link nav-link icon lux-rail__icon-btn settingbar" data-ga-action="nav_settings" data-ga-category="navigation" data-ga-label="Settings" title="Settings"><i className="fe fe-settings" aria-hidden="true" data-toggle="tooltip" data-placement="right" title="Settings" /></button>
              <button type="button" className="link nav-link icon lux-rail__icon-btn iconfaq_btn todayactivity" onClick={() => this.toggleTodayActivitySidebar()} data-ga-action="nav_today_activity" data-ga-category="navigation" data-ga-label="Today activity" title="Today activity"><i className="fe fe-activity" aria-hidden="true" /></button>

              <button type="button" className="link nav-link lux-rail__avatar-btn user_btn" onClick={() => this.toggleUserDivSidebar()} data-ga-action="nav_user_menu" data-ga-category="navigation" data-ga-label="User menu" title="Profile">
                <EmployeeImage employee={this.props.authentication && this.props.authentication.user} classes={"avatar"} />
              </button>
              <button type="button" className="link nav-link icon lux-rail__icon-btn lux-rail__menu-toggle menu_toggle" data-ga-action="nav_menu_toggle" data-ga-category="navigation" data-ga-label="Menu toggle" title="Menu"><i className="fe fe-menu" aria-hidden="true" /></button>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  showNotesOverlay: state.workItem && state.workItem.showNotesOverlay,
  authentication: state.authentication,
});

export default connect(mapStateToProps)(PageLeftMenubar);
