import React, { Component } from "react";
import LuxListCountSkeleton from "views/common/fragments/LuxListCountSkeleton";
import LuxRegisterListSkeletonRows from "views/common/fragments/LuxRegisterListSkeletonRows";
import classNames from "classnames/bind";
import ProjectInfoLine from "./ProjectInfoLine";
import LuxRegisterPagination from "views/common/fragments/LuxRegisterPagination";
import { REGISTER_PAGE_SIZE_OPTIONS } from "_helpers/registerPagination.utils";

const LIST_COLUMNS = [
  { key: "fav", label: "", icon: "fe-star" },
  { key: "id", label: "Ref", icon: "fe-hash" },
  { key: "created", label: "Created", icon: "fe-calendar" },
  { key: "study", label: "Project", icon: "fe-layers" },
  { key: "account", label: "Account", icon: "fe-briefcase" },
  { key: "metrics", label: "Progress", icon: "fe-activity" },
  { key: "dates", label: "Timeline", icon: "fe-clock" },
  { key: "status", label: "Status", icon: "fe-flag", center: true },
  { key: "actions", label: "", center: true },
];

class ProjectListTable extends Component {
  render() {
    const count =
      this.props.totalCount != null
        ? this.props.totalCount
        : this.props.items
        ? this.props.items.length
        : 0;

    return (
      <div className="lux-bid-list-shell">
        <div className="lux-bid-list-shell__bar">
          <span className="lux-bid-list-shell__label">
            <i className="fe fe-list" aria-hidden="true" />
            Project register
          </span>
          <div className="lux-bid-list-shell__actions">
            <span className="lux-bid-list-shell__count">
              {this.props.isLoading ? <LuxListCountSkeleton /> : `${count} record${count === 1 ? "" : "s"}`}
            </span>
            <button
              type="button"
              className={this.props.isLoading ? "lux-bid-list-shell__refresh is-loading" : "lux-bid-list-shell__refresh"}
              title="Refresh list"
              aria-label="Refresh project list"
              onClick={() => this.props.reloadProjectList()}
            >
              <i className="fe fe-refresh-cw" aria-hidden="true" />
            </button>
          </div>
        </div>

        <div className="lux-bid-list" aria-label="Projects">
          <div className="lux-bid-list__head" role="row">
            {LIST_COLUMNS.map((col) => (
              <div
                key={col.key}
                className={["lux-bid-list__head-cell", `lux-bid-list__head-cell--${col.key}`, col.center ? "is-center" : ""].filter(Boolean).join(" ")}
                role="columnheader"
              >
                {col.icon && col.label ? (
                  <span className="lux-bid-list__head-label"><i className={`fe ${col.icon}`} aria-hidden="true" />{col.label}</span>
                ) : (
                  <span className="lux-bid-list__head-label lux-bid-list__head-label--sr">{col.key === "actions" ? "Actions" : "Favorite"}</span>
                )}
              </div>
            ))}
          </div>

          <div
            className={classNames("lux-bid-list__body", { "is-loading": this.props.isLoading })}
            role="list"
          >
            {this.props.isLoading && (
              <LuxRegisterListSkeletonRows
                variant="bid"
                pageSize={this.props.pagination && this.props.pagination.pageSize}
              />
            )}
            {!this.props.isLoading && this.props.items && this.props.items.map((item) => (
              <ProjectInfoLine
                item={item}
                key={item.id}
                handleDeleteProject={this.props.handleDeleteProject}
                handleEditProject={this.props.handleEditProject}
                handleUpdateStatus={this.props.handleUpdateStatus}
                handleDuplicateProject={this.props.handleDuplicateProject}
                handleArchiveProject={this.props.handleArchiveProject}
                handleRemoveProject={this.props.handleRemoveProject}
                handleFavoriteProject={this.props.handleFavoriteProject}
                onViewProject={this.props.onViewProject}
                permission={this.props.permission}
              />
            ))}
          </div>
        </div>

        {this.props.pagination && !this.props.isLoading && this.props.pagination.total > 0 && (
          <LuxRegisterPagination
            pagination={this.props.pagination}
            onPageChange={this.props.onPageChange}
            onPageSizeChange={this.props.onPageSizeChange}
            pageSizeOptions={REGISTER_PAGE_SIZE_OPTIONS}
            summaryLabel={this.props.paginationSummaryLabel || "projects"}
            className="lux-register-list__pagination"
          />
        )}
      </div>
    );
  }
}

export default ProjectListTable;
