const STORAGE_PATH_KEY = "tracopus:projectDetails:returnPath";
const STORAGE_LABEL_KEY = "tracopus:projectDetails:returnLabel";

const PROJECT_DETAILS_PATH_RE = /^\/project\/details\//;

/** Routes scoped to one project — not used as “back” from main project details. */
const PROJECT_DRILLDOWN_PATH_RES = [
  /^\/project\/deliverables\//,
  /^\/project\/deliverable\//,
];

const RETURN_LABEL_RULES = [
  { test: (p) => p.startsWith("/project/list"), label: "Projects" },
  { test: (p) => p.startsWith("/project/dashboard"), label: "Dashboard" },
  { test: (p) => p.startsWith("/project/deliverables"), label: "Deliverables" },
  { test: (p) => p.startsWith("/project/deliverable"), label: "Deliverable" },
  { test: (p) => p.startsWith("/project/taskboard"), label: "Taskboard" },
  { test: (p) => p.startsWith("/project/capacity"), label: "Team capacity" },
  { test: (p) => p.startsWith("/project/accounts"), label: "Accounts" },
  { test: (p) => p.startsWith("/project/search"), label: "Search" },
  { test: (p) => p.startsWith("/project/activites"), label: "Task activity" },
  { test: (p) => p.startsWith("/project/reports"), label: "Reports" },
  { test: (p) => p.startsWith("/project/feedback"), label: "Feedback" },
  { test: (p) => p.startsWith("/project/files"), label: "Files" },
  { test: (p) => p.startsWith("/project/chat"), label: "Chat" },
  { test: (p) => p.startsWith("/project/todolist"), label: "Notes" },
  { test: (p) => p.startsWith("/project/purchaseorder"), label: "Purchase order" },
  { test: (p) => p.startsWith("/sales/bidrequests"), label: "Bid requests" },
  { test: (p) => p.startsWith("/sales/purchaseorders"), label: "Purchase orders" },
  { test: (p) => p.startsWith("/sales/"), label: "Sales" },
  { test: (p) => p.startsWith("/hrms/"), label: "HRMS" },
];

const DEFAULT_RETURN = { path: "/project/list", label: "Projects" };

export function isProjectDetailsPath(pathname = "") {
  return PROJECT_DETAILS_PATH_RE.test(pathname);
}

export function isProjectDrilldownPath(pathname = "") {
  const path = (pathname || "").split("?")[0];
  return PROJECT_DRILLDOWN_PATH_RES.some((re) => re.test(path));
}

function isSafeReturnPath(path) {
  if (!path || typeof path !== "string" || !path.startsWith("/")) return false;
  const pathname = path.split("?")[0];
  if (isProjectDetailsPath(pathname)) return false;
  if (isProjectDrilldownPath(pathname)) return false;
  return /^\/(project|sales|hrms)\//.test(path);
}

export function getReturnLabelForPath(path) {
  const pathname = (path || "").split("?")[0];
  const rule = RETURN_LABEL_RULES.find((r) => r.test(pathname));
  return rule ? rule.label : "previous page";
}

export function captureProjectDetailsReturn(fromPathname, fromSearch = "") {
  const path = `${fromPathname || ""}${fromSearch || ""}`;
  if (!isSafeReturnPath(path)) {
    return;
  }
  try {
    sessionStorage.setItem(STORAGE_PATH_KEY, path);
    sessionStorage.setItem(STORAGE_LABEL_KEY, getReturnLabelForPath(path));
  } catch (_e) {
    /* ignore quota / private mode */
  }
}

function readStoredReturn() {
  try {
    const path = sessionStorage.getItem(STORAGE_PATH_KEY);
    const label = sessionStorage.getItem(STORAGE_LABEL_KEY);
    if (path && isSafeReturnPath(path)) {
      return { path, label: label || getReturnLabelForPath(path) };
    }
  } catch (_e) {
    /* ignore */
  }
  return null;
}

export function getProjectDetailsReturnTarget(location) {
  const stateFrom = location && location.state && location.state.from;
  if (stateFrom && isSafeReturnPath(stateFrom)) {
    return {
      path: stateFrom,
      label: location.state.fromLabel || getReturnLabelForPath(stateFrom),
    };
  }

  const stored = readStoredReturn();
  if (stored) return stored;

  return DEFAULT_RETURN;
}

export function buildProjectDetailsLink(projectIdOrRef, fromLocation, fromLabel) {
  const pathname = `/project/details/${projectIdOrRef}`;
  if (!fromLocation) return { pathname };

  const from =
    (fromLocation.pathname || "") + (fromLocation.search || "");
  const state = { from };
  if (fromLabel) state.fromLabel = fromLabel;
  return { pathname, state };
}
