import React, { Component } from "react";
import classNames from "classnames/bind";
import { connect } from "react-redux";
import { taskActions } from "_actions";
import { store } from "_helpers";
import dateUtils from "_helpers/date.utils";
import SelectInput from "views/common/fragments/formfields/SelectInput";

class DeliverableDetailsHero extends Component {
  handleUpdateStatus = (taskId, status) => {
    store.dispatch(this.props.updateTaskStatus(taskId, status));
  };

  render() {
    const { item, permission, readOnly } = this.props;
    if (!item) return null;

    const projectName = item.projectInfo && item.projectInfo.name;

    return (
      <header className="pd-hero lux-del-hero">
        <div className="pd-hero__glow" aria-hidden="true" />
        <div className="pd-hero__inner">
          <div className="pd-hero__identity">
            <span className="pd-hero__badge">
              {item.ownerUserTeamDetails && item.ownerUserTeamDetails.name}
              {projectName && ` · ${projectName}`}
            </span>
            <span className="pd-hero__id">{item.itemIdUserTeamPrefix}</span>
            <h1 className="pd-hero__title">
              {item.code && <span className="pd-hero__code">[{item.code}]</span>} {item.name}
            </h1>
            <div className="pd-hero__chips">
              <span className="pd-chip pd-chip--soft">
                <i className="fe fe-user" />{" "}
                {(item.ownerDetails && item.ownerDetails.name) || "Unassigned"}
              </span>
              <span className="pd-chip pd-chip--soft">
                <i className="fe fe-calendar" /> Due{" "}
                {dateUtils.convertDateFormat(item.estCompletionTime)}
              </span>
              {item.category && (
                <span className="pd-chip pd-chip--accent">{item.category}</span>
              )}
            </div>
          </div>
          <div className="pd-hero__actions">
            <SelectInput
              options={[
                { value: "NEW", label: "New", level: 0 },
                { value: "ASSIGNED", label: "Assigned", level: 1 },
                { value: "INPROGRESS", label: "In Progress", level: 2 },
                { value: "COMPLETED", label: "Completed", level: 3 },
                { value: "CLOSED", label: "Closed", level: 4 },
              ]}
              value={item.status}
              allowLevelDown={permission.allowStatusLevelDown}
              changeableStatus={permission.changeableStatus}
              isReadOnly={!permission.allowStatusChange || readOnly}
              itemId={item.id}
              onChange={this.handleUpdateStatus}
              className={classNames(
                "tag pd-hero__status",
                { "tag-info": item.status === "NEW" },
                { "tag-primary": item.status === "ASSIGNED" },
                { "tag-warning": item.status === "INPROGRESS" },
                { "tag-success": item.status === "COMPLETED" },
                { "tag-dark": item.status === "CLOSED" }
              )}
            />
          </div>
        </div>
      </header>
    );
  }
}

const mapDispatchToProps = () => ({
  updateTaskStatus: taskActions.updateTaskStatus,
});

export default connect(null, mapDispatchToProps)(DeliverableDetailsHero);
