import React, { Component } from "react";
import ProjectDetailsHeader from "./components/ProjectDetailsHeader";
import ProjectDetailsHero from "./components/ProjectDetailsHero";
import ProjectDetailsGeneral from "./components/ProjectDetailsGeneral";
import ProjectDetailsCalendar from "./components/ProjectDetailsCalendar";
import ProjectDetailsActivity from "./components/ProjectDetailsActivity";
import ProjectDetailsMembers from "./components/ProjectDetailsMembers";
import ProjectDetailsNotification from "./components/ProjectDetailsNotification";
import ProjectDetailsFiles from "./components/ProjectDetailsFiles";
import ProjectDetailsDashboard from "./components/ProjectDetailsDashboard";
import { connect } from "react-redux";
import { projectActions } from "_actions";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import { dashboardActions } from "_actions";
import { accessUtils } from "_helpers";
import FeedbackPageSection from "./components/FeedbackPageSection";
import { ProjectDetailViewNameConst } from "./components/ProjectDetailsHeader";
import ProjectDetailsBackNav from "./components/ProjectDetailsBackNav";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxDetailPageSkeleton from "views/common/fragments/LuxDetailPageSkeleton";

export { ProjectDetailViewNameConst };

class ProjectDetailsPage extends Component {
  constructor() {
    super();
    this.state = {
      projectDetailViewName: ProjectDetailViewNameConst.GENERAL,
      permission: accessUtils.getProjectAccessControl()
    };
  }

  resolveRouteProjectId = () =>
    commonUtils.removeNameIntial(this.props.match.params.projectId);

  loadProjectIfNeeded = () => {
    const projectId = this.resolveRouteProjectId();
    const current = this.props.projectInfo;
    const currentKey =
      current &&
      (current.id === projectId || current.itemIdUserTeamPrefix === projectId);
    if (!currentKey) {
      store.dispatch(this.props.getProjectInfo(projectId));
    }
    if (this.state.projectId !== projectId) {
      this.setState({ projectId });
    }
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(
      this.props.routeProp.name + " : " + this.props.match.params.projectId
    );
    this.loadProjectIfNeeded();

    const urlViewName = this.getViewByName(
      new URLSearchParams(this.props.location.search).get("view")
    );
    this.changeProjectDetailsView(urlViewName);
    this.setState({ projectEstimateRequest: null });
  }

  componentDidUpdate(prevProps) {
    if (prevProps.match.params.projectId !== this.props.match.params.projectId) {
      this.loadProjectIfNeeded();
    }
  }

  getViewByName = (viewName) => {
    if (viewName) {
      switch (viewName) {
        case "general": return ProjectDetailViewNameConst.GENERAL;
        case "dashboard": return ProjectDetailViewNameConst.DASHBOARD;
        case "activity": return ProjectDetailViewNameConst.ACTIVITY;
        case "calendar": return ProjectDetailViewNameConst.CALENDAR;
        case "members": return ProjectDetailViewNameConst.MEMBERS;
        case "notification": return ProjectDetailViewNameConst.NOTIFICATION;
        case "files": return ProjectDetailViewNameConst.FILES;
        case "feedback": return ProjectDetailViewNameConst.FEEDBACK;
        default: break;
      }
    }
    return ProjectDetailViewNameConst.GENERAL;
  };

  changeProjectDetailsView = (viewName) => {
    this.setState({ projectDetailViewName: viewName });
  };

  onEstimateChange = (name, projectEstimateRequest) => {
    this.setState({
      projectEstimateRequest: {
        [name]: { ...projectEstimateRequest }
      }
    });
  };

  handleUpdateEstimate = () => {
    store.dispatch(this.props.updateProjectEstimate(this.state.projectEstimateRequest, this.state.projectId));
  };

  renderViewContent = () => {
    const { projectInfo, isLoading, taskStatisticsByCategory, getTaskStatisticsByCategory } = this.props;
    const { permission, projectDetailViewName, projectEstimateRequest } = this.state;
    const readOnly = (!commonUtils.hasAccess(projectInfo, permission.allowAccessToOtherUserTeamProjects)) || projectInfo.deleted;
    const tabProps = { projectInfo, isLoading, readOnly, permission };

    switch (projectDetailViewName) {
      case ProjectDetailViewNameConst.GENERAL:
        return (
          <ProjectDetailsGeneral
            isLoading={this.props.isLoading}
            item={projectInfo}
            showHero={false}
            projectEstimateRequest={(projectEstimateRequest && projectEstimateRequest.teamEstimate) || (projectInfo.projectEstimate && projectInfo.projectEstimate.teamEstimate)}
            onEstimateChange={this.onEstimateChange}
            handleUpdateEstimate={this.handleUpdateEstimate}
            readOnly={readOnly}
            permission={permission}
            taskStatisticsByCategory={this.props.taskStatisticsByCategory}
            getTaskStatisticsByCategory={this.props.getTaskStatisticsByCategory}
            itemId={projectInfo.id}
            onNavigateFeedback={() => this.changeProjectDetailsView(ProjectDetailViewNameConst.FEEDBACK)}
          />
        );
      case ProjectDetailViewNameConst.FEEDBACK:
        return <FeedbackPageSection projectItem={projectInfo} feedbackType="PROJECT" />;
      case ProjectDetailViewNameConst.DASHBOARD:
        return (
          <ProjectDetailsDashboard
            {...tabProps}
            taskStatisticsByCategory={taskStatisticsByCategory}
            getTaskStatisticsByCategory={getTaskStatisticsByCategory}
          />
        );
      case ProjectDetailViewNameConst.ACTIVITY:
        return <ProjectDetailsActivity {...tabProps} />;
      case ProjectDetailViewNameConst.FILES:
        return <ProjectDetailsFiles {...tabProps} />;
      case ProjectDetailViewNameConst.NOTIFICATION:
        return <ProjectDetailsNotification {...tabProps} />;
      case ProjectDetailViewNameConst.MEMBERS:
        return <ProjectDetailsMembers {...tabProps} />;
      case ProjectDetailViewNameConst.CALENDAR:
        return <ProjectDetailsCalendar {...tabProps} />;
      default:
        return null;
    }
  };

  render() {
    const { projectInfo } = this.props;
    const { permission, projectDetailViewName } = this.state;
    const hasAccess = projectInfo && commonUtils.hasAccess(projectInfo, permission.allowAccessToOtherUserTeamProjects);
    const readOnly = hasAccess ? (projectInfo.deleted) : true;

    return (
      <div className="pd-page lux-project-details-page">
        <ProjectDetailsBackNav
          location={this.props.location}
          projectRef={projectInfo && projectInfo.itemIdUserTeamPrefix}
        />
        {hasAccess &&
          <>
            <ProjectDetailsHero
              item={projectInfo}
              permission={permission}
              readOnly={readOnly}
            />
            <ProjectDetailsHeader
              projectInfo={projectInfo}
              activeView={projectDetailViewName}
              headerSelect={this.changeProjectDetailsView}
            />
          </>
        }

        <div className="pd-page__body">
          {projectInfo && hasAccess && this.renderViewContent()}

          {this.props.isLoading && !projectInfo && (
            <LuxDetailPageSkeleton ariaLabel="Loading project" />
          )}

          {!this.props.isLoading && projectInfo && !hasAccess && (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact pd-empty"
              variant="projects"
              eyebrow="Access"
              title="Access restricted"
              description="You may not have permission to view this project."
              hints={[
                "Ask a project owner to add you to the team",
                "Switch teams in the header if you manage multiple groups",
                "Return to the portfolio and open a project you can access",
              ]}
            />
          )}

          {!this.props.isLoading && !projectInfo && (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact pd-empty"
              variant="projects"
              eyebrow="Project workspace"
              title="No project details found"
              description="You may not have permission to view this project, or it may have been removed."
              hints={[
                "Confirm the project ID in the URL",
                "Open the project from the portfolio list",
                "Verify team membership and access rights",
              ]}
            />
          )}
        </div>
      </div>
    );
  }
}

const mapStateToProps = state => ({
  authentication: state.authentication,
  projectInfo: state.projects.selectedProjectInfo,
  isLoading: state.projects.getInfoLoading,
  taskStatisticsByCategory: state.dashboard.taskStatisticsByCategory
});
const mapDispatchToProps = dispatch => ({
  getProjectInfo: projectActions.getProjectInfo,
  updateProjectEstimate: projectActions.updateProjectEstimate,
  getTaskStatisticsByCategory: dashboardActions.getTaskStatisticsByCategory,
});
export default connect(mapStateToProps, mapDispatchToProps)(ProjectDetailsPage);
