import { getLeaveHolidayKind } from "views/hrms/components/timesheet/timesheetBoard.utils";

/** Parse logged work minutes per employee per day (excludes leave/holiday rows). */
export function parseTimesheetActualsByEmployee(timesheetByEmployee) {
  const result = {};
  if (!timesheetByEmployee) return result;

  Object.keys(timesheetByEmployee).forEach((employeeId) => {
    const sheet = timesheetByEmployee[employeeId];
    const byDay = {};
    ["project", "nonProject"].forEach((timesheetType) => {
      const groups = sheet && sheet[timesheetType];
      if (!groups) return;
      Object.keys(groups).forEach((groupId) => {
        const isLeave =
          timesheetType === "nonProject" &&
          getLeaveHolidayKind(groupId, null);
        if (isLeave) return;

        const tasks = groups[groupId] && groups[groupId].tasks;
        if (!tasks) return;
        tasks.forEach((task) => {
          const cat = (task.taskActCategory || "").toLowerCase();
          if (cat === "leave" || cat === "holiday") return;
          const timeEntry = task.timeEntry || {};
          Object.keys(timeEntry).forEach((dateString) => {
            const mins = parseInt(timeEntry[dateString].timesheetTimeMins || 0, 10);
            if (mins <= 0) return;
            byDay[dateString] = (byDay[dateString] || 0) + mins;
          });
        });
      });
    });
    result[String(employeeId)] = byDay;
  });

  return result;
}

export function getActualMinutesForDay(actualsByEmployee, employeeId, dayKey) {
  const emp = actualsByEmployee && actualsByEmployee[String(employeeId)];
  if (!emp) return 0;
  return emp[dayKey] || 0;
}

export function loadTeamTimesheetData(loadTimeSheetData, employeeIds, startDate, endDate) {
  const ids = (employeeIds || []).filter((id) => id != null);
  if (ids.length === 0) return Promise.resolve({});

  return new Promise((resolve) => {
    loadTimeSheetData(startDate, endDate, ids, [], (payload) => {
      if (!payload) {
        resolve({});
        return;
      }
      if (payload.byEmployee) {
        resolve(payload.byEmployee);
        return;
      }
      if (ids.length === 1) {
        resolve({ [String(ids[0])]: payload });
        return;
      }
      const byEmployee = {};
      ids.forEach((id) => {
        const key = String(id);
        byEmployee[key] =
          (payload[key] != null && payload[key]) ||
          (payload.employeeId != null && String(payload.employeeId) === key ? payload : null);
      });
      if (Object.keys(byEmployee).some((k) => byEmployee[k])) {
        resolve(byEmployee);
        return;
      }
      ids.forEach((id) => {
        byEmployee[String(id)] = payload;
      });
      resolve(byEmployee);
    });
  });
}

export function formatVarianceLabel(plannedMins, actualMins) {
  const delta = actualMins - plannedMins;
  const sign = delta > 0 ? "+" : "";
  return {
    plannedMins,
    actualMins,
    deltaMins: delta,
    label: `${sign}${Math.round(delta / 60 * 10) / 10}h vs plan`,
  };
}
