import React from "react";
import classNames from "classnames/bind";
import {
  getRestrictedTeamCount,
  getTemplateEditorMode,
  resolveOptionLabel,
} from "./feedbackTemplateEditor.utils";

export default function LuxFeedbackTemplateEditorHero({
  feedbackTemplateRequest,
  editMode,
  questionCount,
  feedbackTypeOptions,
  feedbackSubTypeOptions,
  onNewTemplate,
}) {
  const req = feedbackTemplateRequest || {};
  const mode = getTemplateEditorMode(req, editMode);
  const typeLabel = resolveOptionLabel(feedbackTypeOptions, req.type);
  const subTypeLabel = resolveOptionLabel(feedbackSubTypeOptions, req.subType);
  const teamCount = getRestrictedTeamCount(req.restrictedByUserTeamIds);

  const chips = [];
  if (typeLabel) chips.push({ icon: "fe-tag", label: typeLabel });
  if (subTypeLabel) chips.push({ icon: "fe-filter", label: subTypeLabel });
  chips.push({
    icon: "fe-help-circle",
    label: `${questionCount} question${questionCount === 1 ? "" : "s"}`,
  });
  if (teamCount > 0) {
    chips.push({ icon: "fe-users", label: `${teamCount} team${teamCount === 1 ? "" : "s"}` });
  } else if (req.id || editMode) {
    chips.push({ icon: "fe-globe", label: "All teams" });
  }

  return (
    <header
      className={classNames("lux-ft-hero", `lux-ft-hero--${mode.tone}`)}
      aria-label="Template editor status"
    >
      <div className="lux-ft-hero__glow" aria-hidden="true" />
      <div className="lux-ft-hero__inner">
        <div className="lux-ft-hero__main">
          <div className="lux-ft-hero__badges">
            <span className={classNames("lux-ft-hero__mode-pill", `is-${mode.tone}`)}>
              <i className={`fe ${mode.icon}`} aria-hidden="true" />
              {mode.kicker}
            </span>
            {req.itemIdUserTeamPrefix && (
              <span className="lux-ft-hero__ref">{req.itemIdUserTeamPrefix}</span>
            )}
          </div>
          <h2 className="lux-ft-hero__title">{mode.title}</h2>
          <p className="lux-ft-hero__subtitle">{mode.subtitle}</p>
          <ul className="lux-ft-hero__chips" aria-label="Template summary">
            {chips.map((chip) => (
              <li key={chip.label} className="lux-ft-hero__chip">
                <i className={`fe ${chip.icon}`} aria-hidden="true" />
                {chip.label}
              </li>
            ))}
            {!editMode && req.id && (
              <li className="lux-ft-hero__chip is-muted">
                <i className="fe fe-lock" aria-hidden="true" />
                Read-only
              </li>
            )}
          </ul>
        </div>

        <div className="lux-ft-hero__aside">
          {req.id && (
            <a
              className="lux-ft-hero__action lux-ft-hero__action--preview"
              href={`/document/feedback/template/${req.id}`}
              target="_blank"
              rel="noopener noreferrer"
            >
              <i className="fe fe-external-link" aria-hidden="true" />
              Open preview
            </a>
          )}
          {onNewTemplate && (req.id || mode.id === "idle") && (
            <button
              type="button"
              className="lux-ft-hero__action lux-ft-hero__action--ghost"
              onClick={onNewTemplate}
            >
              <i className="fe fe-plus" aria-hidden="true" />
              New template
            </button>
          )}
        </div>
      </div>
    </header>
  );
}
