const TYPE_META = {
  boolean: { label: "Yes / No", icon: "fe-toggle-left", tone: "violet" },
  string: { label: "Text", icon: "fe-type", tone: "sky" },
  number: { label: "Number", icon: "fe-hash", tone: "amber" },
  rating: { label: "Rating", icon: "fe-star", tone: "gold" },
  date: { label: "Date", icon: "fe-calendar", tone: "slate" },
};

export function getQuestionTypeMeta(type, typeOptions = []) {
  const option = typeOptions.find((t) => t.value === type);
  const base = TYPE_META[type] || { label: type || "Question", icon: "fe-help-circle", tone: "slate" };
  return {
    ...base,
    label: (option && option.label) || base.label,
    multi: option && option.multi === true,
  };
}

function questionSortIndex(question) {
  return typeof question.index === "number" ? question.index : 0;
}

export function sortQuestions(questionDataList) {
  if (!questionDataList || !questionDataList.length) return [];
  return [...questionDataList].sort(
    (a, b) => questionSortIndex(a) - questionSortIndex(b)
  );
}

/** Clone template for editor state — stable question keys and indices. */
export function normalizeFeedbackTemplateForEditor(template) {
  if (!template) return template;
  const baseId = template.id || "draft";
  const questionDataList = (template.questionDataList || []).map((q, i) => ({
    ...q,
    index: typeof q.index === "number" ? q.index : i,
    id: q.id != null && q.id !== "" ? q.id : `fb-q-${baseId}-${i}`,
  }));
  return {
    ...template,
    questionDataList,
  };
}
