import React from "react";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "./luxSkeleton.constants";
import { getRegisterSkeletonRowKeys } from "./luxRegisterListSkeleton.utils";

const VARIANTS = {
  bid: {
    itemClass: "lux-bid-list__item",
    columns: [
      { circle: 28 },
      { width: 48 },
      { width: 64 },
      { flex: true },
      { width: 72 },
      { width: 52 },
      { width: 56 },
      { width: 68 },
      { width: 32 },
    ],
  },
  emp: {
    itemClass: "lux-emp-list__item",
    columns: [
      { flex: true },
      { width: 88 },
      { width: 64 },
      { width: 128 },
      { width: 72 },
      { width: 80 },
      { width: 32 },
    ],
  },
  inv: {
    itemClass: "lux-inv-list__item",
    columns: [
      { flex: true },
      { width: 80 },
      { width: 44 },
      { width: 72 },
      { width: 72 },
      { width: 32 },
    ],
  },
  taskboard: {
    itemClass: "lux-taskboard-list__item",
    columns: [
      { width: 28 },
      { flex: true },
      { width: 72 },
      { width: 88 },
      { flex: true },
      { width: 56 },
      { width: 96 },
    ],
  },
  schedule: {
    itemClass: "lux-schedule-row",
    columns: [
      { width: 24 },
      { width: 64 },
      { flex: true },
      { width: 96 },
      { width: 112 },
    ],
  },
  acctdir: {
    itemClass: "lux-acct-dir-row",
    columns: [
      { circle: 44 },
      { flex: true },
      { width: 120 },
      { width: 72 },
    ],
  },
};

function SkeletonCell({ col, height = 14 }) {
  if (col.circle) {
    return <Skeleton circle width={col.circle} height={col.circle} />;
  }
  if (col.flex) {
    return (
      <Skeleton
        height={height}
        borderRadius={6}
        containerClassName="lux-register-skeleton-cell lux-register-skeleton-cell--flex"
      />
    );
  }
  return <Skeleton width={col.width} height={height} borderRadius={6} />;
}

/**
 * Full-width register list skeleton rows (matches grid column layout per variant).
 */
export default function LuxRegisterListSkeletonRows({
  variant = "bid",
  rowCount,
  pageSize,
  cellHeight = 14,
}) {
  const config = VARIANTS[variant] || VARIANTS.bid;
  const keys = getRegisterSkeletonRowKeys(rowCount, pageSize);

  return (
    <SkeletonTheme
      baseColor={LUX_SKELETON_THEME.baseColor}
      highlightColor={LUX_SKELETON_THEME.highlightColor}
    >
      {keys.map((key) => (
        <div key={key} className={`${config.itemClass} is-skeleton`} aria-hidden="true">
          {config.columns.map((col, idx) => (
            <SkeletonCell key={idx} col={col} height={cellHeight} />
          ))}
        </div>
      ))}
    </SkeletonTheme>
  );
}
