const STORAGE_PATH_KEY = "tracopus:deliverableDetails:returnPath";
const STORAGE_LABEL_KEY = "tracopus:deliverableDetails:returnLabel";

const DELIVERABLE_DETAIL_PATH_RE = /^\/project\/deliverable\//;

const DELIVERABLE_DRILLDOWN_PATH_RES = [/^\/project\/workitems\//];

const RETURN_LABEL_RULES = [
  { test: (p) => p.startsWith("/project/deliverables"), label: "Deliverables" },
  { test: (p) => p.startsWith("/project/details"), label: "Project" },
  { test: (p) => p.startsWith("/project/list"), label: "Projects" },
  { test: (p) => p.startsWith("/project/dashboard"), label: "Dashboard" },
  { test: (p) => p.startsWith("/project/capacity"), label: "Team capacity" },
  { test: (p) => p.startsWith("/project/activites"), label: "Task activity" },
];

export function isDeliverableDetailsPath(pathname = "") {
  return DELIVERABLE_DETAIL_PATH_RE.test(pathname);
}

export function isDeliverableDrilldownPath(pathname = "") {
  const path = (pathname || "").split("?")[0];
  return DELIVERABLE_DRILLDOWN_PATH_RES.some((re) => re.test(path));
}

function getDefaultReturn(taskInfo) {
  const projectRef =
    taskInfo &&
    taskInfo.projectInfo &&
    (taskInfo.projectInfo.itemIdUserTeamPrefix || taskInfo.projectInfo.id);
  if (projectRef) {
    return { path: `/project/deliverables/${projectRef}`, label: "Deliverables" };
  }
  return { path: "/project/list", label: "Projects" };
}

function isSafeReturnPath(path) {
  if (!path || typeof path !== "string" || !path.startsWith("/")) return false;
  const pathname = path.split("?")[0];
  if (isDeliverableDetailsPath(pathname)) return false;
  if (isDeliverableDrilldownPath(pathname)) return false;
  return /^\/(project|sales|hrms)\//.test(pathname);
}

export function getReturnLabelForPath(path) {
  const pathname = (path || "").split("?")[0];
  const rule = RETURN_LABEL_RULES.find((r) => r.test(pathname));
  return rule ? rule.label : "previous page";
}

export function captureDeliverableDetailsReturn(fromPathname, fromSearch = "") {
  const path = `${fromPathname || ""}${fromSearch || ""}`;
  if (!isSafeReturnPath(path)) return;
  try {
    sessionStorage.setItem(STORAGE_PATH_KEY, path);
    sessionStorage.setItem(STORAGE_LABEL_KEY, getReturnLabelForPath(path));
  } catch (_e) {
    /* ignore */
  }
}

function readStoredReturn(taskInfo) {
  try {
    const path = sessionStorage.getItem(STORAGE_PATH_KEY);
    const label = sessionStorage.getItem(STORAGE_LABEL_KEY);
    if (path && isSafeReturnPath(path)) {
      return { path, label: label || getReturnLabelForPath(path) };
    }
  } catch (_e) {
    /* ignore */
  }
  return getDefaultReturn(taskInfo);
}

export function getDeliverableDetailsReturnTarget(location, taskInfo) {
  const stateFrom = location && location.state && location.state.from;
  if (stateFrom && isSafeReturnPath(stateFrom)) {
    return {
      path: stateFrom,
      label: location.state.fromLabel || getReturnLabelForPath(stateFrom),
    };
  }
  return readStoredReturn(taskInfo);
}

export function buildDeliverableDetailsLink(taskIdOrRef, fromLocation, fromLabel) {
  const pathname = `/project/deliverable/${taskIdOrRef}`;
  if (!fromLocation) return { pathname };
  const from = (fromLocation.pathname || "") + (fromLocation.search || "");
  const state = { from };
  if (fromLabel) state.fromLabel = fromLabel;
  return { pathname, state };
}
