import originalMoment from "moment";
import { extendMoment } from "moment-range";

const moment = extendMoment(originalMoment);

export function isFutureDay(dayMonth) {
  return dayMonth.clone().startOf("day").isAfter(moment().startOf("day"));
}

export function isToday(dayMonth) {
  return dayMonth.isSame(moment(), "day");
}

export function getDayMeta(dayMonth) {
  const weekday = dayMonth.weekday();
  return {
    isSaturday: weekday === 5,
    isSunday: weekday === 6,
    isWeekend: weekday === 5 || weekday === 6,
    isToday: isToday(dayMonth),
    isFuture: isFutureDay(dayMonth),
    dayNum: dayMonth.format("D"),
    dayShort: dayMonth.format("ddd"),
  };
}

export function normalizeMarkDate(markDate) {
  if (!markDate) return null;
  const value = String(markDate);
  return value.length >= 10 ? value.substring(0, 10) : value;
}

export function findAttendanceItem(items, employeeId, dayMonth) {
  if (!items || !items.length) return null;
  const key = dayMonth.format("YYYY-MM-DD");
  return (
    items.find(
      (item) =>
        String(item.employeeId) === String(employeeId) &&
        normalizeMarkDate(item.markDate) === key
    ) || null
  );
}

export function countAttendanceForDate(items, dateKey) {
  if (!items || !items.length) return 0;
  return items.filter((item) => normalizeMarkDate(item.markDate) === dateKey).length;
}

export function getEmployeeStats(employeeId, items, monthDays) {
  const today = moment().startOf("day");
  const elapsedDays = monthDays.filter((day) => day.clone().startOf("day").isSameOrBefore(today));
  const present = items
    ? items.filter((item) => String(item.employeeId) === String(employeeId)).length
    : 0;
  const elapsed = elapsedDays.length;
  const absent = Math.max(0, elapsed - present);
  const rate = elapsed > 0 ? Math.round((present / elapsed) * 100) : 0;

  return { present, absent, rate, elapsed };
}

export function buildAttendanceSummary(employees, items, monthDays, selectedDate) {
  const today = moment().startOf("day");
  const elapsedDays = monthDays.filter((day) => day.clone().startOf("day").isSameOrBefore(today));
  const workingDays = monthDays.filter((day) => {
    const wd = day.weekday();
    return wd !== 5 && wd !== 6;
  });
  const elapsedWorkingDays = workingDays.filter((day) =>
    day.clone().startOf("day").isSameOrBefore(today)
  );

  const employeeCount = employees ? employees.length : 0;
  const totalMarks = items ? items.length : 0;
  const maxPossible = employeeCount * elapsedDays.length;
  const teamRate = maxPossible > 0 ? Math.round((totalMarks / maxPossible) * 100) : 0;
  const totalAbsent = Math.max(0, maxPossible - totalMarks);

  return {
    employeeCount,
    totalMarks,
    totalAbsent,
    monthLabel: selectedDate.format("MMMM YYYY"),
    monthShort: selectedDate.format("MMM YYYY"),
    daysInMonth: monthDays.length,
    workingDays: workingDays.length,
    elapsedDays: elapsedDays.length,
    elapsedWorkingDays: elapsedWorkingDays.length,
    teamRate,
    avgDaysPerEmployee: employeeCount > 0 ? (totalMarks / employeeCount).toFixed(1) : "0",
  };
}

export function buildAttendanceDashboard(employees, items, monthDays, currentUserId) {
  const today = moment().startOf("day");
  const elapsedDays = monthDays.filter((day) => day.clone().startOf("day").isSameOrBefore(today));
  const employeeCount = employees ? employees.length : 0;

  const dailyTrend = monthDays.map((day) => {
    const key = day.format("YYYY-MM-DD");
    const meta = getDayMeta(day);
    const present = meta.isFuture ? 0 : countAttendanceForDate(items, key);
    const possible = meta.isFuture ? 0 : employeeCount;
    const absent = meta.isFuture ? 0 : Math.max(0, possible - present);
    const rate =
      !meta.isFuture && possible > 0 ? Math.round((present / possible) * 100) : 0;
    return {
      key,
      label: day.format("D"),
      fullLabel: day.format("ddd, MMM D"),
      present,
      absent,
      possible,
      rate,
      ...meta,
    };
  });

  const weeklyTrend = [];
  for (let i = 0; i < monthDays.length; i += 7) {
    const chunk = monthDays.slice(i, i + 7);
    let present = 0;
    let possible = 0;
    let elapsedInChunk = 0;
    chunk.forEach((day) => {
      if (isFutureDay(day)) return;
      elapsedInChunk += 1;
      const key = day.format("YYYY-MM-DD");
      present += countAttendanceForDate(items, key);
      possible += employeeCount;
    });
    const hasFuture = chunk.some((day) => isFutureDay(day));
    weeklyTrend.push({
      label: `Week ${weeklyTrend.length + 1}`,
      range: `${chunk[0].format("MMM D")} – ${chunk[chunk.length - 1].format("D")}`,
      present,
      possible,
      rate: possible > 0 ? Math.round((present / possible) * 100) : 0,
      isFuture: hasFuture && elapsedInChunk === 0,
      isPartial: hasFuture && elapsedInChunk > 0,
    });
  }

  const rankings = (employees || [])
    .map((emp) => ({
      id: emp.id,
      name: emp.name,
      designation: emp.designation,
      isCurrentUser: emp.id === currentUserId,
      ...getEmployeeStats(emp.id, items, monthDays),
    }))
    .sort((a, b) => b.rate - a.rate || b.present - a.present);

  const distribution = {
    excellent: rankings.filter((row) => row.rate >= 90).length,
    good: rankings.filter((row) => row.rate >= 70 && row.rate < 90).length,
    attention: rankings.filter((row) => row.rate < 70 && row.elapsed > 0).length,
  };

  const todayKey = moment().format("YYYY-MM-DD");
  const todayPresent = countAttendanceForDate(items, todayKey);
  const todayAbsent = Math.max(0, employeeCount - todayPresent);

  const totalPresent = items ? items.length : 0;
  const totalPossible = employeeCount * elapsedDays.length;
  const totalAbsent = Math.max(0, totalPossible - totalPresent);

  const coverageMix = [
    {
      label: "Present",
      count: totalPresent,
      tone: "green",
      pct: totalPossible > 0 ? Math.round((totalPresent / totalPossible) * 100) : 0,
    },
    {
      label: "Absent",
      count: totalAbsent,
      tone: "red",
      pct: totalPossible > 0 ? Math.round((totalAbsent / totalPossible) * 100) : 0,
    },
  ];

  const distributionMix = [
    {
      label: "90%+",
      count: distribution.excellent,
      tone: "green",
      pct:
        employeeCount > 0 ? Math.round((distribution.excellent / employeeCount) * 100) : 0,
    },
    {
      label: "70–89%",
      count: distribution.good,
      tone: "blue",
      pct: employeeCount > 0 ? Math.round((distribution.good / employeeCount) * 100) : 0,
    },
    {
      label: "Below 70%",
      count: distribution.attention,
      tone: "amber",
      pct:
        employeeCount > 0 ? Math.round((distribution.attention / employeeCount) * 100) : 0,
    },
  ];

  let bestDay = null;
  let lowestDay = null;
  dailyTrend.forEach((day) => {
    if (day.isFuture || !day.possible) return;
    if (!bestDay || day.rate > bestDay.rate) bestDay = day;
    if (!lowestDay || day.rate < lowestDay.rate) lowestDay = day;
  });

  const elapsedTrend = dailyTrend.filter((day) => !day.isFuture);

  return {
    dailyTrend,
    weeklyTrend,
    coverageMix,
    distributionMix,
    distribution,
    todaySnapshot: {
      present: todayPresent,
      absent: todayAbsent,
      total: employeeCount,
      rate: employeeCount > 0 ? Math.round((todayPresent / employeeCount) * 100) : 0,
    },
    topPerformers: rankings.filter((row) => row.rate >= 70).slice(0, 5),
    needsAttention: [...rankings].reverse().filter((row) => row.rate < 70 && row.elapsed > 0).slice(0, 5),
    bestDay,
    lowestDay,
    avgDailyRate:
      elapsedTrend.length > 0
        ? Math.round(elapsedTrend.reduce((sum, day) => sum + day.rate, 0) / elapsedTrend.length)
        : 0,
  };
}

export function filterEmployeesById(employees, selectedEmployeeId) {
  if (!employees || !employees.length) return employees || [];
  if (selectedEmployeeId == null || selectedEmployeeId === "") {
    return employees;
  }
  return employees.filter((employee) => String(employee.id) === String(selectedEmployeeId));
}

export function sortEmployeesCurrentFirst(employees, currentUserId) {
  if (!employees || !employees.length) return [];
  const list = [...employees];
  list.sort((a, b) => {
    if (currentUserId && a.id === currentUserId) return -1;
    if (currentUserId && b.id === currentUserId) return 1;
    return (a.name || "").localeCompare(b.name || "");
  });
  return list;
}

export function findCurrentUserEmployee(employees, currentUserId) {
  if (!employees || !currentUserId) return null;
  return employees.find((emp) => emp.id === currentUserId) || null;
}

export function combineDateAndTime(dayMonth, timeValue) {
  if (!dayMonth || !timeValue) return null;
  const parts = String(timeValue).split(":");
  const hours = parseInt(parts[0], 10) || 0;
  const minutes = parseInt(parts[1], 10) || 0;
  return dayMonth.clone().hour(hours).minute(minutes).second(0).millisecond(0);
}

export function addHoursToTimeValue(timeValue, hours) {
  if (!timeValue || hours == null || hours === "") return "";
  const parts = String(timeValue).split(":");
  const baseMins = (parseInt(parts[0], 10) || 0) * 60 + (parseInt(parts[1], 10) || 0);
  const totalMins = baseMins + Math.round(parseFloat(hours) * 60);
  const wrapped = ((totalMins % (24 * 60)) + 24 * 60) % (24 * 60);
  const h = Math.floor(wrapped / 60);
  const m = wrapped % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

export function parseTimeFromMarkDateTime(value) {
  if (!value) return "";
  const str = String(value);
  const match = str.match(/T(\d{2}):(\d{2})/);
  if (match) return `${match[1]}:${match[2]}`;
  const d = new Date(str);
  if (Number.isNaN(d.getTime())) return "";
  return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}

export function formatAttendanceTimeDisplay(value) {
  const time = parseTimeFromMarkDateTime(value);
  if (!time) return "—";
  const [h, m] = time.split(":").map((part) => parseInt(part, 10) || 0);
  const period = h >= 12 ? "PM" : "AM";
  const h12 = h % 12 || 12;
  return `${h12}:${String(m).padStart(2, "0")} ${period}`;
}

export function getAttendanceRecordDetails(item) {
  if (!item) {
    return {
      startTimeLabel: "—",
      checkoutTimeLabel: "—",
      hoursLabel: "—",
    };
  }

  const hours =
    item.hours != null && item.hours !== "" && Number.isFinite(Number(item.hours))
      ? Number(item.hours)
      : null;

  return {
    startTimeLabel: formatAttendanceTimeDisplay(item.markTime || item.markDate),
    checkoutTimeLabel: formatAttendanceTimeDisplay(item.checkoutTime),
    hoursLabel: hours != null ? `${hours}h` : "—",
  };
}

export function buildDefaultMarkForm(dayMonth) {
  const meta = getDayMeta(dayMonth);
  const now = moment();
  const startTime = meta.isToday ? now.format("HH:mm") : "09:00";
  const defaultHours = meta.isToday
    ? Math.max(0.5, Math.round(((now.hour() * 60 + now.minute() - (9 * 60)) / 60) * 2) / 2)
    : 8;
  const hours = defaultHours > 0 ? defaultHours : 8;

  return {
    startTime,
    hours: String(hours),
    checkoutTime: addHoursToTimeValue(startTime, hours),
    checkoutAuto: true,
  };
}

export function buildAttendanceMarkPayload(dayMonth, form) {
  const startMoment = combineDateAndTime(dayMonth, form.startTime);
  const checkoutMoment = form.checkoutTime
    ? combineDateAndTime(dayMonth, form.checkoutTime)
    : null;
  const hoursValue =
    form.hours !== "" && form.hours != null ? parseFloat(form.hours) : null;

  return {
    markDate: dayMonth.clone().startOf("day").format("YYYY-MM-DDTHH:mm:ss.SSS"),
    markTime: startMoment ? startMoment.format("YYYY-MM-DDTHH:mm:ss.SSS") : null,
    hours: Number.isFinite(hoursValue) ? hoursValue : null,
    checkoutTime: checkoutMoment ? checkoutMoment.format("YYYY-MM-DDTHH:mm:ss.SSS") : null,
  };
}
