import React from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { enrichWorkItemDetail } from "../plannerHourly.utils";

function clamp(left, width, pad = 12) {
  const maxLeft = typeof window !== "undefined" ? window.innerWidth - width - pad : left;
  return Math.max(pad, Math.min(left, maxLeft));
}

export default function PlannerTimelineSegmentPopover({ segment, anchorRect, onClose }) {
  if (!segment || !anchorRect || typeof document === "undefined") return null;

  const d = enrichWorkItemDetail(segment.item, segment.minutes);
  const popoverWidth = 300;
  const left = clamp(anchorRect.left, popoverWidth);
  const top = anchorRect.bottom + 8;
  const flipAbove = typeof window !== "undefined" && top + 200 > window.innerHeight;
  const style = {
    position: "fixed",
    left,
    top: flipAbove ? anchorRect.top - 8 : top,
    width: popoverWidth,
    zIndex: 1080,
    transform: flipAbove ? "translateY(-100%)" : undefined,
  };

  return createPortal(
    <div
      className="lux-planner-timeline-popover"
      style={style}
      role="tooltip"
      onMouseEnter={(e) => e.stopPropagation()}
      onMouseLeave={onClose}
    >
      <div className="lux-planner-timeline-popover__accent" style={{ background: d.statusColor }} />
      <div className="lux-planner-timeline-popover__body">
        <span className={classNames("lux-planner-timeline-popover__status", `is-${d.statusMeta.tone}`)}>
          <i className={`fe ${d.statusMeta.icon}`} />
          {d.statusMeta.label}
        </span>
        <strong>{segment.label || d.item.name}</strong>
        <p>{[d.projectName, d.taskName].filter(Boolean).join(" · ")}</p>
        <dl>
          <div>
            <dt>Schedule</dt>
            <dd>
              {segment.startLabel} – {segment.endLabel}
            </dd>
          </div>
          <div>
            <dt>Planned</dt>
            <dd>{d.durationLabel}</dd>
          </div>
          <div>
            <dt>Owner</dt>
            <dd>{d.employeeLabel}</dd>
          </div>
        </dl>
        <span className="lux-planner-timeline-popover__hint">Click for full details</span>
      </div>
    </div>,
    document.body
  );
}
