import React, { Component } from "react";
import ReactDatePicker from "react-datepicker";
import classNames from "classnames/bind";
import LoadingButton from "views/common/fragments/LoadingButton";

/**
 * Luxury footer for create/update panels. Same behavior as SidebarFooter.
 */
class LuxCreateFooter extends Component {
  constructor(props) {
    super(props);
    this.state = {
      createAnotherEnabled: false,
      keepDataEnabled: false,
    };
  }

  onCreateAnotherEnabled = (value) => {
    this.setState({ createAnotherEnabled: value });
  };

  onKeepDataEnabled = (value) => {
    this.setState({ keepDataEnabled: value });
  };

  render() {
    const {
      hasFormError,
      onResetFormError,
      editMode,
      duplicateMode,
      disableKeepMeOpen,
      keepDataOptionEnabled,
      effectiveUpdateDateEnabled,
      mappingObject,
      onEffectiveDateDateChange,
      isProcessing,
      handleSubmit,
      initializeRequest,
      createButtonLabel,
      closeButtonLabel,
      wizardMode,
      wizardStepIndex,
      wizardStepCount,
      onWizardBack,
      onWizardNext,
      canWizardNext,
    } = this.props;

    const isFirstWizardStep = wizardStepIndex === 0;
    const isLastWizardStep = wizardStepIndex >= wizardStepCount - 1;

    return (
      <footer className="lux-create-footer">
        {hasFormError && (
          <div className="lux-create-footer__alert" role="alert">
            <i className="fe fe-alert-triangle" aria-hidden="true" />
            <span>Please complete the mandatory fields before submitting.</span>
            <button
              type="button"
              className="lux-create-footer__alert-dismiss"
              onClick={onResetFormError}
              aria-label="Dismiss"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </div>
        )}

        <div className="lux-create-footer__bar">
          <div className="lux-create-footer__options">
            {!editMode && !duplicateMode && !disableKeepMeOpen && (
              <label className="lux-create-footer__check">
                <input
                  type="checkbox"
                  checked={this.state.createAnotherEnabled}
                  onChange={(e) => this.onCreateAnotherEnabled(e.target.checked)}
                />
                <span>Keep panel open</span>
              </label>
            )}
            {this.state.createAnotherEnabled === true && keepDataOptionEnabled && (
              <label className="lux-create-footer__check">
                <input
                  type="checkbox"
                  checked={this.state.keepDataEnabled}
                  onChange={(e) => this.onKeepDataEnabled(e.target.checked)}
                />
                <span>Keep entered data</span>
              </label>
            )}
            {editMode && effectiveUpdateDateEnabled && mappingObject && (
              <label className="lux-create-footer__effective">
                <span>Effective date</span>
                <ReactDatePicker
                  selected={
                    !mappingObject.effectiveDate
                      ? new Date()
                      : typeof mappingObject.effectiveDate === "string"
                        ? new Date(mappingObject.effectiveDate)
                        : mappingObject.effectiveDate
                  }
                  onChange={(selectedValue) => onEffectiveDateDateChange(selectedValue)}
                  dateFormat="yyyy-MM-dd"
                />
              </label>
            )}
          </div>

          <div className="lux-create-footer__actions">
            {wizardMode && !isFirstWizardStep && (
              <button
                type="button"
                className="lux-create-footer__btn lux-create-footer__btn--ghost"
                onClick={onWizardBack}
                disabled={isProcessing}
              >
                <i className="fe fe-arrow-left" aria-hidden="true" /> Back
              </button>
            )}

            <button
              type="button"
              className="lux-create-footer__btn lux-create-footer__btn--ghost"
              onClick={() => initializeRequest(this.state.createAnotherEnabled)}
              disabled={isProcessing}
            >
              Reset
            </button>

            {wizardMode && !isLastWizardStep ? (
              <button
                type="button"
                className="lux-create-footer__btn lux-create-footer__btn--primary"
                onClick={onWizardNext}
                disabled={isProcessing || canWizardNext === false}
              >
                Continue <i className="fe fe-arrow-right" aria-hidden="true" />
              </button>
            ) : (
              <LoadingButton
                isLoading={isProcessing}
                loadingText={
                  editMode ? "Updating…" : duplicateMode ? "Duplicating…" : "Creating…"
                }
                variant="primary"
                size="sm"
                className="lux-create-footer__submit"
                onClick={() =>
                  handleSubmit(this.state.createAnotherEnabled, this.state.keepDataEnabled)
                }
              >
                {createButtonLabel ||
                  (editMode ? "Save changes" : duplicateMode ? "Duplicate" : "Create employee")}
              </LoadingButton>
            )}
          </div>
        </div>
      </footer>
    );
  }
}

export default LuxCreateFooter;
