import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import dateUtils from "_helpers/date.utils";
import classNames from "classnames/bind";
import LuxBackNav from "views/common/fragments/LuxBackNav";
import SelectInput from "views/common/fragments/formfields/SelectInput";
import ItemCommentsSection from "views/project/components/fragments/ItemCommentsSection";
import { bidRequestsActions } from "_actions";
import { connect } from "react-redux";
import { store } from "_helpers";
import CreateBidRequestsSidebarSection from "./modal/CreateBidRequestsSidebarSection";
import {
  getBidStatusMeta,
  getBidStatusSelectValue,
  getBidTypeLabel,
  getBidTypeTone,
} from "./bidRequestList.utils";

const STATUS_OPTIONS = [
  { value: "NEW", label: "New" },
  { value: "ASSIGNED", label: "Assinged" },
  { value: "INPROGRESS", label: "In Progress" },
  { value: "WON", label: "Won" },
  { value: "LOST", label: "Lost" },
  { value: "CANCELLED", label: "Canceled" },
  { value: "REJECTED", label: "Rejected" },
  { value: "CLOSED", label: "Closed" },
];

class BidRequestsDetailsGeneral extends Component {
  handleUpdateStatus = (bidRequestId, status) => {
    store.dispatch(this.props.updateBidRequestsStatus(bidRequestId, status));
  };

  renderFact = (icon, label, value) => (
    <div className="lux-bid-detail__fact">
      <span className="lux-bid-detail__fact-icon" aria-hidden="true">
        <i className={`fe ${icon}`} />
      </span>
      <div>
        <span className="lux-bid-detail__fact-label">{label}</span>
        <strong className="lux-bid-detail__fact-value">{value || "—"}</strong>
      </div>
    </div>
  );

  renderMetaCard = (title, children) => (
    <section className="lux-bid-detail__card">
      <header className="lux-bid-detail__card-head">
        <h2>{title}</h2>
      </header>
      <div className="lux-bid-detail__card-body">{children}</div>
    </section>
  );

  render() {
    const { item, compactView } = this.props;
    if (!item) return null;

    const statusMeta = getBidStatusMeta(item.status);
    const typeTone = getBidTypeTone(item.type);
    const ownerName = item.ownerDetails && item.ownerDetails.name;
    const teamName = item.ownerUserTeamDetails && item.ownerUserTeamDetails.name;

    return (
      <div
        className={classNames("lux-bid-detail", {
          "lux-bid-detail--compact": compactView,
          [`is-status-${statusMeta.tone}`]: true,
        })}
      >
        {!compactView && (
          <LuxBackNav
            component={NavLink}
            to="/sales/bidrequests"
            destinationLabel="Bid requests"
            currentLabel={item.itemIdUserTeamPrefix}
            navClassName="lux-bid-detail__breadcrumb"
            aria-label="Breadcrumb"
          />
        )}

        <header className="lux-bid-detail__hero">
          <div className="lux-bid-detail__hero-glow" aria-hidden="true" />
          <div className="lux-bid-detail__hero-inner">
            <div className="lux-bid-detail__hero-main">
              <div className="lux-bid-detail__hero-badges">
                <span className="lux-bid-detail__ref-pill">{item.itemIdUserTeamPrefix}</span>
                <span className={classNames("lux-bid-detail__status-pill", `is-${statusMeta.tone}`)}>
                  {statusMeta.label}
                </span>
                {item.type && (
                  <span className={classNames("lux-bid-detail__type-pill", `is-${typeTone}`)}>
                    {getBidTypeLabel(item.type)}
                  </span>
                )}
                {item.archived && (
                  <span className="lux-bid-detail__flag-pill is-muted">Archived</span>
                )}
                {item.deleted && (
                  <span className="lux-bid-detail__flag-pill is-danger">Deleted</span>
                )}
              </div>
              <h1 className="lux-bid-detail__title">{item.studyName}</h1>
              <p className="lux-bid-detail__subtitle">
                {teamName && (
                  <>
                    <i className="fe fe-layers" aria-hidden="true" />
                    {teamName}
                    <span className="lux-bid-detail__dot">·</span>
                  </>
                )}
                {ownerName && (
                  <>
                    <i className="fe fe-user" aria-hidden="true" />
                    {ownerName}
                  </>
                )}
              </p>
            </div>

            <div className="lux-bid-detail__hero-aside">
              <label className="lux-bid-detail__status-label">Pipeline status</label>
              <div className={classNames("lux-bid-detail__status-select", `is-${statusMeta.tone}`)}>
                <SelectInput
                  options={STATUS_OPTIONS}
                  value={getBidStatusSelectValue(item.status)}
                  allowLevelDown={this.props.permission.allowStatusLevelDown}
                  changeableStatus={this.props.permission.changeableStatus}
                  isReadOnly={!this.props.permission.allowStatusChange || this.props.readOnly}
                  itemId={item.id}
                  onChange={this.handleUpdateStatus}
                  className="lux-bid-detail__status-input"
                />
              </div>
            </div>
          </div>

          {!compactView && (
            <div className="lux-bid-detail__facts">
              {this.renderFact("fe-calendar", "Created", dateUtils.convertDateTimeFormat(item.createdDate))}
              {this.renderFact("fe-tag", "Sales force ID", item.salesForceId)}
              {this.renderFact("fe-clock", "Field time", item.fieldTime)}
              {this.renderFact("fe-send", "Launch", item.launchTime)}
            </div>
          )}
        </header>

        <div className="lux-bid-detail__layout">
          <main className="lux-bid-detail__main">
            <section className="lux-bid-detail__section">
              <header className="lux-bid-detail__section-head">
                <div>
                  <span className="lux-bid-detail__section-eyebrow">Bid specification</span>
                  <h2 className="lux-bid-detail__section-title">Study details</h2>
                </div>
              </header>
              <div className="lux-bid-detail__form-shell">
                <CreateBidRequestsSidebarSection
                  permission={this.props.permission}
                  editMode={true}
                  readOnly={true}
                  duplicateMode={false}
                  detailView={true}
                  selectedBidRequestsInfo={item}
                />
              </div>
            </section>
          </main>

          {!compactView && (
            <aside className="lux-bid-detail__rail" aria-label="Bid metadata">
              {this.renderMetaCard(
                "Ownership",
                <>
                  {this.renderFact("fe-user", "Bid owner", ownerName)}
                  {this.renderFact("fe-layers", "Team", teamName)}
                </>
              )}

              {this.renderMetaCard(
                "Timeline",
                <>
                  {this.renderFact(
                    "fe-calendar",
                    "Created",
                    dateUtils.convertDateTimeFormat(item.createdDate)
                  )}
                  {item.lastModifiedDate &&
                    this.renderFact(
                      "fe-edit",
                      "Last updated",
                      dateUtils.convertDateTimeFormat(item.lastModifiedDate)
                    )}
                  {item.createdByDetails &&
                    this.renderFact("fe-user-check", "Created by", item.createdByDetails.name)}
                  {item.updatedByDetails &&
                    this.renderFact("fe-user-check", "Updated by", item.updatedByDetails.name)}
                </>
              )}

              {(item.kindOfStudies || item.countries) && (
                <section className="lux-bid-detail__card">
                  <header className="lux-bid-detail__card-head">
                    <h2>Scope</h2>
                  </header>
                  <div className="lux-bid-detail__card-body">
                    {item.kindOfStudies && item.kindOfStudies.length > 0 && (
                      <div className="lux-bid-detail__tag-group">
                        <span className="lux-bid-detail__tag-label">Kind of study</span>
                        <div className="lux-bid-detail__tags">
                          {item.kindOfStudies.map((k) => (
                            <span key={k} className="lux-bid-detail__tag">
                              {k}
                            </span>
                          ))}
                        </div>
                      </div>
                    )}
                    {item.countries && item.countries.length > 0 && (
                      <div className="lux-bid-detail__tag-group">
                        <span className="lux-bid-detail__tag-label">Countries</span>
                        <div className="lux-bid-detail__tags">
                          {item.countries.map((c) => (
                            <span key={c} className="lux-bid-detail__tag is-geo">
                              {c}
                            </span>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </section>
              )}
            </aside>
          )}
        </div>

        {!compactView && (
          <section className="lux-bid-detail__comments-panel">
            <header className="lux-bid-detail__section-head">
              <div>
                <span className="lux-bid-detail__section-eyebrow">Collaboration</span>
                <h2 className="lux-bid-detail__section-title">Comments</h2>
              </div>
            </header>
            <div className="lux-bid-detail__comments-body">
              <ItemCommentsSection itemId={item.id} subType={"BID_REQUEST"} />
            </div>
          </section>
        )}
      </div>
    );
  }
}

const mapDispatchToProps = () => ({
  updateBidRequestsStatus: bidRequestsActions.updateBidRequestsStatus,
});

export default connect(null, mapDispatchToProps)(BidRequestsDetailsGeneral);
