import dateUtils from "_helpers/date.utils";
import { toDonutChart } from "../dashboard/employeeDashboard.utils";

const WEEK_BASELINE_MINS = 40 * 60;
export const TIMESHEET_TYPE_KEYS = ["project", "nonProject"];

export const TIMESHEET_STATUS_META = {
  DRAFT: { label: "Draft", tone: "slate", icon: "fe-edit-3", hint: "Not submitted yet" },
  SUBMITTED: { label: "Submitted", tone: "blue", icon: "fe-send", hint: "Sent for review" },
  PENDING: { label: "Pending", tone: "amber", icon: "fe-clock", hint: "Awaiting approval" },
  APPROVED: { label: "Approved", tone: "green", icon: "fe-check-circle", hint: "Approved for payroll" },
  REJECTED: { label: "Rejected", tone: "rose", icon: "fe-x-circle", hint: "Needs correction" },
  REOPENED: { label: "Reopened", tone: "violet", icon: "fe-rotate-ccw", hint: "Open for edits" },
  LOCKED: { label: "Locked", tone: "slate", icon: "fe-lock", hint: "No further changes" },
  PAYROLL_PROCESSED: {
    label: "Payroll processed",
    tone: "teal",
    icon: "fe-dollar-sign",
    hint: "Included in payroll",
  },
  MIXED: { label: "Mixed", tone: "amber", icon: "fe-layers", hint: "Entries have different statuses" },
  NOT_STARTED: { label: "Not started", tone: "slate", icon: "fe-minus-circle", hint: "No hours logged" },
};

const STATUS_PRIORITY = [
  "REJECTED",
  "DRAFT",
  "REOPENED",
  "PENDING",
  "SUBMITTED",
  "APPROVED",
  "LOCKED",
  "PAYROLL_PROCESSED",
];

export function readAttributeValue(attr) {
  if (attr == null || attr === "") return null;
  if (typeof attr === "object" && attr.value != null && attr.value !== "") {
    return String(attr.value).trim();
  }
  if (typeof attr === "string" || typeof attr === "number") {
    return String(attr).trim();
  }
  return null;
}

export function normalizeTimesheetStatus(rawStatus) {
  if (!rawStatus) return null;
  const normalized = String(rawStatus)
    .trim()
    .toUpperCase()
    .replace(/[\s-]+/g, "_");
  if (normalized === "PAYROLL_PROCESSED" || normalized === "PAYROLLPROCESSED") {
    return "PAYROLL_PROCESSED";
  }
  if (TIMESHEET_STATUS_META[normalized]) return normalized;
  return normalized;
}

export function getTimesheetStatusMeta(statusKey) {
  const key = normalizeTimesheetStatus(statusKey) || "NOT_STARTED";
  return TIMESHEET_STATUS_META[key] || {
    label: key.replace(/_/g, " ").toLowerCase().replace(/^\w/, (c) => c.toUpperCase()),
    tone: "slate",
    icon: "fe-info",
    hint: "Timesheet status",
  };
}

/**
 * Entry status from API when present; otherwise infer for display only.
 * Logged time without a backend status is treated as approved (not draft).
 */
export function deriveTimesheetEntryStatus(entry, taskIsNew) {
  const explicit = normalizeTimesheetStatus(readAttributeValue(entry && entry.status));
  if (explicit) return explicit;

  const mins = parseInt((entry && entry.timesheetTimeMins) || 0, 10);
  if (mins <= 0) return null;

  if (entry.isNew === true || entry.isUpdated === true || taskIsNew === true) {
    return "DRAFT";
  }

  return "APPROVED";
}

function resolveWeekStatus(rootStatus, statusCounts, options = {}) {
  if (rootStatus) return rootStatus;

  const keys = Object.keys(statusCounts).filter((key) => statusCounts[key] > 0);
  if (!keys.length) {
    return options.defaultWhenNoStatus || "NOT_STARTED";
  }
  if (keys.length === 1) return keys[0];

  for (let i = 0; i < STATUS_PRIORITY.length; i += 1) {
    if (statusCounts[STATUS_PRIORITY[i]] > 0) {
      return "MIXED";
    }
  }
  return "MIXED";
}

function forEachTimesheetEntry(timeSheetData, weekDates, visitor) {
  if (!timeSheetData) return;

  TIMESHEET_TYPE_KEYS.forEach((timesheetType) => {
    const taskGroupItems = timeSheetData[timesheetType];
    if (!taskGroupItems || typeof taskGroupItems !== "object") return;

    Object.keys(taskGroupItems).forEach((taskGroupId) => {
      const timeEntryTaskSection = taskGroupItems[taskGroupId];
      const timeSheetTaskList = timeEntryTaskSection && timeEntryTaskSection.tasks;
      if (!timeSheetTaskList) return;

      timeSheetTaskList.forEach((timeSheetTaskItem) => {
        const timeEntry = timeSheetTaskItem && timeSheetTaskItem.timeEntry;
        if (!timeEntry) return;

        Object.keys(timeEntry).forEach((dateString) => {
          if (weekDates.length && !weekDates.includes(dateString)) return;
          visitor({
            timesheetType,
            taskGroupId,
            timeSheetTaskItem,
            dateString,
            entry: timeEntry[dateString],
          });
        });
      });
    });
  });
}

export function convertMinsToDisplay(timeInMins) {
  if (timeInMins > 0) {
    return `${Math.floor(timeInMins / 60)}h ${timeInMins % 60}m`;
  }
  return "0";
}

export function computeTimesheetSummary(timeSheetData, applicableDates) {
  let billableMins = 0;
  let nonProjectMins = 0;
  let leaveOrHolidayMins = 0;

  const weekDates =
    applicableDates && applicableDates.currentWeekDates ? applicableDates.currentWeekDates : [];

  const dailyMap = {};
  const statusCounts = {};
  const rootStatus = normalizeTimesheetStatus(readAttributeValue(timeSheetData && timeSheetData.status));
  const rootShow = readAttributeValue(timeSheetData && timeSheetData.show);

  weekDates.forEach((dateString) => {
    dailyMap[dateString] = {
      billable: 0,
      nonProject: 0,
      leave: 0,
      total: 0,
      statusCounts: {},
    };
  });

  forEachTimesheetEntry(timeSheetData, weekDates, ({ timesheetType, timeSheetTaskItem, dateString, entry }) => {
    const time = parseInt((entry && entry.timesheetTimeMins) || 0, 10);
    const entryStatus = deriveTimesheetEntryStatus(entry, timeSheetTaskItem.isNew === true);

    if (entryStatus && time > 0) {
      statusCounts[entryStatus] = (statusCounts[entryStatus] || 0) + 1;
      dailyMap[dateString].statusCounts[entryStatus] =
        (dailyMap[dateString].statusCounts[entryStatus] || 0) + 1;
    }

    if (timesheetType === "project") {
      billableMins += time;
      dailyMap[dateString].billable += time;
    } else if (timesheetType === "nonProject") {
      if (
        timeSheetTaskItem.taskActCategory &&
        (timeSheetTaskItem.taskActCategory.toLowerCase() === "leave" ||
          timeSheetTaskItem.taskActCategory.toLowerCase() === "holiday")
      ) {
        leaveOrHolidayMins += time;
        dailyMap[dateString].leave += time;
      } else {
        nonProjectMins += time;
        dailyMap[dateString].nonProject += time;
      }
    }
    dailyMap[dateString].total += time;
  });

  const totalMins = billableMins + nonProjectMins;
  const weekStatus = resolveWeekStatus(rootStatus, statusCounts, {
    defaultWhenNoStatus: !rootStatus && totalMins > 0 ? "APPROVED" : "NOT_STARTED",
  });
  const weekStatusMeta = getTimesheetStatusMeta(weekStatus);
  const statusBreakdown = Object.keys(statusCounts)
    .sort((a, b) => (statusCounts[b] || 0) - (statusCounts[a] || 0))
    .map((statusKey) => ({
      statusKey,
      count: statusCounts[statusKey],
      ...getTimesheetStatusMeta(statusKey),
    }));
  const dailyStatuses = weekDates.map((dateString) => {
    const dayCounts = dailyMap[dateString].statusCounts;
    const dayKeys = Object.keys(dayCounts);
    const dayHasTime = dailyMap[dateString].total > 0;
    const dayStatus = resolveWeekStatus(null, dayCounts, {
      defaultWhenNoStatus: dayHasTime ? "APPROVED" : "NOT_STARTED",
    });
    const resolvedKey = dayKeys.length || dayHasTime ? dayStatus : "NOT_STARTED";
    return {
      dateString,
      statusKey: resolvedKey,
      ...getTimesheetStatusMeta(resolvedKey),
    };
  });

  const daysNeedingAttention = buildDaysNeedingAttention(dailyMap, weekDates);

  const utilization = (((totalMins - leaveOrHolidayMins) / 60) / 40) * 100;
  const billableUtilization = ((billableMins / 60) / 40) * 100;
  const nonUtilization = ((nonProjectMins / 60) / 40) * 100;
  const workMins = Math.max(0, totalMins - leaveOrHolidayMins);
  const remainingMins = Math.max(0, WEEK_BASELINE_MINS - workMins);

  return {
    billableMins,
    nonProjectMins,
    leaveOrHolidayMins,
    totalMins,
    workMins,
    remainingMins,
    utilizationMins: utilization,
    billableUtilizationMins: billableUtilization,
    nonUtilizationMins: nonUtilization,
    billableString: convertMinsToDisplay(billableMins),
    nonProjectString: convertMinsToDisplay(nonProjectMins),
    leaveOrHolidayString: convertMinsToDisplay(leaveOrHolidayMins),
    totalString: convertMinsToDisplay(totalMins),
    utilizationString: `${utilization.toFixed(2)} %`,
    billableUtilizationString: `${billableUtilization.toFixed(2)} %`,
    nonUtilizationString: `${nonUtilization.toFixed(2)} %`,
    dailyMap,
    weekDates,
    weekStatus,
    weekStatusMeta,
    rootShow,
    statusBreakdown,
    dailyStatuses,
    statusCounts,
    daysNeedingAttention,
  };
}

export const DAILY_TARGET_HOURS = 8;
export const DAILY_TARGET_MINS = DAILY_TARGET_HOURS * 60;

export function buildDaysNeedingAttention(dailyMap, weekDates) {
  if (!weekDates || !weekDates.length) return [];

  return weekDates
    .map((dateString) => {
      const totalMins = (dailyMap[dateString] && dailyMap[dateString].total) || 0;
      const momentDate = dateUtils.convertDateStringToMoment(dateString);
      const dayLabel = momentDate && momentDate.isValid() ? momentDate.format("ddd D") : dateString.slice(5);
      const hoursShort = (Math.round((totalMins / 60) * 10) / 10).toFixed(1);

      let level = "target";
      let reason = "On target (8h)";
      if (totalMins <= 0) {
        level = "empty";
        reason = "No hours logged";
      } else if (totalMins > DAILY_TARGET_MINS) {
        level = "over";
        reason = `${hoursShort}h logged — over 8h target`;
      } else if (totalMins < DAILY_TARGET_MINS) {
        level = "under";
        const gapMins = DAILY_TARGET_MINS - totalMins;
        reason = `${hoursShort}h logged — ${convertMinsToDisplay(gapMins)} below 8h`;
      }

      return {
        dateString,
        dayLabel,
        totalMins,
        totalDisplay: convertMinsToDisplay(totalMins),
        level,
        reason,
      };
    })
    .filter((day) => day.level !== "target");
}

export function buildTimesheetStatusChart(summary) {
  const { statusBreakdown } = summary;
  if (!statusBreakdown || !statusBreakdown.length) return null;

  const labels = statusBreakdown.map((row) => row.label);
  const series = statusBreakdown.map((row) => row.count);
  const colors = {
    DRAFT: "#64748b",
    SUBMITTED: "#2563eb",
    PENDING: "#d97706",
    APPROVED: "#059669",
    REJECTED: "#e11d48",
    REOPENED: "#7c3aed",
    LOCKED: "#475569",
    PAYROLL_PROCESSED: "#0d9488",
    MIXED: "#d97706",
    NOT_STARTED: "#94a3b8",
  };

  const chart = toDonutChart(
    labels,
    series,
    statusBreakdown.map((row) => colors[row.statusKey] || "#64748b")
  );
  chart.options.plotOptions = {
    pie: {
      donut: {
        size: "68%",
        labels: {
          show: true,
          total: {
            show: true,
            label: "Entries",
            fontSize: "11px",
            fontWeight: 700,
            color: "#64748b",
            formatter: () => String(series.reduce((a, b) => a + b, 0)),
          },
        },
      },
    },
  };
  chart.options.legend = { position: "bottom", fontSize: "11px", fontWeight: 600 };
  return chart;
}

export function buildTimesheetDistributionChart(summary) {
  const { billableMins, nonProjectMins, leaveOrHolidayMins } = summary;
  const total = billableMins + nonProjectMins + leaveOrHolidayMins;
  if (total <= 0) return null;

  const chart = toDonutChart(
    ["Billable", "Non-billable", "Leave / holiday"],
    [billableMins, nonProjectMins, leaveOrHolidayMins],
    ["#059669", "#5b5ff4", "#d97706"]
  );

  chart.options.plotOptions = {
    pie: {
      donut: {
        size: "72%",
        labels: {
          show: true,
          name: { show: true, fontSize: "11px", fontWeight: 600, color: "#64748b" },
          value: {
            show: true,
            fontSize: "18px",
            fontWeight: 800,
            color: "#0f172a",
            formatter: (val) => `${Math.round(parseFloat(val) / 60 * 10) / 10}h`,
          },
          total: {
            show: true,
            label: "Logged",
            fontSize: "11px",
            fontWeight: 700,
            color: "#64748b",
            formatter: () => convertMinsToDisplay(total),
          },
        },
      },
    },
  };
  chart.options.legend = { position: "bottom", fontSize: "11px", fontWeight: 600 };

  return chart;
}

export function buildTimesheetUtilizationChart(summary) {
  const categories = ["Billable", "Non-billable", "Overall"];
  const values = [
    Math.min(100, Math.round(summary.billableUtilizationMins * 100) / 100),
    Math.min(100, Math.round(summary.nonUtilizationMins * 100) / 100),
    Math.min(100, Math.round(summary.utilizationMins * 100) / 100),
  ];

  return {
    series: [{ name: "Utilization %", data: values }],
    options: {
      chart: { type: "bar", toolbar: { show: false }, sparkline: { enabled: false } },
      plotOptions: {
        bar: {
          horizontal: true,
          borderRadius: 6,
          barHeight: "62%",
          distributed: true,
        },
      },
      colors: ["#059669", "#5b5ff4", "#7c3aed"],
      dataLabels: {
        enabled: true,
        formatter: (val) => `${val.toFixed(1)}%`,
        style: { fontSize: "11px", fontWeight: 800, colors: ["#fff"] },
        offsetX: -6,
      },
      xaxis: {
        categories,
        max: 100,
        labels: { style: { fontSize: "11px", fontWeight: 600, colors: "#64748b" } },
      },
      yaxis: {
        labels: { style: { fontSize: "11px", fontWeight: 700, colors: "#334155" } },
      },
      grid: { borderColor: "rgba(226,232,240,0.85)", strokeDashArray: 4, padding: { right: 8 } },
      legend: { show: false },
      tooltip: {
        y: { formatter: (val) => `${val.toFixed(2)}% of 40h week` },
      },
      annotations: {
        xaxis: [
          {
            x: 100,
            borderColor: "rgba(239, 68, 68, 0.35)",
            strokeDashArray: 4,
            label: {
              text: "100%",
              style: { fontSize: "10px", fontWeight: 700, color: "#ef4444", background: "transparent" },
            },
          },
        ],
      },
    },
  };
}

/** Daily hours vs 8h target — fills utilization panel companion slot */
export function buildTimesheetDailyTargetChart(summary) {
  const { weekDates, dailyMap } = summary;
  if (!weekDates || !weekDates.length) return null;

  const categories = weekDates.map((dateString) => {
    const m = dateUtils.convertDateStringToMoment(dateString);
    return m && m.isValid() ? m.format("ddd") : dateString.slice(5);
  });

  const hours = weekDates.map((d) => Math.round(((dailyMap[d].total || 0) / 60) * 10) / 10);
  const colors = weekDates.map((d) => {
    const total = dailyMap[d].total || 0;
    if (total <= 0) return "#94a3b8";
    if (total > DAILY_TARGET_MINS) return "#dc2626";
    if (total < DAILY_TARGET_MINS) return "#d97706";
    return "#059669";
  });

  return {
    series: [{ name: "Hours", data: hours }],
    options: {
      chart: { type: "bar", toolbar: { show: false } },
      plotOptions: {
        bar: {
          borderRadius: 6,
          columnWidth: "58%",
          distributed: true,
          dataLabels: { position: "top" },
        },
      },
      colors,
      dataLabels: {
        enabled: true,
        formatter: (val) => (val > 0 ? `${val}h` : "—"),
        offsetY: -18,
        style: { fontSize: "10px", fontWeight: 800, colors: ["#334155"] },
      },
      xaxis: {
        categories,
        labels: { style: { fontSize: "10px", fontWeight: 700, colors: "#64748b" } },
      },
      yaxis: {
        max: Math.max(DAILY_TARGET_HOURS + 2, ...hours, 8),
        title: { text: "Hours", style: { fontSize: "10px", fontWeight: 700, color: "#94a3b8" } },
        labels: { style: { fontSize: "10px", colors: "#94a3b8" } },
      },
      grid: { borderColor: "rgba(226,232,240,0.85)", strokeDashArray: 4 },
      legend: { show: false },
      tooltip: { y: { formatter: (val) => `${val}h (8h target)` } },
      annotations: {
        yaxis: [
          {
            y: DAILY_TARGET_HOURS,
            borderColor: "rgba(5, 150, 105, 0.55)",
            strokeDashArray: 5,
            label: {
              text: "8h",
              style: { fontSize: "10px", fontWeight: 800, color: "#059669", background: "rgba(255,255,255,0.9)" },
            },
          },
        ],
      },
    },
  };
}

/** Week compliance donut — days at / under / over / empty vs 8h */
export function buildTimesheetWeekComplianceChart(summary) {
  const { weekDates, dailyMap } = summary;
  if (!weekDates || !weekDates.length) return null;

  let onTarget = 0;
  let under = 0;
  let over = 0;
  let empty = 0;

  weekDates.forEach((dateString) => {
    const total = (dailyMap[dateString] && dailyMap[dateString].total) || 0;
    if (total <= 0) empty += 1;
    else if (total > DAILY_TARGET_MINS) over += 1;
    else if (total < DAILY_TARGET_MINS) under += 1;
    else onTarget += 1;
  });

  const series = [onTarget, under, over, empty];
  if (series.every((v) => v === 0)) return null;

  const chart = toDonutChart(
    ["On target (8h)", "Below 8h", "Over 8h", "No data"],
    series,
    ["#059669", "#d97706", "#dc2626", "#94a3b8"]
  );
  chart.options.plotOptions = {
    pie: {
      donut: {
        size: "72%",
        labels: {
          show: true,
          total: {
            show: true,
            label: "Days",
            fontSize: "10px",
            fontWeight: 700,
            color: "#64748b",
            formatter: () => String(weekDates.length),
          },
        },
      },
    },
  };
  chart.options.legend = { position: "bottom", fontSize: "10px", fontWeight: 600 };
  return chart;
}

export function buildTimesheetDailyChart(summary) {
  const { weekDates, dailyMap } = summary;
  if (!weekDates || !weekDates.length) return null;

  const categories = weekDates.map((dateString) => {
    const m = dateUtils.convertDateStringToMoment(dateString);
    return m && m.isValid() ? m.format("ddd") : dateString.slice(5);
  });

  const billable = weekDates.map((d) => Math.round((dailyMap[d].billable / 60) * 10) / 10);
  const nonProject = weekDates.map((d) => Math.round((dailyMap[d].nonProject / 60) * 10) / 10);
  const leave = weekDates.map((d) => Math.round((dailyMap[d].leave / 60) * 10) / 10);

  const hasData = billable.some(Boolean) || nonProject.some(Boolean) || leave.some(Boolean);
  if (!hasData) return null;

  return {
    series: [
      { name: "Billable", data: billable },
      { name: "Non-billable", data: nonProject },
      { name: "Leave / holiday", data: leave },
    ],
    options: {
      chart: { type: "bar", toolbar: { show: false }, stacked: true },
      plotOptions: { bar: { borderRadius: 4, columnWidth: "52%" } },
      colors: ["#059669", "#5b5ff4", "#d97706"],
      dataLabels: { enabled: false },
      xaxis: {
        categories,
        labels: { style: { fontSize: "11px", fontWeight: 700, colors: "#64748b" } },
      },
      yaxis: {
        title: { text: "Hours", style: { fontSize: "11px", fontWeight: 700, color: "#94a3b8" } },
        labels: { style: { fontSize: "10px", colors: "#94a3b8" } },
      },
      legend: { position: "bottom", fontSize: "11px", fontWeight: 600 },
      grid: { borderColor: "rgba(226,232,240,0.85)", strokeDashArray: 4 },
      tooltip: { y: { formatter: (val) => `${val}h` } },
    },
  };
}

export function buildTimesheetContextLine(summary) {
  const { totalString, billableString, utilizationString, remainingMins, weekStatusMeta, rootShow } = summary;
  const parts = [weekStatusMeta.label];
  if (rootShow) {
    parts.push(rootShow);
  }
  parts.push(`${totalString} logged`, `${billableString} billable`, `${utilizationString} utilization`);
  if (remainingMins > 0) {
    parts.push(`${convertMinsToDisplay(remainingMins)} to 40h target`);
  }
  return parts.join(" · ");
}

