import React, { Component } from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import EmployeeImage from "views/common/fragments/EmployeeImage";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import ProjectDetailsTabShell from "./ProjectDetailsTabShell";
import {
  MEMBER_ROLES,
  filterMembers,
  getProjectAccessSummary,
  getProjectMembers,
} from "./projectDetailsTab.utils";

const ROLE_TONES = {
  [MEMBER_ROLES.CREATOR]: "violet",
  [MEMBER_ROLES.UPDATER]: "sky",
  [MEMBER_ROLES.ASSIGNEE]: "mint",
};

function getPrimaryRoleTone(roles) {
  const role = roles && roles.length ? roles[0] : MEMBER_ROLES.ASSIGNEE;
  return ROLE_TONES[role] || "slate";
}

class ProjectDetailsMembers extends Component {
  constructor() {
    super();
    this.state = { query: "" };
  }

  clearSearch = () => {
    this.setState({ query: "" });
  };

  renderAccessPanel = (projectInfo, teams, skills) => {
    const ownerTeam =
      (projectInfo.ownerUserTeamDetails && projectInfo.ownerUserTeamDetails.name) ||
      projectInfo.teamName;
    const teamDetails = projectInfo.restrictedByUserTeamDetails || [];
    const hasAccessContent = ownerTeam || teamDetails.length > 0 || skills.length > 0;

    if (!hasAccessContent) {
      return (
        <aside className="lux-pd-team__access lux-pd-team__access--empty">
          <div className="lux-pd-team__access-empty">
            <span className="lux-pd-team__access-empty-icon" aria-hidden="true">
              <i className="fe fe-shield" />
            </span>
            <strong>Open access</strong>
            <span>No team or skill restrictions are configured for this project.</span>
          </div>
        </aside>
      );
    }

    return (
      <aside className="lux-pd-team__access" aria-label="Access rules">
        <header className="lux-pd-team__access-head">
          <span className="lux-pd-team__access-head-icon" aria-hidden="true">
            <i className="fe fe-shield" />
          </span>
          <div>
            <span className="lux-pd-team__access-eyebrow">Access control</span>
            <strong>Who can work here</strong>
          </div>
        </header>

        <div className="lux-pd-team__access-stack">
          {ownerTeam && (
            <article className="lux-pd-team__access-card is-owner">
              <header>
                <i className="fe fe-home" aria-hidden="true" />
                <div>
                  <span>Owning team</span>
                  <strong>{ownerTeam}</strong>
                </div>
              </header>
            </article>
          )}

          {teamDetails.length > 0 && (
            <article className="lux-pd-team__access-card is-teams">
              <header>
                <i className="fe fe-users" aria-hidden="true" />
                <div>
                  <span>Restricted teams</span>
                  <strong>{teamDetails.length} group{teamDetails.length === 1 ? "" : "s"}</strong>
                </div>
              </header>
              <ul className="lux-pd-team__access-list">
                {teamDetails.map((team) => (
                  <li key={team.id || team.name}>
                    <i className="fe fe-check-circle" aria-hidden="true" />
                    {team.name}
                  </li>
                ))}
              </ul>
            </article>
          )}

          {skills.length > 0 && (
            <article className="lux-pd-team__access-card is-skills">
              <header>
                <i className="fe fe-award" aria-hidden="true" />
                <div>
                  <span>Skill gates</span>
                  <strong>{skills.length} skill{skills.length === 1 ? "" : "s"}</strong>
                </div>
              </header>
              <div className="lux-pd-team__access-chips">
                {skills.map((skill) => (
                  <span key={skill} className="lux-pd-team__access-chip">
                    {skill}
                  </span>
                ))}
              </div>
            </article>
          )}
        </div>
      </aside>
    );
  };

  renderMemberCard = (member) => {
    const tone = getPrimaryRoleTone(member.roles);

    return (
      <article key={member.id} className={classNames("lux-pd-team-card", `is-${tone}`)}>
        <span className="lux-pd-team-card__accent" aria-hidden="true" />
        <div className="lux-pd-team-card__glow" aria-hidden="true" />

        <div className="lux-pd-team-card__hero">
          <Link
            to={`/hrms/profile/${member.id}`}
            className="lux-pd-team-card__avatar-link"
            title={`Open ${member.name}'s profile`}
          >
            <span className="lux-pd-team-card__avatar-ring" aria-hidden="true" />
            <EmployeeImage employee={member} classes="lux-pd-team-card__avatar" />
          </Link>

          <div className="lux-pd-team-card__identity">
            <Link to={`/hrms/profile/${member.id}`} className="lux-pd-team-card__name">
              {member.name || "Unknown"}
            </Link>
            {member.designation && (
              <span className="lux-pd-team-card__role">{member.designation}</span>
            )}
          </div>
        </div>

        <div className="lux-pd-team-card__meta">
          {member.email && (
            <a href={`mailto:${member.email}`} className="lux-pd-team-card__email">
              <i className="fe fe-mail" aria-hidden="true" />
              <span>{member.email}</span>
            </a>
          )}
          <div className="lux-pd-team-card__tags">
            {(member.roles || []).map((role) => (
              <span
                key={role}
                className={classNames(
                  "lux-pd-team-card__tag",
                  ROLE_TONES[role] && `is-${ROLE_TONES[role]}`
                )}
              >
                {role}
              </span>
            ))}
          </div>
        </div>
      </article>
    );
  };

  render() {
    const { projectInfo } = this.props;
    if (!projectInfo) return null;

    const allMembers = getProjectMembers(projectInfo);
    const members = filterMembers(allMembers, this.state.query);
    const { teams, skills } = getProjectAccessSummary(projectInfo);
    const query = (this.state.query || "").trim();

    const stats = [
      {
        key: "people",
        label: "People",
        value: allMembers.length,
        hint: "Named on project",
        tone: "violet",
      },
      {
        key: "teams",
        label: "Teams",
        value: teams.length,
        hint: "Access groups",
        tone: "sky",
      },
      {
        key: "skills",
        label: "Skills",
        value: skills.length,
        hint: "Skill gates",
        tone: "mint",
      },
    ];

    return (
      <ProjectDetailsTabShell
        icon="fe fe-users"
        eyebrow="Team"
        title="Members & access"
        subtitle="People linked to this project from ownership, assignment, and access rules."
        stats={stats}
      >
        <div className="lux-pd-team">
          <div className="lux-pd-team__layout">
            {this.renderAccessPanel(projectInfo, teams, skills)}

            <section className="lux-pd-team__roster" aria-label="Team roster">
              <div className="lux-pd-team__toolbar">
                <label className="lux-pd-team__search">
                  <i className="fe fe-search" aria-hidden="true" />
                  <input
                    type="search"
                    placeholder="Search by name, email, or role…"
                    value={this.state.query}
                    onChange={(e) => this.setState({ query: e.target.value })}
                    aria-label="Search team members"
                  />
                  {query && (
                    <button
                      type="button"
                      className="lux-pd-team__search-clear"
                      onClick={this.clearSearch}
                      aria-label="Clear search"
                    >
                      <i className="fe fe-x" aria-hidden="true" />
                    </button>
                  )}
                </label>
                <span className="lux-pd-team__count">
                  <strong>{members.length}</strong>
                  <span>{members.length === 1 ? "member" : "members"}</span>
                </span>
              </div>

              {members.length > 0 ? (
                <div className={classNames("lux-pd-team__grid", { "is-filtered": query })}>
                  {members.map(this.renderMemberCard)}
                </div>
              ) : allMembers.length > 0 ? (
                <div className="lux-pd-team__no-match">
                  <span className="lux-pd-team__no-match-icon" aria-hidden="true">
                    <i className="fe fe-search" />
                  </span>
                  <strong>No members match your search</strong>
                  <span>Try a different name, email, or role keyword.</span>
                  <button type="button" className="lux-pd-team__no-match-btn" onClick={this.clearSearch}>
                    Clear search
                  </button>
                </div>
              ) : (
                <LuxRegisterEmptyState
                  variant="employees"
                  eyebrow="No people listed"
                  title="No team members on file"
                  description="This project has no named assignees yet. Add access restrictions or assignees when editing the project."
                  hints={[
                    "Check Overview → Access control for team or skill rules",
                    "Assign the project to surface deliverable owners",
                  ]}
                  className="lux-pd-tab__empty lux-pd-tab__empty--compact"
                />
              )}
            </section>
          </div>
        </div>
      </ProjectDetailsTabShell>
    );
  }
}

export default ProjectDetailsMembers;
