import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import CreateWorkItemSidebar from "../../components/modal/CreateWorkItemSidebar";
import { buildPlannerAssignEmployeeContext } from "../plannerAssignContext.utils";
import PlannerAssignEmployeeInsight from "./PlannerAssignEmployeeInsight";
import PlannerAssignAllocatedList from "./PlannerAssignAllocatedList";

function toInsightEmployee(option) {
  if (!option) return null;
  return {
    id: option.id != null ? option.id : option.value,
    name: option.name || option.label,
    userTeamId: option.userTeamId,
    serviceLines: option.serviceLines,
  };
}

export default function PlannerAssignWorkPanel({
  show,
  onClose,
  employees,
  workItems,
  permission,
  weekStartMoment,
  horizonWeeks,
  holidayItems,
  reduceForHolidays,
  filterOptions,
  leaveMap,
  capacityOverrides,
  rangeLabel,
  handleReloadWorkItems,
  assignContext,
  minDate,
  maxDate,
  shellKicker = "Team capacity",
  shellTitle = "Assign work",
  shellSubtitle = "Review existing load for the selected person, then schedule new work across the planning horizon.",
}) {
  const [insightEmployee, setInsightEmployee] = useState(null);

  useEffect(() => {
    if (!show) {
      setInsightEmployee(null);
      return;
    }
    if (assignContext && assignContext.employee) {
      setInsightEmployee(assignContext.employee);
    }
  }, [show, assignContext]);

  const handleEmployeeChange = useCallback((option) => {
    setInsightEmployee(toInsightEmployee(option));
  }, []);

  const context = useMemo(
    () =>
      insightEmployee && weekStartMoment
        ? buildPlannerAssignEmployeeContext({
            employee: insightEmployee,
            workItems,
            startMoment: weekStartMoment,
            horizonWeeks,
            holidayItems,
            reduceForHolidays,
            filterOptions,
            leaveMap,
            capacityOverrides,
          })
        : null,
    [
      insightEmployee,
      workItems,
      weekStartMoment,
      horizonWeeks,
      holidayItems,
      reduceForHolidays,
      filterOptions,
      leaveMap,
      capacityOverrides,
    ]
  );

  if (typeof document === "undefined") return null;

  return createPortal(
    <LuxCreatePanelShell
      show={show}
      onClose={onClose}
      panelId="planner-assign-work-panel"
      className="lux-create-panel--planner-assign create_nonproject_right_sidebar"
      kicker={shellKicker}
      title={shellTitle}
      subtitle={shellSubtitle}
    >
      <div className="lux-planner-assign-panel">
        <PlannerAssignEmployeeInsight context={context} rangeLabel={rangeLabel} />
        <div className="lux-planner-assign-panel__workspace">
          <div className="lux-planner-assign-panel__form">
          <CreateWorkItemSidebar
            key={assignContext && assignContext.key ? assignContext.key : "planner-assign-default"}
            plannerEmbedded
            employees={employees}
            show={show}
            closeActionHandler={onClose}
            permission={permission}
            defaultSelectedStatusOption="ASSIGNED"
            handleReloadWorkItems={handleReloadWorkItems}
            onEmployeeChange={handleEmployeeChange}
            prefillKey={assignContext && assignContext.key}
            prefillEmployee={assignContext && assignContext.employee}
            prefillDate={assignContext && assignContext.prefillDate}
            prefillStartTime={assignContext && assignContext.prefillStartTime}
            minDate={minDate}
            maxDate={maxDate}
            plannerDayCapacityMap={context && context.dayCapacityMap}
          />
          </div>
          <PlannerAssignAllocatedList context={context} />
        </div>
      </div>
    </LuxCreatePanelShell>,
    document.body
  );
}
