import React, { Component } from "react";
import { getQuestionLayoutSpan } from "../../feedbackForm.utils";

class SingleDecisionOptionSingleSelectInput extends Component {
  onChange = (value) => {
    this.props.onChange({ ...this.props.questionConfig, answer: value });
  };

  render() {
    const { questionConfig, readonly } = this.props;
    if (!questionConfig) return null;
    const span = getQuestionLayoutSpan(questionConfig.type);
    const id = `lux-fb-consent-${questionConfig.id}`;

    return (
      <div className={`lux-fb-q lux-fb-q--${span}`}>
        <div className="lux-fb-q__card lux-fb-q__card--consent">
          <div className="radioField m-0">
            <input
              type="checkbox"
              name="conditions"
              id={id}
              onChange={(event) => this.onChange(event.target.checked)}
              disabled={readonly}
              checked={questionConfig.answer === true}
            />
            <label htmlFor={id}>
              {questionConfig.question}
              {questionConfig.mandatory === true && (
                <span className="lux-fb-q__required" aria-label="required">
                  *
                </span>
              )}
            </label>
          </div>
        </div>
      </div>
    );
  }
}
export default SingleDecisionOptionSingleSelectInput;
