import dateUtils from "_helpers/date.utils";
import originalMoment from "moment";
import { extendMoment } from "moment-range";

const moment = extendMoment(originalMoment);

export function parseNoteDateTime(value) {
  if (!value) return null;
  if (typeof value === "string") {
    const m = dateUtils.convertDateStringToMoment(value);
    return m && m.isValid() ? m : null;
  }
  if (Array.isArray(value) && value.length >= 5) {
    const [y, mo, d, h, mi] = value;
    return moment({ year: y, month: (mo || 1) - 1, day: d || 1, hour: h || 0, minute: mi || 0 });
  }
  return null;
}

export function formatNoteWhen(value) {
  const m = parseNoteDateTime(value);
  if (!m) return "—";
  const now = moment();
  if (m.isSame(now, "day")) return `Today · ${m.format("HH:mm")}`;
  if (m.isSame(now.clone().subtract(1, "day"), "day")) return `Yesterday · ${m.format("HH:mm")}`;
  if (m.isSame(now.clone().add(1, "day"), "day")) return `Tomorrow · ${m.format("HH:mm")}`;
  return m.format("ddd, D MMM YYYY · HH:mm");
}

export function formatNoteWhenShort(value) {
  const m = parseNoteDateTime(value);
  return m ? m.format("D MMM YYYY") : "—";
}

export function isNotePending(note) {
  return note && String(note.status || "").toUpperCase() !== "COMPLETED";
}

export function filterPendingNotes(items) {
  return (items || []).filter(isNotePending);
}

export function filterNotesByText(items, query) {
  const q = (query || "").trim().toLowerCase();
  if (!q) return items || [];
  return (items || []).filter((n) => {
    const name = (n.name || "").toLowerCase();
    const desc = (n.description || "").toLowerCase();
    return name.includes(q) || desc.includes(q);
  });
}

export function buildNoteSavePayload({
  name,
  description,
  noteDateTimeLocal,
  note,
  employeeId,
  remindMe = false,
  status,
}) {
  const m = noteDateTimeLocal ? moment(noteDateTimeLocal) : moment();
  const noteDateTime = m.isValid()
    ? m.format(dateUtils.SERVER_DATE_FORMAT)
    : moment().format(dateUtils.SERVER_DATE_FORMAT);
  const resolvedStatus =
    status === "COMPLETED" || status === "IN_PROGRESS"
      ? status
      : note && note.status === "COMPLETED"
        ? "COMPLETED"
        : "IN_PROGRESS";
  const body = {
    name: (name || "").trim(),
    description: (description || "").trim(),
    noteDateTime,
    remindMe: !!remindMe,
    status: resolvedStatus,
  };
  if (note && note.id) body.id = note.id;
  if (employeeId != null) body.employeeId = employeeId;
  return body;
}

export function getNotesLoadRange(monthsBack = 12, monthsForward = 3) {
  const start = moment().subtract(monthsBack, "months").startOf("day");
  const end = moment().add(monthsForward, "months").endOf("day");
  return {
    startDate: start.format(dateUtils.SERVER_DATE_FORMAT),
    endDate: end.format(dateUtils.SERVER_DATE_FORMAT),
  };
}

export function buildNotesSummary(items) {
  const list = items || [];
  const pending = filterPendingNotes(list);
  const done = list.length - pending.length;
  return {
    total: list.length,
    pending: pending.length,
    completed: done,
  };
}

export function noteCardTone(note) {
  if (!isNotePending(note)) return "done";
  const m = parseNoteDateTime(note.noteDateTime);
  if (m && m.isBefore(moment(), "day")) return "overdue";
  if (m && m.isSame(moment(), "day")) return "today";
  return "upcoming";
}
