import React from "react";
import { NavLink } from "react-router-dom";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import { getDeliverableStatusMeta } from "./deliverableList.utils";

function formatScheduleRange(start, end) {
  const startM = start && dateUtils.convertDateStringToMoment(start);
  const endM = end && dateUtils.convertDateStringToMoment(end);
  if (!startM && !endM) return "—";
  const fmt = (m) => (m ? m.format("D MMM YYYY") : "—");
  if (startM && endM) return `${fmt(startM)} → ${fmt(endM)}`;
  return fmt(startM || endM);
}

export default function WorkItemCreateContextInsight({ taskInfo }) {
  if (!taskInfo) return null;

  const statusMeta = getDeliverableStatusMeta(taskInfo.status);
  const project = taskInfo.projectInfo;
  const projectRef =
    project && (project.itemIdUserTeamPrefix || project.id);
  const projectPath = projectRef ? `/project/details/${projectRef}` : null;
  const deliverableRef = taskInfo.itemIdUserTeamPrefix || taskInfo.id;
  const deliverablePath = `/project/deliverable/${deliverableRef}`;
  const scheduleLabel = formatScheduleRange(
    taskInfo.estStartTime,
    taskInfo.estCompletionTime
  );

  return (
    <div className="lux-workitem-create-context" aria-label="Project and deliverable context">
      <article className="lux-workitem-create-context__card">
        <span className="lux-workitem-create-context__icon" aria-hidden="true">
          <i className="fe fe-briefcase" />
        </span>
        <div className="lux-workitem-create-context__copy">
          <span className="lux-workitem-create-context__eyebrow">Project</span>
          {projectPath ? (
            <NavLink to={projectPath} className="lux-workitem-create-context__title">
              {project && project.name ? project.name : projectRef}
              <i className="fe fe-arrow-up-right" aria-hidden="true" />
            </NavLink>
          ) : (
            <span className="lux-workitem-create-context__title is-static">
              {project && project.name ? project.name : "—"}
            </span>
          )}
          {project && project.category && (
            <p className="lux-workitem-create-context__meta">{project.category}</p>
          )}
        </div>
      </article>

      <article className="lux-workitem-create-context__card is-deliverable">
        <span className="lux-workitem-create-context__icon" aria-hidden="true">
          <i className="fe fe-check-square" />
        </span>
        <div className="lux-workitem-create-context__copy">
          <span className="lux-workitem-create-context__eyebrow">Deliverable</span>
          <NavLink to={deliverablePath} className="lux-workitem-create-context__title">
            {taskInfo.name || deliverableRef}
            <i className="fe fe-arrow-up-right" aria-hidden="true" />
          </NavLink>
          <p className="lux-workitem-create-context__meta">
            <span>{scheduleLabel}</span>
            <span className="lux-workitem-create-context__dot">·</span>
            <span
              className={classNames(
                "lux-workitem-create-context__status",
                `is-${statusMeta.tone}`
              )}
            >
              {statusMeta.label}
            </span>
          </p>
        </div>
      </article>
    </div>
  );
}
