import React, { useMemo } from "react";
import classNames from "classnames/bind";
import DashboardApexChart from "../dashboard/DashboardApexChart";
import TimesheetLuxuryDialog from "./TimesheetLuxuryDialog";
import {
  buildEntryDetailModel,
  buildEntryRowHoursChart,
  resolveTaskFromRequest,
} from "./timesheetDetail.utils";

function TimesheetEntryDetailModal({ show, payload, timeSheetRequest, weekDates, onClose }) {
  const model = useMemo(() => {
    if (!show || !payload || !timeSheetRequest) return null;

    const resolved = resolveTaskFromRequest(
      timeSheetRequest,
      payload.timesheetType,
      payload.taskGroupId,
      payload.taskIndex
    );

    if (!resolved) return null;

    return buildEntryDetailModel({
      timesheetType: payload.timesheetType,
      taskGroupId: payload.taskGroupId,
      timeEntryTaskSection: resolved.section,
      timeSheetTaskItem: resolved.task,
      weekDates,
    });
  }, [show, payload, timeSheetRequest, weekDates]);

  const chart = useMemo(() => (model ? buildEntryRowHoursChart(model.dayRows) : null), [model]);

  if (!model) {
    return (
      <TimesheetLuxuryDialog
        show={show}
        onClose={onClose}
        ariaLabel="Time entry details"
        kicker="Time entry"
        title="Entry not found"
        subtitle="This row may have been removed."
      >
        <p className="lux-ts-detail__empty">Unable to load entry details.</p>
      </TimesheetLuxuryDialog>
    );
  }

  return (
    <TimesheetLuxuryDialog
      show={show}
      onClose={onClose}
      wide
      ariaLabel="Time entry details"
      kicker="Time entry line"
      kickerIcon="fe-briefcase"
      title={model.title}
      subtitle={model.subtitle}
      badge={model.badge}
      footer={
        <p className="lux-ts-detail__foot-note">
          Click a day column on the board to see all entries for that date.
        </p>
      }
    >
      <div className="lux-ts-detail__kpi-grid">
        <article className="lux-ts-detail__kpi is-primary">
          <span>Week total</span>
          <strong>{model.rowTotalDisplay}</strong>
        </article>
        <article className="lux-ts-detail__kpi">
          <span>Active days</span>
          <strong>{model.activeDays}</strong>
        </article>
        <article className="lux-ts-detail__kpi">
          <span>Avg / active day</span>
          <strong>{model.avgPerActiveDay}</strong>
        </article>
        <article className="lux-ts-detail__kpi">
          <span>Days with notes</span>
          <strong>{model.daysWithComments}</strong>
        </article>
      </div>

      <div className="lux-ts-detail__split">
        <section className="lux-ts-detail__card">
          <h4 className="lux-ts-detail__card-title">Hours this week</h4>
          <p className="lux-ts-detail__card-sub">Daily breakdown for this row · 8h reference line</p>
          {chart && (
            <DashboardApexChart type="bar" series={chart.series} options={chart.options} height={220} />
          )}
        </section>

        <section className="lux-ts-detail__card">
          <h4 className="lux-ts-detail__card-title">Day-by-day</h4>
          <p className="lux-ts-detail__card-sub">Status, hours, and notes per day</p>
          <ul className="lux-ts-detail__day-list">
            {model.dayRows.map((row) => (
              <li
                key={row.dateString}
                className={classNames("lux-ts-detail__day-row", {
                  "has-hours": row.mins > 0,
                  "has-notes": row.hasDetails,
                })}
              >
                <div className="lux-ts-detail__day-row-main">
                  <span className="lux-ts-detail__day-row-date">{row.dayLabel}</span>
                  <span className={classNames("lux-ts-detail__status-pill", `is-${row.statusMeta.tone}`)}>
                    <i className={`fe ${row.statusMeta.icon}`} aria-hidden="true" />
                    {row.statusMeta.label}
                  </span>
                </div>
                <div className="lux-ts-detail__day-row-hours">{row.hoursDisplay}</div>
                {(row.comments || row.skill || row.quantity) && (
                  <div className="lux-ts-detail__day-row-meta">
                    {row.comments && (
                      <p className="lux-ts-detail__comment">
                        <i className="fe fe-message-square" aria-hidden="true" />
                        {row.comments}
                      </p>
                    )}
                    {(row.skill || row.quantity) && (
                      <p className="lux-ts-detail__meta-line">
                        {row.skill && <span>Skill: {row.skill}</span>}
                        {row.quantity && <span>Qty: {row.quantity}</span>}
                      </p>
                    )}
                  </div>
                )}
              </li>
            ))}
          </ul>
        </section>
      </div>
    </TimesheetLuxuryDialog>
  );
}

export default TimesheetEntryDetailModal;
