import React, { Component } from "react";
import { connect } from "react-redux";
import { employeeActions } from "_actions";
import { store } from "_helpers";
import ProjectEstimateAddLineModal from "../modal/ProjectEstimateAddLineModal";
import { getMonthRangeOptions, getEstimateTotal } from "./projectEstimate.utils";

class ProjectEstimateTeam extends Component {
    constructor() {
        super();
        this.state = {
            teamProjectEstimate: null,
            showAddLineModal: false,
        };
    }

    componentDidMount() {
        this.setState({ teamProjectEstimate: this.props.teamProjectEstimate });
    }

    componentDidUpdate(prevProps) {
        if (prevProps.teamProjectEstimate !== this.props.teamProjectEstimate) {
            this.setState({ teamProjectEstimate: this.props.teamProjectEstimate });
        }
    }

    getMonthOptions = () => getMonthRangeOptions(
        this.props.projectInfo.estStartTime,
        this.props.projectInfo.estCompletionTime
    );

    onAddMonthlyEstimate = (month, estimateType, estimateName, estimateHours) => {
        this.setState((prevState) => {
            const updated = {
                ...prevState.teamProjectEstimate,
                estimates: {
                    ...(prevState.teamProjectEstimate.estimates || {}),
                    [month]: {
                        ...(prevState.teamProjectEstimate.estimates && prevState.teamProjectEstimate.estimates[month]) || {},
                        [estimateType]: {
                            ...((prevState.teamProjectEstimate.estimates
                                && prevState.teamProjectEstimate.estimates[month]
                                && prevState.teamProjectEstimate.estimates[month][estimateType]) || {}),
                            [estimateName]: estimateHours,
                        },
                    },
                },
                estimateTypes: [...new Set([
                    ...(prevState.teamProjectEstimate.estimateTypes || []),
                    estimateType,
                ])],
            };
            return { teamProjectEstimate: updated };
        }, () => {
            this.props.onAddTeamEstimate(this.props.teamId, this.state.teamProjectEstimate);
        });
    };

    removeMonthFromEstimate = (monthToBeDeleted) => {
        const teamProjectEstimateNew = { ...this.state.teamProjectEstimate };
        delete teamProjectEstimateNew.estimates[monthToBeDeleted];
        this.setState({ teamProjectEstimate: teamProjectEstimateNew }, () => {
            this.props.onAddTeamEstimate(this.props.teamId, this.state.teamProjectEstimate);
        });
    };

    renderHourColumns = (hours) => {
        const { projectItem } = this.props;
        return (
            <>
                <span className="lux-estimate-line__val">{hours.estimate}</span>
                {projectItem.automationEnabled &&
                    <span className="lux-estimate-line__val lux-estimate-line__val--muted">{hours.estimateAutomation}</span>
                }
                {projectItem.revisedEstEnabled &&
                    <span className="lux-estimate-line__val lux-estimate-line__val--accent">{hours.estimateRevised}</span>
                }
            </>
        );
    };

    renderColumnHeaders = () => {
        const { projectItem } = this.props;
        return (
            <div className="lux-estimate-line lux-estimate-line--head">
                <span className="lux-estimate-line__name">Resource</span>
                <span className="lux-estimate-line__val">Hours</span>
                {projectItem.automationEnabled && <span className="lux-estimate-line__val">W/ tool</span>}
                {projectItem.revisedEstEnabled && <span className="lux-estimate-line__val">Revised</span>}
            </div>
        );
    };

    render() {
        const team = this.props.teamProjectEstimate || this.state.teamProjectEstimate;
        if (!team) return null;

        const monthOptions = this.getMonthOptions();
        const estimateTypes = team.estimateTypes || [];
        const { editable, projectItem } = this.props;

        return (
            <article className="lux-estimate-team-card">
                <header className="lux-estimate-team-card__head">
                    <span className="lux-estimate-team-card__icon"><i className="fe fe-users" /></span>
                    <div>
                        <h3 className="lux-estimate-team-card__name">{team.teamName}</h3>
                        <span className="lux-estimate-team-card__types">
                            {estimateTypes.length > 0 ? estimateTypes.join(" · ") : "No types yet"}
                        </span>
                    </div>
                    {editable &&
                        <button
                            type="button"
                            className="lux-estimate-team-card__remove link"
                            onClick={() => this.props.removeTeamFromEstimate(this.props.teamId)}
                            title="Remove team"
                        >
                            <i className="fe fe-trash-2" />
                        </button>
                    }
                </header>

                {team.estimates && monthOptions.map(({ value: monthYear }) => {
                    if (!team.estimates[monthYear]) return null;
                    return (
                        <div key={monthYear} className="lux-estimate-month-block">
                            <div className="lux-estimate-month-block__head">
                                <span><i className="fe fe-calendar" /> {monthYear}</span>
                                {editable &&
                                    <button
                                        type="button"
                                        className="link lux-estimate-month-block__remove"
                                        onClick={() => this.removeMonthFromEstimate(monthYear)}
                                        title="Remove month"
                                    >
                                        <i className="fe fe-x" />
                                    </button>
                                }
                            </div>
                            {estimateTypes.map((estimateType) => {
                                const typeData = team.estimates[monthYear][estimateType];
                                if (!typeData) return null;
                                return (
                                    <div key={`${monthYear}-${estimateType}`} className="lux-estimate-type-block">
                                        <span className="lux-estimate-type-block__label">{estimateType}</span>
                                        {this.renderColumnHeaders()}
                                        {Object.keys(typeData).map((estimateName) => (
                                            <div key={estimateName} className="lux-estimate-line">
                                                <span className="lux-estimate-line__name" title={estimateName}>{estimateName}</span>
                                                {this.renderHourColumns(typeData[estimateName])}
                                            </div>
                                        ))}
                                    </div>
                                );
                            })}
                        </div>
                    );
                })}

                {estimateTypes.length > 0 &&
                    <div className="lux-estimate-team-card__totals">
                        <span className="lux-estimate-team-card__totals-label">Team total</span>
                        <div className="lux-estimate-team-card__totals-vals">
                            {estimateTypes.map((estimateType) => (
                                <span key={estimateType} className="lux-estimate-team-card__total-chip">
                                    {estimateType}: {getEstimateTotal(team, estimateType, "estimate", monthOptions)}h
                                </span>
                            ))}
                        </div>
                    </div>
                }

                {editable &&
                    <>
                        <button
                            type="button"
                            className="lux-estimate-add-line-btn"
                            onClick={() => {
                                if (!this.props.employeeAppConfig) {
                                    store.dispatch(employeeActions.getModuleConfig(this.props.teamId));
                                }
                                this.setState({ showAddLineModal: true });
                            }}
                        >
                            <i className="fe fe-plus" /> Add estimate line
                        </button>
                        <ProjectEstimateAddLineModal
                            show={this.state.showAddLineModal}
                            teamId={this.props.teamId}
                            teamName={team.teamName}
                            projectInfo={this.props.projectInfo}
                            projectItem={projectItem}
                            userTeams={this.props.userTeams}
                            onClose={() => this.setState({ showAddLineModal: false })}
                            onAdd={this.onAddMonthlyEstimate}
                        />
                    </>
                }
            </article>
        );
    }
}

const mapStateToProps = (state) => ({
    employeeAppConfig: state.employees.createConfig,
});

export default connect(mapStateToProps)(ProjectEstimateTeam);
