import React from "react";
import classNames from "classnames/bind";
import {
  getEventsForDay,
  getMonthGridDays,
  MONTH_CELL_EVENT_LIMIT,
} from "./customCalendar.utils";
import LuxCalendarEventChip from "./LuxCalendarEventChip";

const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

export default function LuxCustomCalendarMonth({
  date,
  events,
  selectedEvent,
  onSelectEvent,
  onDayClick,
}) {
  const days = getMonthGridDays(date);

  return (
    <div className="lux-custom-cal lux-custom-cal--month">
      <div className="lux-custom-cal__weekdays" role="row">
        {WEEKDAYS.map((name) => (
          <span key={name} className="lux-custom-cal__weekday" role="columnheader">
            {name}
          </span>
        ))}
      </div>
      <div className="lux-custom-cal__month-grid" role="grid">
        {days.map((day) => {
          const dayEvents = getEventsForDay(events, day.moment);
          const visible = dayEvents.slice(0, MONTH_CELL_EVENT_LIMIT);
          const more = dayEvents.length - visible.length;

          return (
            <button
              key={day.moment.format("YYYY-MM-DD")}
              type="button"
              className={classNames("lux-custom-cal__month-cell", {
                "is-off-month": !day.isCurrentMonth,
                "is-today": day.isToday,
                "is-weekend": day.isWeekend,
              })}
              onClick={(e) => onDayClick && onDayClick(day.date, e)}
            >
              <span className="lux-custom-cal__month-cell-head">
                <span className="lux-custom-cal__month-day">{day.moment.date()}</span>
                {day.isToday && <span className="lux-custom-cal__today-pill">Today</span>}
              </span>
              <span className="lux-custom-cal__month-events">
                {visible.map((ev) => (
                  <LuxCalendarEventChip
                    key={ev.id}
                    event={ev}
                    mini
                    selected={selectedEvent && selectedEvent.id === ev.id}
                    onSelect={onSelectEvent}
                  />
                ))}
                {more > 0 && (
                  <span className="lux-custom-cal__more">+{more} more</span>
                )}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}
