import React, { Component } from "react";
import { ProfileChannelCard } from "views/hrms/components/profile/ProfileSettingsShared";
import ProjectDetailsTabShell from "./ProjectDetailsTabShell";
import {
  PROJECT_NOTIFICATION_PREFS,
  buildNotificationPrefState,
} from "./projectDetailsTab.utils";

class ProjectDetailsNotification extends Component {
  constructor() {
    super();
    this.state = { prefs: buildNotificationPrefState() };
  }

  handlePrefChange = (id, enabled) => {
    this.setState((prev) => ({
      prefs: { ...prev.prefs, [id]: enabled },
    }));
  };

  render() {
    const { projectInfo, readOnly } = this.props;
    const enabledCount = Object.values(this.state.prefs).filter(Boolean).length;

    return (
      <ProjectDetailsTabShell
        icon="fe fe-bell"
        eyebrow="Alerts"
        title="Notification preferences"
        subtitle="Preview how you would like to be notified about this project. Saving requires a notifications API."
        stats={[
          { key: "on", label: "Enabled", value: enabledCount, hint: "Local preview" },
          {
            key: "total",
            label: "Channels",
            value: PROJECT_NOTIFICATION_PREFS.length,
            hint: "Available types",
          },
        ]}
      >
        <div className="lux-pd-notifications">
          <p className="lux-pd-notifications__banner">
            <i className="fe fe-info" aria-hidden="true" />
            Preferences are shown for <strong>{projectInfo ? projectInfo.name : "this project"}</strong> only.
            Changes are not persisted until notification settings are available on the server.
          </p>

          <div className="lux-pd-notifications__grid">
            {PROJECT_NOTIFICATION_PREFS.map((pref) => (
              <ProfileChannelCard
                key={pref.id}
                icon={pref.icon}
                label={pref.label}
                description={pref.description}
                enabled={this.state.prefs[pref.id]}
                disabled={readOnly || pref.comingSoon}
                comingSoon={pref.comingSoon}
                onChange={(on) => this.handlePrefChange(pref.id, on)}
              />
            ))}
          </div>
        </div>
      </ProjectDetailsTabShell>
    );
  }
}

export default ProjectDetailsNotification;
