import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import BidPipelineFunnelDiagram from "views/sales/components/fragments/BidPipelineFunnelDiagram";
import {
  buildActivityStatusDonutChart,
  buildActivityOutcomeDonutChart,
  buildActivityPriorityBarChart,
  buildActivityCategoryBarChart,
  buildActivityTypeDonutChart,
  buildActivityChecklistDonutChart,
  buildActivityHoursCompareChart,
  buildActivityCompletionDonutChart,
  buildActivityLoggedHoursTrendChart,
  buildActivityOwnerBarChart,
} from "./workItemActivity.charts";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const SUMMARY_STORAGE_KEY = "famstack-activity-summary-expanded";

const QUICK_FILTERS = [
  { value: "ALL", label: "All" },
  { value: "ONGOING", label: "On going" },
  { value: "COMPLETED", label: "Completed" },
  { value: "ASSIGNED", label: "Assigned" },
  { value: "CREATEDBYME", label: "Created by me" },
];

class WorkItemActivitiesSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = { expanded: readSummaryExpanded(SUMMARY_STORAGE_KEY) };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => {
        writeSummaryExpanded(SUMMARY_STORAGE_KEY, this.state.expanded);
      }
    );
  };

  getShowFilter = () => {
    const options = this.props.filterOptions;
    return (options && options.SHOW && options.SHOW.selected) || "COMPLETED";
  };

  quickFilter = (value) => {
    if (this.props.onQuickFilter) {
      this.props.onQuickFilter(value);
    }
  };

  getCharts = (stat) => ({
    statusDonut: buildActivityStatusDonutChart(stat),
    outcomeDonut: buildActivityOutcomeDonutChart(stat),
    priorityBar: buildActivityPriorityBarChart(stat),
    categoryBar: buildActivityCategoryBarChart(stat),
    typeDonut: buildActivityTypeDonutChart(stat),
    checklistDonut: buildActivityChecklistDonutChart(stat),
    hoursBar: buildActivityHoursCompareChart(stat),
    completionDonut: buildActivityCompletionDonutChart(stat),
    loggedTrend: buildActivityLoggedHoursTrendChart(stat),
    ownerBar: buildActivityOwnerBarChart(stat),
  });

  buildContextLine = (stat, visibleCount, filterOptions, dateLabel) => {
    const parts = [];
    if (dateLabel) parts.push(dateLabel);
    if (visibleCount !== stat.total) {
      parts.push(`${visibleCount} of ${stat.total} shown`);
    }
    if (filterOptions && filterOptions.filterText) {
      parts.push(`matching “${filterOptions.filterText}”`);
    }
    parts.push(`${stat.loggedHours} logged · ${stat.pending} pending inbox`);
    return parts.join(" · ");
  };

  renderFilterChips = (showFilter, compact) => (
    <div
      className={classNames("lux-bid-summary__filters", {
        "lux-bid-summary__filters--compact": compact,
      })}
      role="group"
      aria-label="Filter activities by status"
    >
      {QUICK_FILTERS.map((option) => (
        <button
          key={option.value}
          type="button"
          className={classNames("lux-bid-summary__filter-chip", {
            "is-active": showFilter === option.value,
          })}
          onClick={() => this.quickFilter(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );

  renderKpiStrip = (stat) => (
    <div className="lux-bid-summary__kpi-strip" role="list" aria-label="Activity metrics">
      {stat.kpis.map((kpi) => (
        <article
          key={kpi.key}
          className={classNames("lux-bid-summary__kpi", kpi.tone && `is-${kpi.tone}`)}
          role="listitem"
        >
          <div className="lux-bid-summary__kpi-top">
            <span className="lux-bid-summary__kpi-label">{kpi.label}</span>
            <span className="lux-bid-summary__kpi-icon" aria-hidden="true">
              <i className={kpi.icon} />
            </span>
          </div>
          <strong className="lux-bid-summary__kpi-value">
            <CountUp end={Number(kpi.value) || 0} duration={0.85} decimals={kpi.key === "logged" ? 1 : 0} />
            {kpi.key === "utilization" && "%"}
          </strong>
          {kpi.hint && <span className="lux-bid-summary__kpi-hint">{kpi.hint}</span>}
        </article>
      ))}
    </div>
  );

  renderRateChips = (stat) => {
    const completion = stat.completionMetrics;
    const hours = stat.hoursMetrics;
    if (!completion || !hours) return null;

    return (
      <div className="lux-activity-metric-chips">
        <article className="lux-activity-metric-chip is-completion">
          <div className="lux-activity-metric-chip__viz">
            <div className="lux-bid-summary__rate-ring" style={{ "--lux-win-pct": `${completion.rate}%` }} aria-hidden="true">
              <span><CountUp end={completion.rate} duration={0.8} />%</span>
            </div>
          </div>
          <div className="lux-activity-metric-chip__copy">
            <strong className="lux-activity-metric-chip__title">Activity completion</strong>
            <p className="lux-activity-metric-chip__explain">{completion.explain}</p>
            <p className="lux-activity-metric-chip__headline">{completion.fractionLabel}</p>
            <div className="lux-bid-summary__bar lux-activity-metric-chip__bar" aria-hidden="true">
              <span className="lux-bid-summary__bar-segment is-green" style={{ flexGrow: Math.max(completion.completed, 0.15) }} title={`Finished: ${completion.completed}`} />
              <span className="lux-bid-summary__bar-segment is-slate" style={{ flexGrow: Math.max(completion.open, 0.15) }} title={`Open: ${completion.open}`} />
            </div>
            <ul className="lux-activity-metric-chip__legend">
              <li><span className="lux-bid-summary__legend-dot is-green" /> Finished <strong>{completion.completed}</strong></li>
              <li><span className="lux-bid-summary__legend-dot is-slate" /> Still open <strong>{completion.open}</strong></li>
            </ul>
          </div>
        </article>

        <article className="lux-activity-metric-chip is-hours">
          <div className="lux-activity-metric-chip__viz">
            <div className="lux-bid-summary__rate-ring is-pipeline" style={{ "--lux-win-pct": `${hours.rate}%` }} aria-hidden="true">
              <span><CountUp end={hours.rate} duration={0.8} />%</span>
            </div>
          </div>
          <div className="lux-activity-metric-chip__copy">
            <strong className="lux-activity-metric-chip__title">Time booked vs plan</strong>
            <p className="lux-activity-metric-chip__explain">{hours.explain}</p>
            <div className="lux-activity-metric-chip__compare">
              <div className="lux-activity-metric-chip__compare-item is-logged">
                <span>Logged</span>
                <strong>{hours.loggedHours}</strong>
                <em>{hours.loggedHoursNum}h actual</em>
              </div>
              <div className="lux-activity-metric-chip__compare-item is-estimated">
                <span>Estimated</span>
                <strong>{hours.estimatedHours}</strong>
                <em>{hours.estimatedHoursNum}h planned</em>
              </div>
            </div>
            <span className={classNames("lux-activity-metric-chip__variance", `is-${hours.varianceTone}`)}>
              <i className={`fe ${hours.varianceTone === "over" ? "fe-trending-up" : hours.varianceTone === "under" ? "fe-trending-down" : "fe-minus"}`} aria-hidden="true" />
              {hours.varianceLabel}
              {hours.rate > 0 && ` · ${hours.rate}% of plan captured`}
            </span>
          </div>
        </article>
      </div>
    );
  };

  renderMetricContextFooter = (stat, type) => {
    if (type === "completion") {
      const c = stat.completionMetrics;
      if (!c || !c.total) return null;
      return (
        <footer className="lux-activity-metric-context">
          <span><strong>{c.completed}</strong> finished</span>
          <span><strong>{c.open}</strong> still in progress or not started</span>
          <span className="lux-activity-metric-context__emphasis">{c.fractionLabel} ({c.rate}%)</span>
        </footer>
      );
    }
    if (type === "hours") {
      const h = stat.hoursMetrics;
      if (!h) return null;
      return (
        <footer className="lux-activity-metric-context">
          <span><strong>{h.loggedHours}</strong> logged on completed work</span>
          <span><strong>{h.estimatedHours}</strong> planned across filter</span>
          <span className={classNames("lux-activity-metric-context__emphasis", `is-${h.varianceTone}`)}>{h.varianceLabel}</span>
        </footer>
      );
    }
    return null;
  };

  renderContextChartPanel = (title, subtitle, chart, emptyMessage, contextType, stat, { height = 168, chartType = "donut", wide = false } = {}) => (
    <article className={classNames("lux-bid-summary__chart-panel lux-bid-summary__chart-panel--contextual", { "lux-bid-summary__chart-panel--wide": wide })}>
      <div className="lux-bid-summary__panel-head">
        <div>
          <h3 className="lux-bid-summary__panel-title">{title}</h3>
          {subtitle && <p className="lux-bid-summary__panel-sub">{subtitle}</p>}
        </div>
      </div>
      <div className="lux-bid-summary__chart-body">
        {!chart && <p className="lux-bid-summary__chart-empty">{emptyMessage}</p>}
        {chart && <DashboardApexChart type={chartType} series={chart.series} options={chart.options} height={height} />}
      </div>
      {chart && this.renderMetricContextFooter(stat, contextType)}
    </article>
  );

  renderHighlights = (stat) => (
    <div className="lux-po-summary__highlights" role="list" aria-label="Activity highlights">
      {stat.highlights.map((item) => (
        <article key={item.key} className={classNames("lux-po-summary__highlight", item.tone && `is-${item.tone}`)} role="listitem">
          <span className="lux-po-summary__highlight-icon" aria-hidden="true"><i className={item.icon} /></span>
          <div className="lux-po-summary__highlight-copy">
            <span className="lux-po-summary__highlight-label">{item.label}</span>
            <strong><CountUp end={item.value} duration={0.75} /></strong>
            <span className="lux-po-summary__highlight-hint">{item.hint}</span>
          </div>
        </article>
      ))}
    </div>
  );

  renderInsightCard = (insight) => (
    <article key={insight.key} className="lux-bid-summary__insight lux-po-summary__insight">
      <header>
        <i className={insight.icon} aria-hidden="true" />
        <div>
          <strong>{insight.title}</strong>
          <span>{insight.subtitle}</span>
        </div>
      </header>
      {!insight.mix || !insight.mix.length ? (
        <div className="lux-bid-summary__bar lux-bid-summary__bar--empty">{insight.emptyLabel}</div>
      ) : (
        <>
          <div className="lux-bid-summary__bar" aria-hidden="true">
            {insight.mix.map((seg) => (
              <span key={seg.key} className={classNames("lux-bid-summary__bar-segment", `is-${seg.tone}`)} style={{ flexGrow: Math.max(seg.count, 0.15) }} title={`${seg.label}: ${seg.count}`} />
            ))}
          </div>
          <ul className="lux-bid-summary__legend">
            {insight.mix.map((seg) => (
              <li key={seg.key}>
                <span className={classNames("lux-bid-summary__legend-dot", `is-${seg.tone}`)} />
                <span>{seg.label}</span>
                <strong>{seg.count}</strong>
                <em>{seg.pct}%</em>
              </li>
            ))}
          </ul>
        </>
      )}
    </article>
  );

  renderStageFlow = (stat) => (
    <div className="lux-bid-summary__stage-flow" aria-label="Activity lifecycle stages">
      {[
        { key: "new", label: "New", count: stat.stageCounts.newCount, tone: "sky" },
        { key: "assigned", label: "Assigned", count: stat.stageCounts.assignedCount, tone: "indigo" },
        { key: "progress", label: "In progress", count: stat.stageCounts.inProgressCount, tone: "amber" },
        { key: "completed", label: "Completed", count: stat.stageCounts.completedCount, tone: "green" },
      ].map((stage, index, arr) => (
        <React.Fragment key={stage.key}>
          <div className={classNames("lux-bid-summary__stage-node", `is-${stage.tone}`)}>
            <span className="lux-bid-summary__stage-node-label">{stage.label}</span>
            <strong><CountUp end={stage.count} duration={0.7} /></strong>
          </div>
          {index < arr.length - 1 && (
            <span className="lux-bid-summary__stage-arrow" aria-hidden="true"><i className="fe fe-arrow-right" /></span>
          )}
        </React.Fragment>
      ))}
    </div>
  );

  renderChartPanel = (title, subtitle, chart, emptyMessage, { height = 168, wide = false, chartType = "donut", compactHead = false } = {}) => (
    <article className={classNames("lux-bid-summary__chart-panel", { "lux-bid-summary__chart-panel--wide": wide, "lux-bid-summary__chart-panel--compact": compactHead })}>
      <div className="lux-bid-summary__panel-head">
        <div>
          <h3 className="lux-bid-summary__panel-title">{title}</h3>
          {!compactHead && subtitle && <p className="lux-bid-summary__panel-sub">{subtitle}</p>}
        </div>
      </div>
      <div className="lux-bid-summary__chart-body">
        {!chart && <p className="lux-bid-summary__chart-empty">{emptyMessage}</p>}
        {chart && <DashboardApexChart type={chartType} series={chart.series} options={chart.options} height={height} />}
      </div>
    </article>
  );

  renderSkeleton = () => (
    <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
      <div className="lux-bid-summary lux-activity-summary is-loading">
        <Skeleton height={88} borderRadius={16} />
        <div className="lux-bid-summary__kpi-strip lux-bid-summary__kpi-strip--skeleton">
          {[1, 2, 3, 4, 5, 6].map((key) => <Skeleton key={key} height={72} borderRadius={14} />)}
        </div>
      </div>
    </SkeletonTheme>
  );

  render() {
    const { stats, dateLabel, isLoading, visibleCount, filterOptions } = this.props;
    const { expanded } = this.state;
    if (isLoading && (!stats || !stats.total)) return this.renderSkeleton();
    if (!stats) return null;

    const showFilter = this.getShowFilter();
    const charts = this.getCharts(stats);
    const count = visibleCount != null ? visibleCount : stats.total;

    return (
      <section
        className={classNames("lux-bid-summary lux-po-summary lux-activity-summary", { "is-collapsed": !expanded })}
        aria-label="Activity overview"
      >
        <div className="lux-bid-summary__header-bar">
          <div className="lux-bid-summary__header-main">
            <LuxSummaryEyebrow variant="work-item-activities" className="lux-bid-summary__eyebrow">
              Task activity intelligence
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--compact">
                <CountUp end={stats.total} duration={0.85} />{" "}
                <span>
                  activities · {stats.completionRate}% done · {stats.loggedHours} logged · {stats.pending} pending
                </span>
              </h2>
            ) : (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--bar">Activity overview</h2>
            )}
          </div>
          <button
            type="button"
            className="lux-bid-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-activity-summary-body"
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
          </button>
        </div>

        {!expanded && (
          <div className="lux-bid-summary__collapsed-strip">
            <p className="lux-bid-summary__collapsed-line">{this.buildContextLine(stats, count, filterOptions, dateLabel)}</p>
            {this.renderFilterChips(showFilter, true)}
          </div>
        )}

        <div id="lux-activity-summary-body" className="lux-bid-summary__body" aria-hidden={!expanded}>
          <div className="lux-bid-summary__toolbar">
            <p className="lux-bid-summary__subtitle">{this.buildContextLine(stats, count, filterOptions, dateLabel)}</p>
            {this.renderFilterChips(showFilter, false)}
          </div>

          <div className="lux-bid-summary__metrics-row lux-po-summary__metrics-row">
            {this.renderKpiStrip(stats)}
            {this.renderRateChips(stats)}
          </div>

          {this.renderHighlights(stats)}

          <div className="lux-bid-summary__insights lux-po-summary__insights">
            {stats.insights.map(this.renderInsightCard)}
          </div>

          {this.renderStageFlow(stats)}

          <div className="lux-po-summary__analytics lux-po-summary__analytics--primary">
            <article className="lux-bid-summary__chart-panel lux-bid-summary__chart-panel--funnel lux-bid-summary__chart-panel--funnel-compact">
              <div className="lux-bid-summary__panel-head">
                <h3 className="lux-bid-summary__panel-title">Delivery funnel</h3>
                <p className="lux-bid-summary__panel-sub">Stage progression for filtered activities</p>
              </div>
              <BidPipelineFunnelDiagram funnel={stats.funnel} totalActive={stats.total} layout="horizontal" />
            </article>
            {this.renderChartPanel("By status", "Lifecycle distribution", charts.statusDonut, "No status data yet", { height: 168, compactHead: true })}
            {this.renderChartPanel("Outcome mix", "Completed vs in progress vs open", charts.outcomeDonut, "No outcome data yet", { height: 168, compactHead: true })}
            {this.renderContextChartPanel(
              "Time booked vs plan",
              "Compares actual hours logged on completed work against the total estimated hours for all activities in your filter.",
              charts.hoursBar,
              "No hour data for this period",
              "hours",
              stats,
              { height: 168, chartType: "bar" }
            )}
          </div>

          <div className="lux-po-summary__analytics lux-po-summary__analytics--secondary lux-activity-summary__analytics--secondary">
            {this.renderChartPanel("Logged hours trend", "Completed work by day in the selected period", charts.loggedTrend, "No logged hours in this period", { height: 176, chartType: "area", wide: true, compactHead: true })}
            {this.renderChartPanel("Top categories", "Most common activity categories", charts.categoryBar, "No category data", { height: 168, chartType: "bar", compactHead: true })}
            {this.renderChartPanel("Billable scope", "Project vs non-project activities", charts.typeDonut, "No scope data", { height: 168, compactHead: true })}
            {this.renderChartPanel("Checklist state", "Completion on activities with checklists", charts.checklistDonut, "No checklist data", { height: 168, compactHead: true })}
            {this.renderChartPanel("Priority load", "Urgency across filtered activities", charts.priorityBar, "No priority data", { height: 168, chartType: "bar", compactHead: true })}
            {this.renderContextChartPanel(
              "Finished vs still open",
              "Donut shows how many filtered activities are Completed/Closed versus those still waiting to be finished.",
              charts.completionDonut,
              "No activities to measure",
              "completion",
              stats,
              { height: 168, chartType: "donut" }
            )}
            {this.renderChartPanel("Owner workload", "Activities assigned per team member", charts.ownerBar, "No owner data", { height: 168, chartType: "bar", compactHead: true })}
          </div>
        </div>
      </section>
    );
  }
}

export default WorkItemActivitiesSummary;
