import React, { Component } from "react";
import classNames from "classnames/bind";
import { connect } from "react-redux";
import { projectActions } from "_actions";
import { store } from "_helpers";
import dateUtils from "_helpers/date.utils";
import SelectInput from "views/common/fragments/formfields/SelectInput";

class ProjectDetailsHero extends Component {
    handleUpdateStatus = (projectId, status) => {
        store.dispatch(this.props.updateProjectStatus(projectId, status));
    };

    render() {
        const { item, permission, readOnly, compact } = this.props;
        if (!item) return null;

        return (
            <header className={`pd-hero lux-pd-hero ${compact ? "pd-hero--compact" : ""}`}>
                <div className="pd-hero__glow" aria-hidden="true" />
                <div className="pd-hero__inner">
                    <div className="pd-hero__identity">
                        <span className="pd-hero__badge">
                          {(item.ownerUserTeamDetails && item.ownerUserTeamDetails.name) || "Team"}
                        </span>
                        <span className="pd-hero__id">{item.itemIdUserTeamPrefix}</span>
                        <h1 className="pd-hero__title">
                            <span className="pd-hero__code">[{item.code}]</span> {item.name}
                        </h1>
                        <div className="pd-hero__chips">
                            <span className="pd-chip pd-chip--soft">
                                <i className="fe fe-user" /> {item.ownerDetails && item.ownerDetails.name}
                            </span>
                            <span className="pd-chip pd-chip--soft">
                                <i className="fe fe-calendar" /> Due {dateUtils.convertDateFormat(item.estCompletionTime)}
                            </span>
                            {item.priority &&
                                <span className="pd-chip pd-chip--accent">{item.priority}</span>
                            }
                        </div>
                    </div>
                    <div className="pd-hero__actions">
                        <SelectInput
                            options={[
                                { value: "NEW", label: "New", level: 0 },
                                { value: "ASSIGNED", label: "Assigned", level: 1 },
                                { value: "INPROGRESS", label: "In Progress", level: 2 },
                                { value: "COMPLETED", label: "Completed", level: 3 },
                                { value: "CLOSED", label: "Closed", level: 4 }]}
                            value={item.status}
                            allowLevelDown={permission.allowStatusLevelDown}
                            changeableStatus={permission.changeableStatus}
                            isReadOnly={(!permission.allowStatusChange) || readOnly}
                            itemId={item.id}
                            onChange={this.handleUpdateStatus}
                            className={classNames("tag pd-hero__status",
                                { "tag-info": item.status === "NEW" },
                                { "tag-primary": item.status === "ASSIGNED" },
                                { "tag-warning": item.status === "INPROGRESS" },
                                { "tag-success": item.status === "COMPLETED" },
                                { "tag-dark": item.status === "CLOSED" }
                            )} />
                        {!readOnly &&
                            <div className="item-action dropdown show">
                                <button type="button" className="link pd-icon-btn" data-toggle="dropdown" aria-expanded="true">
                                    <i className="fe fe-more-vertical" />
                                </button>
                                <div className="dropdown-menu dropdown-menu-right dropdownrightmenu">
                                    <button type="button" className="dropdown-item link"><i className="dropdown-icon fa fa-cloud-download" /> Download</button>
                                    <div className="dropdown-divider" />
                                    <button type="button" className="dropdown-item link"><i className="dropdown-icon fa fa-edit" /> Edit</button>
                                    <button type="button" className="dropdown-item link"><i className="dropdown-icon fa fa-paste" /> Archive</button>
                                    <button type="button" className="dropdown-item link"><i className="dropdown-icon fa fa-trash" /> Delete</button>
                                </div>
                            </div>
                        }
                    </div>
                </div>
            </header>
        );
    }
}

const mapDispatchToProps = dispatch => ({
    updateProjectStatus: projectActions.updateProjectStatus,
});

export default connect(null, mapDispatchToProps)(ProjectDetailsHero);
