import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import CountUp from "react-countup";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import { ACCOUNT_QUALITY_FILTERS } from "./accountsSummary.utils";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const SUMMARY_STORAGE_KEY = "famstack-accounts-summary-expanded";

const TYPE_FILTERS = [
  { value: "", label: "All types" },
  { value: "ACCOUNT", label: "Accounts" },
  { value: "TEAM", label: "Teams" },
  { value: "CLIENT", label: "Clients" },
  { value: "SALES_FORCE", label: "Salesforce" },
];

class AccountsPageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = { expanded: readSummaryExpanded(SUMMARY_STORAGE_KEY) };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(SUMMARY_STORAGE_KEY, this.state.expanded)
    );
  };

  buildContextLine = (stat, visibleCount, filterOptions) => {
    const parts = [];
    if (stat.isUserTeamsView) {
      parts.push("User teams directory");
    } else if (this.props.viewLabel) {
      parts.push(this.props.viewLabel);
    }
    if (visibleCount !== stat.total) {
      parts.push(`${visibleCount} of ${stat.total} shown`);
    }
    if (filterOptions && filterOptions.filterText) {
      parts.push(`matching “${filterOptions.filterText}”`);
    }
    if (this.props.typeFilter) {
      const chip = TYPE_FILTERS.find((f) => f.value === this.props.typeFilter);
      if (chip) parts.push(chip.label);
    }
    if (this.props.qualityFilter) {
      parts.push(this.getQualityFilterLabel(this.props.qualityFilter));
    }
    return parts.join(" · ");
  };

  getQualityFilterLabel = (key) => {
    const map = {
      [ACCOUNT_QUALITY_FILTERS.NEEDS_ATTENTION]: "Needs attention",
      [ACCOUNT_QUALITY_FILTERS.COMPLETE]: "Complete only",
      [ACCOUNT_QUALITY_FILTERS.MISSING_TEAMS]: "Missing teams",
      [ACCOUNT_QUALITY_FILTERS.MISSING_CLIENTS]: "Missing clients",
      [ACCOUNT_QUALITY_FILTERS.MISSING_EMAIL]: "Missing email",
      [ACCOUNT_QUALITY_FILTERS.MISSING_POC]: "No owner",
      [ACCOUNT_QUALITY_FILTERS.MISSING_DESCRIPTION]: "No description",
      [ACCOUNT_QUALITY_FILTERS.SF_NO_ID]: "SF without ID",
    };
    return map[key] || "Filtered";
  };

  onQualityChip = (filterKey) => {
    if (!this.props.onQualityFilter) return;
    const next =
      this.props.qualityFilter === filterKey ? "" : filterKey;
    this.props.onQualityFilter(next);
  };

  renderFilterChips = (typeFilter, compact) => (
    <div
      className={classNames("lux-acct-summary__filters", {
        "lux-acct-summary__filters--compact": compact,
      })}
      role="group"
      aria-label="Filter by record type"
    >
      {TYPE_FILTERS.map((option) => (
        <button
          key={option.value || "all"}
          type="button"
          className={classNames("lux-acct-summary__filter-chip", {
            "is-active": (typeFilter || "") === option.value,
          })}
          onClick={() => this.props.onTypeFilter && this.props.onTypeFilter(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );

  renderHero = (stat, visibleCount, filterOptions) => (
    <header className="lux-acct-summary__hero">
      <div className="lux-acct-summary__hero-main">
        <div className="lux-acct-summary__hero-copy">
          <h2 className="lux-acct-summary__title lux-acct-summary__title--hero">
            <CountUp end={stat.total} duration={0.85} />
            <span>{stat.isUserTeamsView ? " teams in scope" : " records in scope"}</span>
          </h2>
          <p className="lux-acct-summary__subtitle">{this.buildContextLine(stat, visibleCount, filterOptions)}</p>
        </div>

        {!stat.isUserTeamsView && (
          <div
            className="lux-acct-summary__health-ring-wrap"
            title={`${stat.quality.completeRecords} complete · ${stat.totalIssues} with gaps`}
          >
            <div
              className={classNames("lux-acct-summary__health-ring", {
                "is-strong": stat.healthScore >= 80,
                "is-fair": stat.healthScore >= 50 && stat.healthScore < 80,
                "is-weak": stat.healthScore < 50,
              })}
              style={{ "--lux-health-pct": `${stat.healthScore}%` }}
              aria-hidden="true"
            >
              <span>
                <CountUp end={stat.healthScore} duration={0.9} />%
              </span>
            </div>
            <div className="lux-acct-summary__health-copy">
              <strong>Data health</strong>
              <span>
                {stat.quality.completeRecords} complete · {stat.totalIssues} gaps
              </span>
            </div>
          </div>
        )}
      </div>
    </header>
  );

  renderKpiStrip = (stat) => (
    <div className="lux-acct-summary__grid" role="list" aria-label="Account directory metrics">
      {stat.kpis.map((kpi) => (
        <article
          key={kpi.key}
          className={classNames("lux-acct-summary__metric", kpi.tone && `lux-acct-summary__metric--${kpi.tone}`)}
          role="listitem"
        >
          <span className="lux-acct-summary__metric-icon" aria-hidden="true">
            <i className={kpi.icon} />
          </span>
          <div className="lux-acct-summary__metric-body">
            <span className="lux-acct-summary__metric-label">{kpi.label}</span>
            <strong className="lux-acct-summary__metric-value">
              <CountUp end={kpi.value} duration={0.85} />
              {kpi.suffix || ""}
            </strong>
            {kpi.hint && <span className="lux-acct-summary__metric-hint">{kpi.hint}</span>}
          </div>
        </article>
      ))}
    </div>
  );

  renderHighlights = (stat) => (
    <div className="lux-acct-summary__highlights" role="list" aria-label="Directory highlights">
      {stat.highlights.map((item) => (
        <article
          key={item.key}
          className={classNames("lux-acct-summary__highlight", item.tone && `is-${item.tone}`)}
          role="listitem"
        >
          <span className="lux-acct-summary__highlight-icon" aria-hidden="true">
            <i className={item.icon} />
          </span>
          <div className="lux-acct-summary__highlight-copy">
            <span className="lux-acct-summary__highlight-label">{item.label}</span>
            <strong>
              {item.display != null ? item.display : <CountUp end={item.value} duration={0.75} />}
            </strong>
            <span className="lux-acct-summary__highlight-hint">{item.hint}</span>
          </div>
        </article>
      ))}
    </div>
  );

  renderAttentionPanel = (stat, qualityFilter) => {
    if (stat.isUserTeamsView || !stat.attentionItems || stat.attentionItems.length === 0) {
      if (stat.isUserTeamsView || stat.total === 0) return null;
      return (
        <aside className="lux-acct-summary__attention lux-acct-summary__attention--clear">
          <i className="fe fe-check-circle" aria-hidden="true" />
          <div>
            <strong>All clear in this view</strong>
            <span>No data-quality gaps detected for visible records.</span>
          </div>
        </aside>
      );
    }

    return (
      <section className="lux-acct-summary__attention" aria-label="Records needing attention">
        <header className="lux-acct-summary__attention-head">
          <div>
            <strong>Data quality alerts</strong>
            <span>Click an issue to filter the directory list below</span>
          </div>
          <div className="lux-acct-summary__attention-quick">
            <button
              type="button"
              className={classNames("lux-acct-summary__attention-quick-btn", {
                "is-active": qualityFilter === ACCOUNT_QUALITY_FILTERS.NEEDS_ATTENTION,
              })}
              onClick={() => this.onQualityChip(ACCOUNT_QUALITY_FILTERS.NEEDS_ATTENTION)}
            >
              All issues ({stat.totalIssues})
            </button>
            <button
              type="button"
              className={classNames("lux-acct-summary__attention-quick-btn", {
                "is-active": qualityFilter === ACCOUNT_QUALITY_FILTERS.COMPLETE,
              })}
              onClick={() => this.onQualityChip(ACCOUNT_QUALITY_FILTERS.COMPLETE)}
            >
              Complete ({stat.quality.completeRecords})
            </button>
            {qualityFilter && (
              <button
                type="button"
                className="lux-acct-summary__attention-clear"
                onClick={() => this.onQualityChip("")}
              >
                Clear filter
              </button>
            )}
          </div>
        </header>
        <div className="lux-acct-summary__attention-grid">
          {stat.attentionItems.map((item) => (
            <button
              key={item.key}
              type="button"
              className={classNames("lux-acct-summary__attention-card", `is-${item.tone}`, {
                "is-active": qualityFilter === item.filterKey,
                [`is-severity-${item.severity}`]: item.severity,
              })}
              onClick={() => this.onQualityChip(item.filterKey)}
            >
              <span className="lux-acct-summary__attention-card-icon" aria-hidden="true">
                <i className={item.icon} />
              </span>
              <div className="lux-acct-summary__attention-card-body">
                <span className="lux-acct-summary__attention-card-count">
                  <CountUp end={item.count} duration={0.7} />
                </span>
                <strong>{item.label}</strong>
                <span className="lux-acct-summary__attention-card-hint">{item.hint}</span>
                {item.samples && item.samples.length > 0 && (
                  <span className="lux-acct-summary__attention-card-samples">
                    e.g. {item.samples.join(", ")}
                    {item.count > item.samples.length ? "…" : ""}
                  </span>
                )}
              </div>
              <span className="lux-acct-summary__attention-card-pct">{item.pct}%</span>
            </button>
          ))}
        </div>
      </section>
    );
  };

  renderCoverageMeters = (stat) => {
    if (stat.isUserTeamsView) return null;
    const { coverage, typeCounts } = stat;
    const meters = [];
    if (typeCounts.ACCOUNT > 0 && coverage.accountTeamRate != null) {
      meters.push({
        key: "teams",
        label: "Accounts with teams",
        value: coverage.accountTeamRate,
        detail: `${coverage.accountsWithTeams} of ${typeCounts.ACCOUNT}`,
        tone: "sky",
      });
    }
    if (typeCounts.TEAM > 0 && coverage.teamClientRate != null) {
      meters.push({
        key: "clients",
        label: "Teams with clients",
        value: coverage.teamClientRate,
        detail: `${coverage.teamsWithClients} of ${typeCounts.TEAM}`,
        tone: "teal",
      });
    }
    if (typeCounts.CLIENT > 0 && coverage.clientEmailRate != null) {
      meters.push({
        key: "email",
        label: "Clients with email",
        value: coverage.clientEmailRate,
        detail: `${coverage.clientsWithEmail} of ${typeCounts.CLIENT}`,
        tone: "green",
      });
    }
    if (!meters.length) return null;

    return (
      <section className="lux-acct-summary__coverage" aria-label="Hierarchy coverage">
        <h3 className="lux-acct-summary__section-title">Hierarchy coverage</h3>
        <div className="lux-acct-summary__coverage-grid">
          {meters.map((m) => (
            <div key={m.key} className={classNames("lux-acct-summary__coverage-meter", `is-${m.tone}`)}>
              <div className="lux-acct-summary__coverage-top">
                <span>{m.label}</span>
                <strong>{m.value}%</strong>
              </div>
              <div className="lux-acct-summary__coverage-track" aria-hidden="true">
                <span className="lux-acct-summary__coverage-fill" style={{ width: `${m.value}%` }} />
              </div>
              <span className="lux-acct-summary__coverage-detail">{m.detail}</span>
            </div>
          ))}
        </div>
      </section>
    );
  };

  renderPlaybook = (stat) => {
    if (stat.isUserTeamsView || !stat.playbook) return null;
    return (
      <section className="lux-acct-summary__playbook" aria-label="Directory playbook">
        <h3 className="lux-acct-summary__section-title">How to use this directory</h3>
        <ol className="lux-acct-summary__playbook-list">
          {stat.playbook.map((step) => (
            <li key={step.key} className="lux-acct-summary__playbook-item">
              <span className="lux-acct-summary__playbook-step">{step.step}</span>
              <div>
                <strong>
                  <i className={step.icon} aria-hidden="true" /> {step.title}
                </strong>
                <p>{step.text}</p>
              </div>
            </li>
          ))}
        </ol>
      </section>
    );
  };

  renderInsightCard = (insight) => (
    <article key={insight.key} className="lux-acct-summary__insight">
      <header>
        <i className={insight.icon} aria-hidden="true" />
        <div>
          <strong>{insight.title}</strong>
          <span>{insight.subtitle}</span>
        </div>
      </header>
      {!insight.mix || !insight.mix.length ? (
        <div className="lux-acct-summary__bar lux-acct-summary__bar--empty">{insight.emptyLabel}</div>
      ) : (
        <>
          <div className="lux-acct-summary__bar" aria-hidden="true">
            {insight.mix.map((segment) => (
              <span
                key={segment.key || segment.label}
                className={classNames("lux-acct-summary__bar-segment", `is-${segment.tone}`)}
                style={{ width: `${Math.max(segment.pct, segment.count > 0 ? 4 : 0)}%` }}
                title={`${segment.label}: ${segment.count} (${segment.pct}%)`}
              />
            ))}
          </div>
          <ul className="lux-acct-summary__legend">
            {insight.mix.map((segment) => (
              <li key={segment.key || segment.label}>
                <span className={classNames("lux-acct-summary__legend-dot", `is-${segment.tone}`)} />
                <span className="lux-acct-summary__legend-label">{segment.label}</span>
                <strong>{segment.count}</strong>
                <span className="lux-acct-summary__legend-pct">{segment.pct}%</span>
              </li>
            ))}
          </ul>
        </>
      )}
    </article>
  );

  renderChartPanel = (
    title,
    subtitle,
    chart,
    emptyMessage,
    { height = 140, chartType = "donut", wide = false, tall = false, compact = false } = {}
  ) => (
    <article
      className={classNames("lux-acct-summary__chart-panel", {
        "lux-acct-summary__chart-panel--wide": wide,
        "lux-acct-summary__chart-panel--tall": tall,
        "lux-acct-summary__chart-panel--compact": compact,
      })}
    >
      <div className="lux-acct-summary__panel-head">
        <div>
          <h3 className="lux-acct-summary__panel-title">{title}</h3>
          <p className="lux-acct-summary__panel-sub">{subtitle}</p>
        </div>
      </div>
      <div className="lux-acct-summary__chart-body">
        {!chart && <p className="lux-acct-summary__chart-empty">{emptyMessage}</p>}
        {chart && (
          <DashboardApexChart
            type={chartType}
            series={chart.series}
            options={chart.options}
            height={height}
          />
        )}
      </div>
    </article>
  );

  renderSkeleton = () => (
    <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
      <div className="lux-acct-summary lux-acct-summary--insights is-loading">
        <Skeleton height={56} borderRadius={16} />
        <div className="lux-acct-summary__layout-skeleton">
          <Skeleton height={120} borderRadius={14} />
          <Skeleton height={200} borderRadius={14} />
          <Skeleton height={160} borderRadius={14} />
        </div>
      </div>
    </SkeletonTheme>
  );

  render() {
    const { stat, charts, visibleCount, filterOptions, isLoading, typeFilter, qualityFilter } =
      this.props;
    if (isLoading && !stat) {
      return this.renderSkeleton();
    }
    if (!stat) return null;

    const { expanded } = this.state;
    const contextLine = this.buildContextLine(stat, visibleCount, filterOptions);
    const chartData = charts || {};

    return (
      <section
        className={classNames("lux-acct-summary", "lux-acct-summary--insights", {
          "is-collapsed": !expanded,
        })}
        aria-label="Accounts directory summary"
      >
        <div className="lux-acct-summary__header-bar">
          <div className="lux-acct-summary__header-main">
            <LuxSummaryEyebrow variant="accounts" className="lux-acct-summary__eyebrow">
              Account directory intelligence
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-acct-summary__title lux-acct-summary__title--compact">
                <CountUp end={visibleCount} duration={0.6} />{" "}
                <span>
                  {stat.isUserTeamsView ? "teams" : "records"}
                  {!stat.isUserTeamsView && ` · ${stat.healthScore}% health`}
                </span>
              </h2>
            ) : (
              <h2 className="lux-acct-summary__title lux-acct-summary__title--bar">
                Directory insights &amp; data quality
              </h2>
            )}
            {contextLine && <p className="lux-acct-summary__context">{contextLine}</p>}
          </div>
          <button
            type="button"
            className="lux-acct-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-acct-summary-body"
          >
            {getSummaryToggleLabel(expanded)}
            <i className={`fe fe-chevron-${expanded ? "up" : "down"}`} aria-hidden="true" />
          </button>
        </div>

        {!expanded && (
          <div className="lux-acct-summary__collapsed-strip">
            {!stat.isUserTeamsView && this.renderFilterChips(typeFilter, true)}
          </div>
        )}

        <div id="lux-acct-summary-body" className="lux-acct-summary__body" aria-hidden={!expanded}>
          <div className="lux-acct-summary__layout">
            <div className="lux-acct-summary__layout-main">
              {this.renderHero(stat, visibleCount, filterOptions)}
              {!stat.isUserTeamsView && this.renderFilterChips(typeFilter, false)}
              {this.renderKpiStrip(stat)}
              {this.renderAttentionPanel(stat, qualityFilter)}
              {this.renderCoverageMeters(stat)}
              {this.renderHighlights(stat)}
              <div className="lux-acct-summary__insights">
                {stat.insights.map((insight) => this.renderInsightCard(insight))}
              </div>
            </div>

            <aside className="lux-acct-summary__layout-side">
              {this.renderPlaybook(stat)}
              <div className="lux-acct-summary__charts lux-acct-summary__charts--side">
                {this.renderChartPanel(
                  "Data health",
                  "Complete vs needs attention",
                  chartData.healthDonut,
                  "No records to score"
                )}
                {this.renderChartPanel(
                  "Issue breakdown",
                  "Gaps found in this view",
                  chartData.issuesBar,
                  "No quality issues — great job!",
                  { height: Math.max(160, (stat.issueMix && stat.issueMix.length) * 36), chartType: "bar", tall: true }
                )}
                {this.renderChartPanel(
                  "Record types",
                  "Accounts, teams & clients",
                  chartData.typeDonut,
                  "Open records to see mix"
                )}
                {this.renderChartPanel(
                  "Hierarchy coverage",
                  "% with teams, clients & email",
                  chartData.coverageBar,
                  "Not enough hierarchy depth",
                  { height: 150, chartType: "bar" }
                )}
              </div>
            </aside>
          </div>

          <div className="lux-acct-summary__charts lux-acct-summary__charts--triple">
            {this.renderChartPanel(
              "Data source",
              "Salesforce vs manual",
              chartData.sourceDonut,
              "No Salesforce in view",
              { compact: true }
            )}
            {this.renderChartPanel(
              "Billing type",
              "Billable split",
              chartData.billingDonut,
              "Billing type not set",
              { compact: true }
            )}
            {this.renderChartPanel(
              "Top by clients",
              "Largest nodes in view",
              chartData.topClientsBar,
              "No client counts yet",
              { height: 140, chartType: "bar", compact: true }
            )}
          </div>
        </div>
      </section>
    );
  }
}

export default AccountsPageSummary;
