import React, { Component } from "react";
import { applyLuxPalette, getLuxPaletteId, LUX_PALETTES } from "_helpers/theme.utils";

class ThemeDiv extends Component {
  constructor() {
    super();
    this.state = {
      activePalette: getLuxPaletteId(),
    };
  }

  handlePaletteSelect = (paletteId) => {
    applyLuxPalette(paletteId);
    this.setState({ activePalette: paletteId });
  }

  render() {
    const palettes = Object.values(LUX_PALETTES);
    const active = LUX_PALETTES[this.state.activePalette] || LUX_PALETTES.indigo;

    return (
      <div className="theme_div lux-theme-panel">
        <div className="lux-theme-panel__shell">
          <header className="lux-theme-panel__header">
            <div className="lux-theme-panel__header-main">
              <span className="lux-theme-panel__icon" aria-hidden="true">
                <i className="fe fe-droplet" />
              </span>
              <div className="lux-theme-panel__header-copy">
                <span className="lux-theme-panel__eyebrow">Personalization</span>
                <h3 className="lux-theme-panel__title">Color Palettes</h3>
                <p className="lux-theme-panel__subtitle">
                  Curated accent systems for navigation, actions, and focus states.
                </p>
              </div>
            </div>
            <button
              type="button"
              className="lux-theme-panel__close theme-div-close-link"
              aria-label="Close palette panel"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-theme-panel__stats">
            <span className="lux-theme-panel__stat">
              <i className="fe fe-layers" aria-hidden="true" />
              {palettes.length} palettes
            </span>
            <span className="lux-theme-panel__stat">
              <i className="fe fe-check-circle" aria-hidden="true" />
              Auto-saved
            </span>
          </div>

          <div className="lux-theme-panel__active-preview">
            <span
              className="lux-theme-panel__active-swatch"
              style={{
                background: `linear-gradient(135deg, ${active.primary}, ${active.accent})`,
              }}
              aria-hidden="true"
            />
            <div className="lux-theme-panel__active-copy">
              <span className="lux-theme-panel__active-label">Active</span>
              <strong>{active.label}</strong>
              <span className="lux-theme-panel__active-mood">{active.mood}</span>
            </div>
          </div>

          <div className="lux-theme-panel__body">
            <ul className="lux-palette-grid">
              {palettes.map((palette) => {
                const isActive = this.state.activePalette === palette.id;

                return (
                  <li key={palette.id}>
                    <button
                      type="button"
                      className={`lux-palette-card${isActive ? " is-active" : ""}`}
                      onClick={() => this.handlePaletteSelect(palette.id)}
                      aria-pressed={isActive}
                      data-ga-action="theme_palette_select"
                      data-ga-category="engagement"
                      data-ga-label={palette.label}
                    >
                      <div
                        className="lux-palette-card__swatch"
                        style={{
                          background: `linear-gradient(135deg, ${palette.primary} 0%, ${palette.accent} 100%)`,
                        }}
                      >
                        <span className="lux-palette-card__dots" aria-hidden="true">
                          <span style={{ background: palette.primarySoft }} />
                          <span style={{ background: palette.primary }} />
                          <span style={{ background: palette.accent }} />
                        </span>
                        {isActive && (
                          <span className="lux-palette-card__badge" aria-hidden="true">
                            <i className="fe fe-check" />
                          </span>
                        )}
                        {palette.darkShell && (
                          <span className="lux-palette-card__tag">Dark</span>
                        )}
                      </div>
                      <div className="lux-palette-card__copy">
                        <span className="lux-palette-card__name">{palette.label}</span>
                        <span className="lux-palette-card__desc">{palette.description}</span>
                        <span className="lux-palette-card__meta">
                          <span className="lux-palette-card__mood">{palette.mood}</span>
                          <span className="lux-palette-card__hex">{palette.primary}</span>
                        </span>
                      </div>
                    </button>
                  </li>
                );
              })}
            </ul>
          </div>

          <footer className="lux-theme-panel__footer">
            <p>Changes apply instantly across the workspace shell and persist on this device.</p>
          </footer>
        </div>
      </div>
    );
  }
}

export default ThemeDiv;
