import React, { Component } from "react";
import { connect } from "react-redux";
import { taskActions } from "_actions";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import { dashboardActions } from "_actions";
import { accessUtils } from "_helpers";
import DeliverableDetailsBackNav from "./components/DeliverableDetailsBackNav";
import DeliverableDetailsHero from "./components/DeliverableDetailsHero";
import DeliverableDetailsHeader, {
  DeliverableDetailViewNameConst,
} from "./components/DeliverableDetailsHeader";
import DeliverableDetailsGeneral from "./components/DeliverableDetailsGeneral";
import { getDeliverableBreadcrumbLabel } from "./components/deliverableDetailsTab.utils";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxDetailPageSkeleton from "views/common/fragments/LuxDetailPageSkeleton";

class TaskDetailsPage extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getTaskAccessControl(),
      deliverableDetailViewName: DeliverableDetailViewNameConst.GENERAL,
      taskId: null,
    };
  }

  resolveRouteTaskId = () =>
    commonUtils.removeNameIntial(this.props.match.params.taskId);

  loadTaskIfNeeded = () => {
    const taskId = this.resolveRouteTaskId();
    const current = this.props.taskInfo;
    const currentKey = current && (current.id === taskId || current.itemIdUserTeamPrefix === taskId);
    if (!currentKey) {
      store.dispatch(this.props.getTaskInfo(taskId));
    }
    if (this.state.taskId !== taskId) {
      this.setState({ taskId });
    }
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(
      this.props.routeProp.name + " : " + this.props.match.params.taskId
    );
    this.loadTaskIfNeeded();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.match.params.taskId !== this.props.match.params.taskId) {
      this.loadTaskIfNeeded();
    }
  }

  render() {
    const { taskInfo, isLoading } = this.props;
    const { permission } = this.state;
    const hasAccess =
      taskInfo &&
      commonUtils.hasAccess(taskInfo, permission.allowAccessToOtherUserTeamDeliverables);
    const readOnly = hasAccess ? taskInfo.deleted : true;

    return (
      <div className="pd-page lux-deliverable-details-page lux-project-details-page">
        <DeliverableDetailsBackNav
          location={this.props.location}
          taskInfo={taskInfo}
          deliverableRef={
            getDeliverableBreadcrumbLabel(taskInfo) ||
            (taskInfo && taskInfo.itemIdUserTeamPrefix)
          }
        />
        {hasAccess && (
          <>
            <DeliverableDetailsHero
              item={taskInfo}
              permission={permission}
              readOnly={readOnly}
            />
            <DeliverableDetailsHeader
              taskInfo={taskInfo}
              activeView={this.state.deliverableDetailViewName}
            />
          </>
        )}

        <div className="pd-page__body">
          {isLoading && !taskInfo && (
            <LuxDetailPageSkeleton ariaLabel="Loading deliverable" />
          )}

          {hasAccess && taskInfo && !isLoading && (
            <DeliverableDetailsGeneral
              item={taskInfo}
              readOnly={readOnly}
              permission={permission}
              workItemStatisticsByCategory={this.props.workItemStatisticsByCategory}
              getWorkItemStatisticsByCategory={
                this.props.getWorkItemStatisticsByCategory
              }
            />
          )}

          {!isLoading && !hasAccess && (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact pd-empty lux-del-empty"
              variant="deliverables"
              eyebrow="Deliverable workspace"
              title="No deliverable details found"
              description="You may not have permission to view this deliverable, or it does not exist."
              hints={[
                "Confirm the deliverable ID in the URL",
                "Open it from the project deliverables list",
                "Verify team membership and access rights",
              ]}
            />
          )}
        </div>
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  taskInfo: state.tasks.selectedTaskInfo,
  isLoading: state.tasks.loading === true,
  workItemStatisticsByCategory: state.dashboard.workItemStatisticsByCategory,
});

const mapDispatchToProps = () => ({
  getTaskInfo: taskActions.getTaskInfo,
  getWorkItemStatisticsByCategory: dashboardActions.getWorkItemStatisticsByCategory,
});

export default connect(mapStateToProps, mapDispatchToProps)(TaskDetailsPage);
