import React, { Component } from "react";
import classNames from "classnames/bind";
import { filterChatList } from "./chat.utils";

export default class ChatSidebar extends Component {
  constructor(props) {
    super(props);
    this.state = { tab: "users", search: "" };
  }

  setTab = (tab) => this.setState({ tab });

  onSearch = (e) => this.setState({ search: e.target.value });

  renderListItem = (item) => {
    const isActive = this.props.activeId === item.id;
    return (
      <button
        key={item.id}
        type="button"
        className={classNames("lux-chat-sidebar__item", {
          "is-active": isActive,
          "is-unread": item.unread > 0,
        })}
        onClick={() => this.props.onSelect && this.props.onSelect(item)}
      >
        <span className={classNames("lux-chat-sidebar__avatar", `is-${item.status}`)}>
          {item.initials}
          <span className={classNames("lux-chat-sidebar__status", item.status)} aria-hidden="true" />
        </span>
        <span className="lux-chat-sidebar__copy">
          <span className="lux-chat-sidebar__name">{item.name}</span>
          <span className="lux-chat-sidebar__preview">{item.preview}</span>
        </span>
        {item.unread > 0 && <span className="lux-chat-sidebar__badge">{item.unread}</span>}
      </button>
    );
  };

  render() {
    const { contacts, groups } = this.props;
    const { tab, search } = this.state;
    const items = filterChatList(tab === "users" ? contacts : groups, search);

    return (
      <aside className="lux-chat-sidebar" aria-label="Conversations">
        <div className="lux-chat-sidebar__tabs" role="tablist">
          <button
            type="button"
            role="tab"
            className={classNames("lux-chat-sidebar__tab", { "is-active": tab === "users" })}
            aria-selected={tab === "users"}
            onClick={() => this.setTab("users")}
          >
            <i className="fe fe-user" aria-hidden="true" /> People
          </button>
          <button
            type="button"
            role="tab"
            className={classNames("lux-chat-sidebar__tab", { "is-active": tab === "groups" })}
            aria-selected={tab === "groups"}
            onClick={() => this.setTab("groups")}
          >
            <i className="fe fe-users" aria-hidden="true" /> Groups
          </button>
        </div>
        <div className="lux-chat-sidebar__search">
          <i className="fe fe-search" aria-hidden="true" />
          <input
            type="search"
            placeholder="Search conversations…"
            value={search}
            onChange={this.onSearch}
            aria-label="Search conversations"
          />
        </div>
        <div className="lux-chat-sidebar__list" role="list">
          {items.map((item) => this.renderListItem(item))}
        </div>
      </aside>
    );
  }
}
