export function formatRegisterFetchError(error) {
  if (!error) {
    return "Something went wrong while loading data. Please try again.";
  }
  if (typeof error === "string") {
    return error;
  }
  if (error.message && typeof error.message === "string") {
    return error.message;
  }
  if (error.errorMessage && typeof error.errorMessage === "string") {
    return error.errorMessage;
  }
  if (error.error && typeof error.error === "string") {
    return error.error;
  }
  return "Something went wrong while loading data. Please try again.";
}

export function shouldShowRegisterFetchError({ error, isLoading, items }) {
  if (!error || isLoading) {
    return false;
  }
  if (items == null) {
    return true;
  }
  return Array.isArray(items) ? items.length === 0 : false;
}
