import { commonUtils } from "_helpers";

/** Canonical bid status key (INPROGRESS, IN_PROGRESS, IN PROGRESS, etc.). */
export const normalizeBidRequestStatus = commonUtils.normalizeBidRequestStatus;

export const isBidInProgressStatus = commonUtils.isBidInProgressStatus;

/** Value for status dropdown when API returns IN PROGRESS / IN_PROGRESS variants. */
export function getBidStatusSelectValue(status) {
  return isBidInProgressStatus(status) ? "INPROGRESS" : status;
}

export const BID_STATUS_META = {
  NEW: { label: "New", tone: "sky" },
  ASSIGNED: { label: "Assigned", tone: "indigo" },
  INPROGRESS: { label: "In progress", tone: "amber" },
  WON: { label: "Won", tone: "green" },
  LOST: { label: "Lost", tone: "slate" },
  CANCELLED: { label: "Cancelled", tone: "rose" },
  REJECTED: { label: "Rejected", tone: "slate" },
  CLOSED: { label: "Closed", tone: "slate" },
};

export const BID_TYPE_LABELS = {
  ADHOC: "Adhoc",
  FTEMS: "FTE–MS",
  FTESA: "FTE–Staff aug",
  SERVICES: "Services",
  PRODUCT: "Product",
  TRACKER: "Tracker",
  TMHB: "T&M hourly",
};

export const BID_TYPE_TONES = {
  ADHOC: "indigo",
  FTEMS: "violet",
  FTESA: "sky",
  SERVICES: "amber",
  PRODUCT: "teal",
  TRACKER: "green",
  TMHB: "slate",
};

export function getBidStatusMeta(status) {
  const key = normalizeBidRequestStatus(status);
  return BID_STATUS_META[key] || { label: status || "—", tone: "slate" };
}

export function getBidTypeLabel(type) {
  return (type && BID_TYPE_LABELS[type]) || type || "—";
}

export function getBidTypeTone(type) {
  return (type && BID_TYPE_TONES[type]) || "slate";
}
