import React from "react";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import ItemChecklistInput from "./fragments/ItemChecklistInput";
import { LuxDelTimelineStep } from "./DeliverableLuxBlocks";

export default function DeliverableDetailsRightRail({
  item,
  readOnly,
  permission,
  onUpdateChecklist,
}) {
  if (!item) return null;

  return (
    <aside className="pd-workspace__aside lux-del-rail" aria-label="Timeline and checklist">
      <header className="lux-del-rail__head">
        <span className="lux-del-rail__eyebrow">Delivery context</span>
        <p className="lux-del-rail__hint">Schedule, effort, and checklist</p>
      </header>

      <section className="lux-del-aside-card">
        <header className="lux-del-aside-card__head">
          <span className="lux-del-aside-card__icon" aria-hidden="true">
            <i className="fe fe-clock" />
          </span>
          <h2 className="lux-del-aside-card__title">Timeline</h2>
        </header>
        <div className="lux-del-aside-card__body">
          <div className="lux-del-timeline">
            <LuxDelTimelineStep
              label="Start"
              value={dateUtils.convertDateFormat(item.estStartTime)}
              active
            />
            <LuxDelTimelineStep
              label="Due"
              value={dateUtils.convertDateFormat(item.estCompletionTime)}
              active={item.status === "INPROGRESS" || item.status === "ASSIGNED"}
            />
            <LuxDelTimelineStep
              label="Est. duration"
              value={
                item.estDurationMins
                  ? `${dateUtils.minuteToHourString(item.estDurationMins)} (hrs)`
                  : "—"
              }
            />
            <LuxDelTimelineStep
              label="Created"
              value={dateUtils.convertDateTimeFormat(item.createdDate)}
            />
            {item.lastModifiedDate && (
              <LuxDelTimelineStep
                label="Last updated"
                value={dateUtils.convertDateTimeFormat(item.lastModifiedDate)}
              />
            )}
          </div>
          <div className="lux-del-meta-list">
            {item.createdByDetails && (
              <div className="lux-del-meta-list__row">
                <span>Created by</span>
                <strong>{item.createdByDetails.name}</strong>
              </div>
            )}
            {item.updatedByDetails && (
              <div className="lux-del-meta-list__row">
                <span>Updated by</span>
                <strong>{item.updatedByDetails.name}</strong>
              </div>
            )}
            {item.ownerDetails && (
              <div className="lux-del-meta-list__row">
                <span>Delivery lead</span>
                <strong>{item.ownerDetails.name}</strong>
              </div>
            )}
          </div>
        </div>
      </section>

      {permission.checklistEnabled && (
        <section className="lux-del-aside-card">
          <header className="lux-del-aside-card__head">
            <span className="lux-del-aside-card__icon" aria-hidden="true">
              <i className="fe fe-check-square" />
            </span>
            <h2 className="lux-del-aside-card__title">Checklist</h2>
          </header>
          <div className="lux-del-aside-card__body lux-del-aside-card__body--checklist">
            <ItemChecklistInput
              handleUpdateChecklist={onUpdateChecklist}
              type="TASK"
              readOnly={readOnly}
              permission={permission}
              checklistData={item.checklistData}
              itemUserTeamId={item.userTeamId}
            />
          </div>
        </section>
      )}
    </aside>
  );
}
