export function getTemplateEditorMode(feedbackTemplateRequest, editMode) {
  const req = feedbackTemplateRequest || {};
  if (!req.id && editMode) {
    return {
      id: "create",
      kicker: "Draft workspace",
      title: "Creating new template",
      subtitle: "Define type, name, and questions — then save to share with your team.",
      tone: "create",
      icon: "fe-plus-circle",
    };
  }
  if (req.id && editMode) {
    return {
      id: "edit",
      kicker: "Editing template",
      title: req.name || "Untitled template",
      subtitle: "Update details, access, and questions. Changes apply to future campaigns.",
      tone: "edit",
      icon: "fe-edit-2",
    };
  }
  if (req.id) {
    return {
      id: "preview",
      kicker: "Read-only preview",
      title: req.name || "Untitled template",
      subtitle: "Review structure before editing or sending feedback campaigns.",
      tone: "preview",
      icon: "fe-eye",
    };
  }
  return {
    id: "idle",
    kicker: "Template library",
    title: "Select or create a template",
    subtitle: "Pick a template from the list or start a new one for this item type.",
    tone: "idle",
    icon: "fe-layers",
  };
}

export function resolveOptionLabel(options, value) {
  if (!value || !options || !options.length) return null;
  const match = options.find((o) => o.value === value);
  return match ? match.label : value;
}

export function getRestrictedTeamCount(restrictedByUserTeamIds) {
  if (!restrictedByUserTeamIds) return 0;
  if (Array.isArray(restrictedByUserTeamIds)) return restrictedByUserTeamIds.length;
  return 1;
}
