import React, { Component } from "react";
import LoadingButton from "views/common/fragments/LoadingButton";

class LuxWorkItemCreateFooter extends Component {
  constructor(props) {
    super(props);
    this.state = { createAnotherEnabled: false };
  }

  onCreateAnotherChange = (checked) => {
    this.setState({ createAnotherEnabled: checked });
  };

  render() {
    const {
      editMode,
      hasFormError,
      onResetFormError,
      handleSubmit,
      onClose,
      isProcessing,
      assigneeLabel,
      hoursLabel,
    } = this.props;
    const { createAnotherEnabled } = this.state;
    const submitLabel = editMode ? "Update work item" : "Create work item";
    const loadingLabel = editMode ? "Updating…" : "Creating…";

    return (
      <footer className="lux-planner-assign-footer lux-create-footer lux-workitem-create-footer">
        {hasFormError && (
          <div className="lux-create-footer__alert" role="alert">
            <i className="fe fe-alert-triangle" aria-hidden="true" />
            <span>Complete required fields before saving.</span>
            <button
              type="button"
              className="lux-create-footer__alert-dismiss"
              onClick={onResetFormError}
              aria-label="Dismiss"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </div>
        )}

        <div className="lux-planner-assign-footer__summary">
          <div className="lux-planner-assign-footer__summary-main">
            {hoursLabel ? (
              <div className="lux-planner-assign-footer__stat">
                <span className="lux-planner-assign-footer__stat-label">Duration</span>
                <strong>{hoursLabel}</strong>
              </div>
            ) : (
              <p className="lux-planner-assign-footer__empty">
                Enter a name, assignee, and schedule to log work on this deliverable.
              </p>
            )}
          </div>
          {assigneeLabel && (
            <div className="lux-planner-assign-footer__context">
              <span>
                <i className="fe fe-user" aria-hidden="true" /> {assigneeLabel}
              </span>
            </div>
          )}
        </div>

        <div className="lux-create-footer__bar lux-planner-assign-footer__bar">
          {!editMode && (
            <label className="lux-workitem-create-footer__keep">
              <input
                type="checkbox"
                checked={createAnotherEnabled}
                onChange={(e) => this.onCreateAnotherChange(e.target.checked)}
              />
              <span>Keep panel open after create</span>
            </label>
          )}
          <p className="lux-planner-assign-footer__hint">
            {editMode
              ? "Update this work item while staying within the deliverable schedule window."
              : "New work items are linked to the deliverable shown above."}
          </p>
          <div className="lux-create-footer__actions">
            <button
              type="button"
              className="lux-create-footer__btn lux-create-footer__btn--ghost"
              onClick={() => onClose(false)}
              disabled={isProcessing}
            >
              <i className="fe fe-x" aria-hidden="true" /> Close
            </button>
            <LoadingButton
              isLoading={isProcessing}
              loadingText={loadingLabel}
              variant="primary"
              size="sm"
              className="lux-create-footer__submit lux-planner-assign-footer__submit"
              onClick={() => handleSubmit(createAnotherEnabled)}
            >
              <i className="fe fe-check-circle" aria-hidden="true" /> {submitLabel}
            </LoadingButton>
          </div>
        </div>
      </footer>
    );
  }
}

export default LuxWorkItemCreateFooter;
