import React, { Component } from "react";
import LuxListCountSkeleton from "views/common/fragments/LuxListCountSkeleton";
import LuxRegisterListSkeletonRows from "views/common/fragments/LuxRegisterListSkeletonRows";
import classNames from "classnames/bind";
import BidRequestsInfoLine from "./BidRequestsInfoLine";
import LuxRegisterPagination from "views/common/fragments/LuxRegisterPagination";
import { REGISTER_PAGE_SIZE_OPTIONS } from "_helpers/registerPagination.utils";

const LIST_COLUMNS = [
  { key: "id", label: "Ref", icon: "fe-hash" },
  { key: "created", label: "Created", icon: "fe-calendar" },
  { key: "study", label: "Study", icon: "fe-file-text" },
  { key: "studyType", label: "TG", icon: "fe-target", center: true },
  { key: "sfId", label: "SF ID", icon: "fe-tag" },
  { key: "kind", label: "Kind", icon: "fe-book-open" },
  { key: "countries", label: "Geo", icon: "fe-globe" },
  { key: "status", label: "Update status", icon: "fe-activity", center: true },
  { key: "actions", label: "", icon: null, center: true },
];

class BidRequestsListTable extends Component {

  render() {
    const count =
      this.props.totalCount != null
        ? this.props.totalCount
        : this.props.items
        ? this.props.items.length
        : 0;

    return (
      <div className="lux-bid-list-shell">
        <div className="lux-bid-list-shell__bar">
          <span className="lux-bid-list-shell__label">
            <i className="fe fe-list" aria-hidden="true" />
            Bid register
          </span>
          <span className="lux-bid-list-shell__count">
            {this.props.isLoading ? <LuxListCountSkeleton /> : `${count} record${count === 1 ? "" : "s"}`}
          </span>
        </div>

        <div className="lux-bid-list" aria-label="Bid requests list">
          <div className="lux-bid-list__head" role="row">
            {LIST_COLUMNS.map((col) => (
              <div
                key={col.key}
                className={[
                  "lux-bid-list__head-cell",
                  `lux-bid-list__head-cell--${col.key}`,
                  col.center ? "is-center" : "",
                ]
                  .filter(Boolean)
                  .join(" ")}
                role="columnheader"
              >
                {col.icon ? (
                  <span className="lux-bid-list__head-label">
                    <i className={`fe ${col.icon}`} aria-hidden="true" />
                    {col.label}
                  </span>
                ) : (
                  <span className="lux-bid-list__head-label lux-bid-list__head-label--sr">
                    Actions
                  </span>
                )}
              </div>
            ))}
          </div>

          <div
            className={classNames("lux-bid-list__body", { "is-loading": this.props.isLoading })}
            role="list"
          >
            {this.props.isLoading && (
              <LuxRegisterListSkeletonRows
                variant="bid"
                pageSize={this.props.pagination && this.props.pagination.pageSize}
              />
            )}
            {!this.props.isLoading &&
              this.props.items &&
              this.props.items.map((item) => (
                <BidRequestsInfoLine
                  item={item}
                  key={item.id}
                  handleDeleteBidRequests={this.props.handleDeleteBidRequests}
                  handleEditBidRequests={this.props.handleEditBidRequests}
                  handleUpdateStatus={this.props.handleUpdateStatus}
                  handleDuplicateBidRequests={this.props.handleDuplicateBidRequests}
                  onViewBidRequests={this.props.onViewBidRequests}
                  handleArchiveBidRequests={this.props.handleArchiveBidRequests}
                  handleRemoveBidRequests={this.props.handleRemoveBidRequests}
                  permission={this.props.permission}
                />
              ))}
          </div>
        </div>

        {this.props.pagination && !this.props.isLoading && this.props.pagination.total > 0 && (
          <LuxRegisterPagination
            pagination={this.props.pagination}
            onPageChange={this.props.onPageChange}
            onPageSizeChange={this.props.onPageSizeChange}
            pageSizeOptions={REGISTER_PAGE_SIZE_OPTIONS}
            summaryLabel={this.props.paginationSummaryLabel || "bids"}
            className="lux-register-list__pagination"
          />
        )}
      </div>
    );
  }
}

export default BidRequestsListTable;
