import React, { Component } from "react";
import { connect } from "react-redux";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import LuxCreateFieldGroup, { LuxCreateField } from "views/common/create/LuxCreateFieldGroup";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import LuxCreateFooter from "views/common/create/LuxCreateFooter";
import { validationUtils } from "_helpers";
import { commonUtils } from "_helpers";

const VIEW_META = {
  ACCOUNTS: {
    icon: "fe-layers",
    label: "account",
    badge: "Account",
    hint: "Add a billable node to your hierarchy — link teams, clients, and Salesforce when ready.",
  },
  ACCOUNT: {
    icon: "fe-layers",
    label: "account",
    badge: "Account",
    hint: "Add a billable node to your hierarchy — link teams, clients, and Salesforce when ready.",
  },
  TEAM: {
    icon: "fe-users",
    label: "team",
    badge: "Team",
    hint: "Group work under a team shell before attaching accounts and clients.",
  },
  CLIENT: {
    icon: "fe-briefcase",
    label: "client",
    badge: "Client",
    hint: "Capture the client contact surface — email helps invoicing and notifications.",
  },
};

class CreateAccountModal extends Component {
  constructor() {
    super();
    this.state = {
      isNewItemSelected: true,
      accountsRequest: {},
      formErrors: {},
      hasFormError: false,
    };
  }

  componentDidUpdate(prevProps) {
    if (prevProps.show && !this.props.show) {
      this.resetForm();
    }
  }

  resetForm = () => {
    this.setState({
      accountsRequest: {},
      formErrors: {},
      hasFormError: false,
      isNewItemSelected: true,
    });
  };

  onFormError = (fieldName, hasError) => {
    this.setState((prevState) => ({
      formErrors: { ...prevState.formErrors, [fieldName]: hasError },
    }));
  };

  onResetFormError = () => {
    this.setState({ hasFormError: false });
  };

  onNewItemSelected = (isNewItemSelected) => {
    this.setState({ isNewItemSelected });
  };

  onChange = (fieldName, value) => {
    this.onResetFormError();
    if (fieldName === "name") {
      this.setState((prevState) => ({
        isNewItemSelected: true,
        accountsRequest: {
          allowOnlyForUserTeams: [
            (this.props.selectedUserTeamItem && this.props.selectedUserTeamItem.id) ||
              commonUtils.getCurrentUserTeamId(),
          ],
          parentItems: [
            (this.props.selectedParentItem && this.props.selectedParentItem.id) ||
              commonUtils.getCurrentUserTeamId(),
          ],
          type: this.props.viewName === "ACCOUNTS" ? "ACCOUNT" : this.props.viewName,
          [fieldName]: value,
        },
      }));
    } else {
      this.setState((prevState) => ({
        accountsRequest: { ...prevState.accountsRequest, [fieldName]: value },
      }));
    }
  };

  onCreateSelectChange = (fieldName, selectedOption) => {
    this.setState({ accountsRequest: { ...selectedOption } });
  };

  submitCallBackFunction = () => {
    this.setState({ accountsRequest: {} });
  };

  handleSubmit = (createAnotherEnabled) => {
    const isValidForm = validationUtils.isValidRequest(
      this.props.fieldConfig,
      this.state.accountsRequest,
      this.state.formErrors
    );
    if (isValidForm) {
      this.props.handleSubmit(
        this.state.accountsRequest,
        this.state.isNewItemSelected,
        createAnotherEnabled,
        this.submitCallBackFunction
      );
      if (!createAnotherEnabled) {
        this.props.closeActionHandler();
      }
    } else {
      this.setState({ hasFormError: true });
    }
  };

  getContextChips = () => {
    const parent = this.props.selectedParentItem;
    const team = this.props.selectedUserTeamItem;
    const chips = [];
    if (team && team.name) {
      chips.push({ icon: "fe-users", label: team.name });
    }
    if (parent && parent.name && (!team || parent.name !== team.name)) {
      chips.push({ icon: "fe-folder", label: parent.name });
    }
    return chips;
  };

  getViewMeta = (viewName) => VIEW_META[viewName] || VIEW_META.ACCOUNTS;

  renderSection = (icon, title, hint, children) => (
    <section className="lux-create-section">
      <header className="lux-create-section__head">
        <span className="lux-create-section__icon" aria-hidden="true">
          <i className={`fe ${icon}`} />
        </span>
        <div>
          <h3 className="lux-create-section__title">{title}</h3>
          <p className="lux-create-section__hint">{hint}</p>
        </div>
      </header>
      <div className="lux-create-section__body lux-create-form">{children}</div>
    </section>
  );

  renderContextRow = () => {
    const contextChips = this.getContextChips();
    if (contextChips.length === 0 && this.state.isNewItemSelected) {
      return null;
    }
    return (
      <div className="lux-create-panel__context-row">
        {contextChips.map((chip) => (
          <span key={chip.label} className="lux-create-panel__context-chip" title={chip.label}>
            <i className={`fe ${chip.icon}`} aria-hidden="true" />
            {chip.label}
          </span>
        ))}
        {!this.state.isNewItemSelected && (
          <span className="lux-create-panel__context-chip is-accent">
            <i className="fe fe-link" aria-hidden="true" />
            Linking existing record
          </span>
        )}
      </div>
    );
  };

  renderForm = () => {
    const { viewName } = this.props;
    const isAccountType = viewName === "ACCOUNT" || viewName === "ACCOUNTS";
    const isClientType = viewName === "CLIENT";

    return (
      <>
        {this.renderContextRow()}
        {this.renderSection(
          "fe-user",
          "Essentials",
          "Name and owner anchor this record in the directory.",
          <LuxCreateFieldGroup columns={2}>
            <LuxCreateField>
              <CustomInput
                type="createselect"
                label="Name"
                name="name"
                fieldConfig={this.props.fieldConfig}
                mappingObject={this.state.accountsRequest}
                onChange={this.onChange}
                onCreateSelectChange={this.onCreateSelectChange}
                onNewItemSelected={this.onNewItemSelected}
                placeholder="Search or type a name…"
                onFormError={this.onFormError}
                options={
                  this.props.subAccountItems &&
                  commonUtils.convertObjectToSelectObject(this.props.subAccountItems)
                }
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                type="select"
                label="Owner"
                name="poc"
                fieldConfig={this.props.fieldConfig}
                mappingObject={this.state.accountsRequest}
                onChange={this.onChange}
                placeholder="Assign owner…"
                options={
                  this.props.allEmployees &&
                  commonUtils.convertObjectToSelectObject(this.props.allEmployees)
                }
                onFormError={this.onFormError}
              />
            </LuxCreateField>
          </LuxCreateFieldGroup>
        )}

        {this.renderSection(
          "fe-file-text",
          "Profile",
          "Notes and commercial details visible across the account tree.",
          <LuxCreateFieldGroup columns={2}>
            <LuxCreateField>
              <CustomInput
                type="textarea"
                label="Description"
                name="description"
                height="44px"
                fieldConfig={this.props.fieldConfig}
                mappingObject={this.state.accountsRequest}
                onChange={this.onChange}
                placeholder="Context, scope, or billing notes…"
                onFormError={this.onFormError}
                datatype="alpnumspl"
              />
            </LuxCreateField>
            {isClientType && (
              <LuxCreateField>
                <CustomInput
                  inputtype="text"
                  label="Client email"
                  name="email"
                  fieldConfig={this.props.fieldConfig}
                  mappingObject={this.state.accountsRequest}
                  onChange={this.onChange}
                  onFormError={this.onFormError}
                  placeholder="name@company.com"
                  datatype="email"
                />
              </LuxCreateField>
            )}
            {isAccountType && (
              <LuxCreateField>
                <CustomInput
                  type="select"
                  label="Billing type"
                  name="itemType"
                  fieldConfig={this.props.fieldConfig}
                  mappingObject={this.state.accountsRequest}
                  onChange={this.onChange}
                  placeholder="Select billing…"
                  options={[
                    { value: "BILLABLE", label: "Billable" },
                    { value: "NON_BILLABLE", label: "Non billable" },
                  ]}
                  onFormError={this.onFormError}
                />
              </LuxCreateField>
            )}
            {isAccountType && (
              <LuxCreateField span="full">
                <CustomInput
                  inputtype="text"
                  label="Salesforce account ID"
                  name="extAccountId"
                  fieldConfig={this.props.fieldConfig}
                  mappingObject={this.state.accountsRequest}
                  onChange={this.onChange}
                  onFormError={this.onFormError}
                  placeholder="Optional — e.g. 001XXXXXXXXXXXX"
                  datatype="alpnumspl"
                />
              </LuxCreateField>
            )}
          </LuxCreateFieldGroup>
        )}

        <LuxCreateFooter
          hasFormError={this.state.hasFormError}
          onResetFormError={this.onResetFormError}
          handleSubmit={this.handleSubmit}
          initializeRequest={this.resetForm}
          createButtonLabel={`${this.state.isNewItemSelected ? "Create" : "Add"} ${
            this.getViewMeta(viewName).label
          }`}
        />
      </>
    );
  };

  render() {
    const { show, viewName, closeActionHandler } = this.props;
    const meta = this.getViewMeta(viewName);
    const actionLabel = this.state.isNewItemSelected ? "Create" : "Add";

    return (
      <LuxCreatePanelShell
        show={show === true}
        onClose={closeActionHandler}
        panelId="createaccountmodal"
        className="lux-create-panel--accounts create_accounts_right_sidebar"
        kicker="Account directory"
        title={`${actionLabel} ${meta.label}`}
        subtitle={meta.hint}
      >
        {show === true && this.renderForm()}
      </LuxCreatePanelShell>
    );
  }
}

const mapStateToProps = (state) => ({
  fieldConfig: state.accounts.fieldConfig,
  allEmployees: state.employees.allEmployees,
  subAccountItems: state.accounts.subAccountItems,
});

export default connect(mapStateToProps)(CreateAccountModal);
