import React from "react";
import classNames from "classnames/bind";
import { getUnassignedWorkItems } from "../plannerAssign.utils";
import { formatPlannerHours } from "../planner.utils";

export default function PlannerAssignTray({ workItems, open, onToggle, canAssign }) {
  if (!canAssign) return null;

  const unassigned = getUnassignedWorkItems(workItems);

  return (
    <aside
      className={classNames("lux-planner-assign-tray", { "is-collapsed": !open })}
      aria-label="Unassigned work"
    >
      <header className="lux-planner-assign-tray__head">
        <div>
          <strong>Unassigned</strong>
          <span>{unassigned.length} item{unassigned.length === 1 ? "" : "s"}</span>
        </div>
        <button type="button" className="lux-planner-assign-tray__toggle" onClick={onToggle}>
          <i className={`fe fe-chevron-${open ? "down" : "up"}`} />
        </button>
      </header>
      {open && (
        <div className="lux-planner-assign-tray__list">
          {unassigned.length === 0 ? (
            <p className="lux-planner-assign-tray__empty">All work has an owner in this horizon.</p>
          ) : (
            unassigned.map((item) => (
              <div
                key={item.id}
                className="lux-planner-assign-tray__card"
                draggable
                onDragStart={(e) => {
                  e.dataTransfer.setData("application/x-planner-workitem", String(item.id));
                  e.dataTransfer.setData("text/plain", String(item.id));
                  e.dataTransfer.effectAllowed = "move";
                }}
              >
                <span className="lux-planner-assign-tray__grip" aria-hidden>
                  <i className="fe fe-menu" />
                </span>
                <div className="lux-planner-assign-tray__card-body">
                  <strong>{item.name || item.taskName || item.taskActCategory || "Work item"}</strong>
                  <span>{item.projectName || "No project"}</span>
                  <em>{formatPlannerHours(item.estDurationInMins || 60)}</em>
                </div>
              </div>
            ))
          )}
          <p className="lux-planner-assign-tray__hint">Drag onto a green cell to assign. Conflicts are flagged before save.</p>
        </div>
      )}
    </aside>
  );
}
