import moment from 'moment';
import React, { Component } from 'react'
import { calendarUtils } from '_helpers/calendar.utils';
import classNames from 'classnames/bind';
import dateUtils from '_helpers/date.utils';

class Calendar extends Component {
    constructor(props) {
        super(props)
        this.state = {
            selectedDates: props.selectedDates || [dateUtils.getCurrentTime()],
            viewMonthDate: props.viewMonthDate || dateUtils.getCurrentTime(),
            view: "days",
        }
    }

    componentDidUpdate(prevProps) {
        if (this.props.selectedDates && this.props.selectedDates !== prevProps.selectedDates) {
            this.setState({ selectedDates: this.props.selectedDates });
        }
        if (this.props.viewMonthDate && prevProps.viewMonthDate && !this.props.viewMonthDate.isSame(prevProps.viewMonthDate, "month")) {
            this.setState({ viewMonthDate: this.props.viewMonthDate });
        } else if (this.props.viewMonthDate && !prevProps.viewMonthDate) {
            this.setState({ viewMonthDate: this.props.viewMonthDate });
        }
    }

    getSelectedDates = () => (this.props.selectedDates || this.state.selectedDates);

    getViewMonthDate = () => (this.props.viewMonthDate || this.state.viewMonthDate);

    goToBackMonth = (type) => {
        let viewMonthDate = dateUtils.substractXFromMoments(this.getViewMonthDate(), type, 1);
        if (!this.props.viewMonthDate) {
            this.setState({ viewMonthDate });
        }
        this.props.onCalendarViewDate(viewMonthDate);
    };

    goToNextMonth = (type) => {
        let viewMonthDate = dateUtils.addXToMoments(this.getViewMonthDate(), type, 1);
        if (!this.props.viewMonthDate) {
            this.setState({ viewMonthDate });
        }
        this.props.onCalendarViewDate(viewMonthDate);
    };

    goToCurrent = () => {
        const today = dateUtils.getCurrentTime();
        if (!this.props.viewMonthDate) {
            this.setState({ viewMonthDate: today });
        }
        this.props.onCalendarViewDate(today);
    };

    onDateSelect = (selectedDate) => {
        const selectedDates = [selectedDate];
        if (!this.props.selectedDates) {
            this.setState({ selectedDates });
        }
        this.props.onSelectedDateChange(selectedDates);
    }

    onWeekDatesSelect = (selectedDates) => {
        const dates = selectedDates.map(selectedDate => selectedDate.date);
        if (!this.props.selectedDates) {
            this.setState({ selectedDates: dates });
        }
        this.props.onSelectedDateChange(dates);
    }

    onMonthDatesSelect = (weekByWeekOftheMonth) => {
        let selectedDates = []
        weekByWeekOftheMonth.map(weekDates => weekDates.weekDates.map(selectedDate => { if (selectedDate.isCurrentMonth) { selectedDates.push(selectedDate.date) } }))
        if (!this.props.selectedDates) {
            this.setState({ selectedDates });
        }
        this.props.onSelectedDateChange(selectedDates);
    }

    renderCalendarTable = (weekByWeekOftheMonth, selectedDates) => (
        <table className="table table-calendar table-bordered">
            <tbody>
                <tr>
                    <th className="text-muted bgcolorlightgray fsize9">Week</th>
                    <th>Mo</th>
                    <th>Tu</th>
                    <th>We</th>
                    <th>Th</th>
                    <th>Fr</th>
                    <th>Sa</th>
                    <th>Su</th>
                </tr>
                <CalendarView
                    datesByWeekList={weekByWeekOftheMonth}
                    selectedDates={selectedDates}
                    holidayItems={this.props.holidayItems}
                    complatedTaskItems={this.props.complatedTaskItems}
                    onDateSelect={this.onDateSelect}
                    onWeekDatesSelect={this.onWeekDatesSelect}
                />
            </tbody>
        </table>
    );

    render() {
        const viewMonthDate = this.getViewMonthDate();
        const selectedDates = this.getSelectedDates();
        let weekByWeekOftheMonth = calendarUtils.getWeekByWeekOftheMonth(viewMonthDate);

        if (this.props.embedded) {
            return (
                <div className={classNames("lux-activity-calendar-embed", this.props.className)}>
                    <div className="lux-activity-calendar-embed__head">
                        <button type="button" className="lux-activity-calendar-embed__title link" onClick={() => { this.onMonthDatesSelect(weekByWeekOftheMonth) }}>
                            {viewMonthDate.format(dateUtils.DATE_MONTH_FORMAT)}
                        </button>
                        <div className="lux-activity-calendar-embed__nav">
                            <button type="button" className="link" onClick={() => this.goToBackMonth("months")} aria-label="Previous month"><i className="fa fa-angle-double-left fa-lg" /></button>
                            <button type="button" className="link" onClick={this.goToCurrent} aria-label="Today"><i className="fa fa-home" /></button>
                            <button type="button" className="link" onClick={() => this.goToNextMonth("months")} aria-label="Next month"><i className="fa fa-angle-double-right fa-lg" /></button>
                        </div>
                    </div>
                    {this.renderCalendarTable(weekByWeekOftheMonth, selectedDates)}
                </div>
            );
        }

        return (
            <div className={classNames("card", this.props.className)}>
                <div className="card-header mt-0 pt-0">
                    <button className="card-title link" onClick={() => { this.onMonthDatesSelect(weekByWeekOftheMonth) }}>{viewMonthDate.format(dateUtils.DATE_MONTH_FORMAT)}</button>
                    <div className="card-options">
                        <div className="card-options">
                            <button className="link mr-2" onClick={() => this.goToBackMonth("months")}><i className="fa fa-angle-double-left fa-lg" /></button>
                            <button className="link mr-2 " onClick={this.goToCurrent}><i className="fa fa-home" /></button>
                            <button className="link " onClick={() => this.goToNextMonth("months")}><i className="fa fa-angle-double-right fa-lg" /></button>
                        </div>
                    </div>
                </div>
                <div className="card-body p-0">
                    {this.renderCalendarTable(weekByWeekOftheMonth, selectedDates)}
                </div>
            </div>)
    }
}

class CalendarView extends Component {

    isSelectedDate = (thisDate) => {
        return this.props.selectedDates.some(selectedDate => selectedDate.date() === thisDate.date() && selectedDate.month() === thisDate.month());
    }

    isHoliday = (thisDate) => {
        return this.props.holidayItems && this.props.holidayItems.some(holidayItem => holidayItem.holidayDate.substring(0, holidayItem.holidayDate.indexOf("T")) === thisDate.format(dateUtils.DATE_PICKER_FORMAT));
    }

    getTaskMark = (thisDate) => {
        // return "green";
        //let currentTask = this.props.complatedTaskItems && this.props.complatedTaskItems.filter(completedTaskItem => completedTaskItem.actualStartTime.substring(0, completedTaskItem.actualStartTime.indexOf("T")) === thisDate.format(dateUtils.DATE_PICKER_FORMAT));
    }

    render() {
        return (
            <>
                {this.props.datesByWeekList.map((weekListItem) =>
                    <tr key={weekListItem.weekNumber}>
                        <td onClick={() => this.props.onWeekDatesSelect(weekListItem.weekDates)} className="text-muted bgcolorlightgray fsize14 fweight600">{weekListItem.weekNumber}</td>
                        {weekListItem.weekDates.map((date, index) =>
                            <td key={date.dayNumber + "-" + index} onClick={() => this.props.onDateSelect(date.date)} className={classNames("", { "holiday": this.isHoliday(date.date) }, { "active": this.isSelectedDate(date.date) }, { "text-muted notcurrentmonth": !date.isCurrentMonth }, { "fweight600": date.isCurrentMonth }, { "weekend": index === 5 || index === 6 }, { "currentDay": date.isCurrentDate })}>
                                <span className={"marked " + (this.getTaskMark(date.date) || '')}>{date.dayNumber}</span>
                            </td>
                        )}
                    </tr>

                )}
            </>
        )
    }
}

export default Calendar;
